"use client";

import * as React from "react";
import { Check, Clock, RotateCcw, Square, X, ChevronRight, CircleDashed } from "lucide-react";
import { cn } from "../../lib/cn";
import { Spinner } from "../ui/spinner";
import { Tabs } from "../ui/tabs";
import { Button } from "../ui/button";
import { RelativeTime } from "./relative-time";

/**
 * AgentRuns
 * Background agent jobs: what's running, what finished, what failed — with time, cost and
 * one-click Stop / Retry. Running jobs show live progress; failures show why.
 */
export type RunStatus = "queued" | "running" | "completed" | "failed" | "stopped";
export interface AgentRun { id: string; title: string; status: RunStatus; startedAt: Date; durationSec?: number; progress?: number; step?: string; cost?: number; error?: string }

export interface AgentRunsProps {
  runs: AgentRun[];
  onStop?: (id: string) => void;
  onRetry?: (id: string) => void;
  onOpen?: (id: string) => void;
  className?: string;
}

const statusUI: Record<RunStatus, { icon: React.ReactNode; label: string; cls: string }> = {
  queued: { icon: <CircleDashed className="size-4" />, label: "Queued", cls: "text-fg-subtle" },
  running: { icon: <Spinner className="size-4" />, label: "Running", cls: "text-info" },
  completed: { icon: <Check className="size-4" />, label: "Completed", cls: "text-success" },
  failed: { icon: <X className="size-4" />, label: "Failed", cls: "text-danger" },
  stopped: { icon: <Square className="size-3.5" />, label: "Stopped", cls: "text-fg-muted" },
};
const dur = (s?: number) => (s == null ? "" : s < 60 ? `${s}s` : `${Math.floor(s / 60)}m ${s % 60}s`);

export function AgentRuns({ runs, onStop, onRetry, onOpen, className }: AgentRunsProps) {
  const [filter, setFilter] = React.useState("all");
  const count = (s: RunStatus[]) => runs.filter((r) => s.includes(r.status)).length;
  const shown = runs.filter((r) => filter === "all" || (filter === "active" ? ["running", "queued"].includes(r.status) : filter === "done" ? r.status === "completed" : ["failed", "stopped"].includes(r.status)));
  return (
    <div className={cn("overflow-hidden rounded-lg border border-border bg-bg", className)}>
      <div className="px-4 pt-2">
        <Tabs
          size="sm"
          value={filter}
          onValueChange={setFilter}
          items={[
            { value: "all", label: "All", badge: <span className="text-fg-subtle tabular-nums">{runs.length}</span> },
            { value: "active", label: "Active", badge: <span className="text-fg-subtle tabular-nums">{count(["running", "queued"])}</span> },
            { value: "done", label: "Completed" },
            { value: "failed", label: "Failed", badge: count(["failed"]) ? <span className="tabular-nums text-danger">{count(["failed"])}</span> : undefined },
          ]}
        />
      </div>
      <ul className="divide-y divide-border">
        {shown.map((r) => {
          const s = statusUI[r.status];
          return (
            <li key={r.id} className="group flex items-start gap-3 px-4 py-3">
              <span className={cn("mt-0.5 shrink-0", s.cls)} aria-label={s.label}>{s.icon}</span>
              <div className="min-w-0 flex-1">
                <button type="button" onClick={() => onOpen?.(r.id)} className="block max-w-full truncate text-left text-sm font-medium text-fg hover:underline">{r.title}</button>
                <p className="mt-0.5 flex flex-wrap items-center gap-x-2 text-xs text-fg-subtle">
                  <span className={s.cls}>{s.label}</span>
                  <span>·</span><RelativeTime date={r.startedAt} />
                  {r.durationSec != null && <><span>·</span><span className="inline-flex items-center gap-1 tabular-nums"><Clock className="size-3" />{dur(r.durationSec)}</span></>}
                  {r.cost != null && <><span>·</span><span className="tabular-nums">${r.cost.toFixed(2)}</span></>}
                </p>
                {r.status === "running" && (
                  <div className="mt-2 space-y-1">
                    {r.step && <p className="truncate text-xs text-fg-muted">{r.step}</p>}
                    <div className="h-1 overflow-hidden rounded-full bg-surface-2"><div className="h-full rounded-full bg-info transition-[width] duration-500" style={{ width: `${r.progress ?? 10}%` }} /></div>
                  </div>
                )}
                {r.status === "failed" && r.error && <p className="mt-1.5 rounded-sm bg-danger/[0.05] px-2 py-1 font-mono text-xs text-danger">{r.error}</p>}
              </div>
              <div className="flex shrink-0 items-center gap-1">
                {r.status === "running" && onStop && <Button size="xs" variant="outline" onClick={() => onStop(r.id)}><Square className="!size-3" />Stop</Button>}
                {(r.status === "failed" || r.status === "stopped") && onRetry && <Button size="xs" variant="outline" onClick={() => onRetry(r.id)}><RotateCcw />Retry</Button>}
                {onOpen && <button type="button" onClick={() => onOpen(r.id)} aria-label={`Open ${r.title}`} className="grid size-7 place-items-center rounded-sm text-fg-subtle hover:bg-surface-2 hover:text-fg"><ChevronRight className="size-4" /></button>}
              </div>
            </li>
          );
        })}
        {!shown.length && <li className="px-4 py-10 text-center text-sm text-fg-subtle">Nothing here</li>}
      </ul>
    </div>
  );
}

components/ai/announcement.tsx.source:
"use client";

import * as React from "react";
import { ArrowRight, X, Sparkles } from "lucide-react";
import { cn } from "../../lib/cn";

/**
 * Announcement
 * Tell users about something new without a modal:
 * - <AnnouncementPill/> above an empty state or in a header ("New · Nova is here →")
 * - <AnnouncementBar/> full-width strip at the top of the app, dismissible and remembered by `id`
 */
export function AnnouncementPill({ tag = "New", children, href, onClick, className }: { tag?: React.ReactNode; children: React.ReactNode; href?: string; onClick?: () => void; className?: string }) {
  const C: any = href ? "a" : "button";
  return (
    <C
      href={href}
      type={href ? undefined : "button"}
      onClick={onClick}
      className={cn("group inline-flex h-8 items-center gap-2 rounded-full border border-border bg-bg py-1 pl-1 pr-3 text-sm text-fg-muted shadow-xs transition-colors hover:border-border-strong hover:text-fg focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-fg/20", className)}
    >
      <span className="inline-flex h-6 items-center gap-1 rounded-full bg-accent px-2 text-xs font-medium text-accent-fg [&_svg]:size-3">{tag}</span>
      {children}
      <ArrowRight className="size-3.5 transition-transform group-hover:translate-x-0.5" />
    </C>
  );
}

export function AnnouncementBar({ id, children, action, onDismiss, tone = "accent", className }: { id?: string; children: React.ReactNode; action?: { label: string; href?: string; onClick?: () => void }; onDismiss?: () => void; tone?: "accent" | "subtle"; className?: string }) {
  const key = id ? `pl-announcement-${id}` : null;
  const [hidden, setHidden] = React.useState(() => { try { return key ? localStorage.getItem(key) === "1" : false; } catch { return false; } });
  if (hidden) return null;
  const dismiss = () => { setHidden(true); try { if (key) localStorage.setItem(key, "1"); } catch { /* storage blocked */ } onDismiss?.(); };
  return (
    <div role="region" aria-label="Announcement" className={cn("relative flex min-h-10 items-center justify-center gap-3 px-12 py-2 text-center text-sm", tone === "accent" ? "bg-accent text-accent-fg" : "border-b border-border bg-surface text-fg", className)}>
      <Sparkles className="hidden size-4 shrink-0 opacity-80 sm:block" />
      <span>{children}</span>
      {action && (
        <a href={action.href} onClick={action.onClick} className="shrink-0 cursor-pointer font-medium underline underline-offset-4 hover:no-underline">{action.label}</a>
      )}
      <button type="button" onClick={dismiss} aria-label="Dismiss announcement" className="absolute right-2 top-1/2 grid size-7 -translate-y-1/2 place-items-center rounded-sm opacity-70 hover:bg-black/10 hover:opacity-100 dark:hover:bg-white/10"><X className="size-4" /></button>
    </div>
  );
}

components/ai/api-key-input.tsx.source:
"use client";

import * as React from "react";
import { AlertCircle, Check, Eye, EyeOff, KeyRound } from "lucide-react";
import { cn } from "../../lib/cn";
import { Button } from "../ui/button";
import { Spinner } from "../ui/spinner";

/**
 * ApiKeyInput
 * For bring-your-own-key products. Masked by default · show/hide · paste-friendly
 * · async verify with idle → checking → valid | invalid. After saving, show only the last 4 chars.
 */
export type KeyStatus = "idle" | "checking" | "valid" | "invalid";

export interface ApiKeyInputProps {
  value: string;
  onValueChange: (v: string) => void;
  onVerify?: () => void;
  status?: KeyStatus;
  label?: string;
  provider?: string;
  placeholder?: string;
  helpText?: React.ReactNode;
  errorText?: string;
  className?: string;
}

export function ApiKeyInput({ value, onValueChange, onVerify, status = "idle", label = "API key", provider, placeholder = "sk-…", helpText, errorText = "That key didn't work. Check it's copied in full and has access to this model.", className }: ApiKeyInputProps) {
  const [show, setShow] = React.useState(false);
  const id = React.useId();
  const hid = `${id}-help`;
  return (
    <div className={cn("space-y-2", className)}>
      <div className="flex items-baseline justify-between">
        <label htmlFor={id} className="text-sm font-medium text-fg">{label}</label>
        {provider && <span className="text-xs text-fg-subtle">{provider}</span>}
      </div>
      <div className="flex gap-2">
        <div className={cn(
          "flex h-9 min-w-0 flex-1 items-center gap-2 rounded-md border bg-bg px-3 shadow-xs transition-[border-color,box-shadow] focus-within:ring-4",
          status === "invalid" ? "border-danger/50 focus-within:ring-danger/10" : status === "valid" ? "border-success/50 focus-within:ring-success/10" : "border-border focus-within:border-border-strong focus-within:ring-fg/5"
        )}>
          <KeyRound className="size-4 shrink-0 text-fg-subtle" />
          <input
            id={id}
            type={show ? "text" : "password"}
            value={value}
            onChange={(e) => onValueChange(e.target.value.trim())}
            placeholder={placeholder}
            autoComplete="off"
            spellCheck={false}
            aria-invalid={status === "invalid" || undefined}
            aria-describedby={hid}
            className="min-w-0 flex-1 bg-transparent font-mono text-sm text-fg placeholder:text-fg-subtle focus:outline-none"
          />
          {status === "valid" && <Check className="size-4 shrink-0 text-success" />}
          {status === "invalid" && <AlertCircle className="size-4 shrink-0 text-danger" />}
          <button type="button" onClick={() => setShow((s) => !s)} aria-label={show ? "Hide key" : "Show key"} className="shrink-0 text-fg-subtle hover:text-fg">
            {show ? <EyeOff className="size-4" /> : <Eye className="size-4" />}
          </button>
        </div>
        {onVerify && (
          <Button variant="outline" onClick={onVerify} disabled={!value || status === "checking"} className="w-20">
            {status === "checking" ? <Spinner className="size-3.5" /> : "Verify"}
          </Button>
        )}
      </div>
      <p id={hid} className={cn("text-xs", status === "invalid" ? "text-danger" : status === "valid" ? "text-success" : "text-fg-subtle")} aria-live="polite">
        {status === "invalid" ? errorText : status === "valid" ? `Connected · key ending in ${value.slice(-4)}` : helpText}
      </p>
    </div>
  );
}

components/ai/artifact.tsx.source:
"use client";

import * as React from "react";
import { Check, Copy, Download, Maximize2, X } from "lucide-react";
import { cn } from "../../lib/cn";
import { useCopy } from "../../lib/hooks";
import { Tooltip } from "../ui/tooltip";

/**
 * Artifact
 * A standalone output (document, code file, chart, app) shown in a panel beside the chat.
 * Header: title + version + actions. Optional Preview / Code tabs.
 */
export interface ArtifactProps {
  title: string;
  description?: string;
  version?: string;
  /** If both are set, shows Preview / Code tabs */
  preview?: React.ReactNode;
  code?: React.ReactNode;
  /** Raw text for the copy action */
  copyText?: string;
  onDownload?: () => void;
  onExpand?: () => void;
  onClose?: () => void;
  children?: React.ReactNode;
  className?: string;
}

export function Artifact({ title, description, version, preview, code, copyText, onDownload, onExpand, onClose, children, className }: ArtifactProps) {
  const [tab, setTab] = React.useState<"preview" | "code">("preview");
  const { copied, copy } = useCopy();
  const tabs = preview && code;
  const btn = "grid size-8 place-items-center rounded-sm text-fg-muted transition-colors hover:bg-surface-2 hover:text-fg";

  return (
    <section aria-label={title} className={cn("flex min-h-0 flex-col overflow-hidden rounded-xl border border-border bg-bg shadow-sm", className)}>
      <header className="flex h-14 shrink-0 items-center gap-3 border-b border-border pl-4 pr-2">
        <div className="min-w-0 flex-1">
          <p className="flex items-center gap-2 truncate text-base font-medium text-fg">
            {title}
            {version && <span className="rounded-xs bg-surface-2 px-1.5 text-2xs font-medium text-fg-muted">{version}</span>}
          </p>
          {description && <p className="truncate text-xs text-fg-subtle">{description}</p>}
        </div>
        {tabs && (
          <div className="flex h-8 rounded-md bg-surface-2 p-0.5 text-xs font-medium" role="tablist">
            {(["preview", "code"] as const).map((t) => (
              <button key={t} role="tab" type="button" aria-selected={tab === t} onClick={() => setTab(t)} className={cn("rounded-sm px-3 capitalize transition-colors", tab === t ? "bg-bg text-fg shadow-xs" : "text-fg-muted hover:text-fg")}>{t}</button>
            ))}
          </div>
        )}
        <div className="flex items-center">
          {copyText != null && <Tooltip label={copied ? "Copied" : "Copy"}><button type="button" className={btn} onClick={() => copy(copyText)} aria-label="Copy">{copied ? <Check className="size-4" /> : <Copy className="size-4" />}</button></Tooltip>}
          {onDownload && <Tooltip label="Download"><button type="button" className={btn} onClick={onDownload} aria-label="Download"><Download className="size-4" /></button></Tooltip>}
          {onExpand && <Tooltip label="Full screen"><button type="button" className={btn} onClick={onExpand} aria-label="Full screen"><Maximize2 className="size-4" /></button></Tooltip>}
          {onClose && <Tooltip label="Close"><button type="button" className={btn} onClick={onClose} aria-label="Close"><X className="size-4" /></button></Tooltip>}
        </div>
      </header>
      <div className="min-h-0 flex-1 overflow-auto">
        {tabs ? (tab === "preview" ? preview : code) : children ?? preview ?? code}
      </div>
    </section>
  );
}

components/ai/attachments.tsx.source:
"use client";

import * as React from "react";
import { FileCode2, FileImage, FileSpreadsheet, FileText, FileAudio, RotateCcw, X } from "lucide-react";
import { cn } from "../../lib/cn";

/**
 * Attachments
 * File and image chips for the prompt input and sent messages.
 * States: uploading (progress ring) · ready · error (retry). Images render as thumbnails.
 */
export interface AttachmentData {
  id: string;
  name: string;
  size?: number;
  type?: string;
  url?: string;
  status?: "uploading" | "ready" | "error";
  progress?: number;
}

const ext = (n: string) => n.split(".").pop()?.toLowerCase() ?? "";
const isImage = (a: AttachmentData) => a.type?.startsWith("image/") || ["png", "jpg", "jpeg", "gif", "webp", "avif"].includes(ext(a.name));
const iconFor = (n: string) => {
  const e = ext(n);
  if (["csv", "xlsx", "xls"].includes(e)) return FileSpreadsheet;
  if (["js", "ts", "tsx", "jsx", "py", "json", "html", "css", "md"].includes(e)) return FileCode2;
  if (["mp3", "wav", "m4a"].includes(e)) return FileAudio;
  if (["png", "jpg", "jpeg", "gif", "webp", "svg"].includes(e)) return FileImage;
  return FileText;
};
export const formatBytes = (b?: number) => (b == null ? "" : b < 1024 ? `${b} B` : b < 1048576 ? `${Math.round(b / 1024)} KB` : `${(b / 1048576).toFixed(1)} MB`);

function Progress({ value }: { value: number }) {
  return (
    <svg viewBox="0 0 20 20" className="size-5 -rotate-90" aria-hidden>
      <circle cx="10" cy="10" r="8" fill="none" strokeWidth="2" className="stroke-border" />
      <circle cx="10" cy="10" r="8" fill="none" strokeWidth="2" strokeLinecap="round" className="stroke-fg transition-[stroke-dashoffset] duration-300" strokeDasharray={50.3} strokeDashoffset={50.3 * (1 - value / 100)} />
    </svg>
  );
}

export interface AttachmentProps { data: AttachmentData; onRemove?: () => void; onRetry?: () => void; className?: string }

export function Attachment({ data, onRemove, onRetry, className }: AttachmentProps) {
  const { name, size, status = "ready", progress = 0, url } = data;
  const Icon = iconFor(name);
  const err = status === "error";

  if (isImage(data) && url) {
    return (
      <div className={cn("group relative size-16 shrink-0 overflow-hidden rounded-md border border-border bg-surface", err && "border-danger/50", className)} title={name}>
        <img src={url} alt={name} className={cn("size-full object-cover", status === "uploading" && "opacity-40")} />
        {status === "uploading" && <div className="absolute inset-0 grid place-items-center"><Progress value={progress} /></div>}
        {onRemove && <RemoveBtn name={name} onRemove={onRemove} />}
      </div>
    );
  }

  return (
    <div className={cn("group relative flex h-14 w-60 shrink-0 items-center gap-3 rounded-md border bg-bg p-2 pr-3", err ? "border-danger/40" : "border-border", className)}>
      <div className={cn("relative grid size-10 shrink-0 place-items-center rounded-sm", err ? "bg-danger/10 text-danger" : "bg-surface-2 text-fg-muted")}>
        {status === "uploading" ? <Progress value={progress} /> : <Icon className="size-5" />}
      </div>
      <div className="min-w-0 flex-1">
        <p className="truncate text-sm font-medium text-fg">{name}</p>
        <p className={cn("text-xs", err ? "text-danger" : "text-fg-subtle")}>
          {status === "uploading" ? `Uploading · ${Math.round(progress)}%` : err ? "Upload failed" : [ext(name).toUpperCase(), formatBytes(size)].filter(Boolean).join(" · ")}
        </p>
      </div>
      {err && onRetry && (
        <button type="button" onClick={onRetry} aria-label={`Retry ${name}`} className="grid size-7 place-items-center rounded-sm text-fg-muted hover:bg-surface-2 hover:text-fg"><RotateCcw className="size-3.5" /></button>
      )}
      {onRemove && <RemoveBtn name={name} onRemove={onRemove} />}
    </div>
  );
}

function RemoveBtn({ name, onRemove }: { name: string; onRemove: () => void }) {
  return (
    <button
      type="button"
      onClick={onRemove}
      aria-label={`Remove ${name}`}
      className="absolute right-1 top-1 grid size-5 place-items-center rounded-full bg-fg text-bg opacity-0 shadow-sm transition-opacity focus:opacity-100 group-hover:opacity-100 [@media(hover:none)]:opacity-100"
    >
      <X className="size-3" />
    </button>
  );
}

export function Attachments({ items, onRemove, onRetry, className }: { items: AttachmentData[]; onRemove?: (id: string) => void; onRetry?: (id: string) => void; className?: string }) {
  if (!items.length) return null;
  return (
    <div className={cn("flex flex-wrap gap-2", className)}>
      {items.map((a) => (
        <Attachment key={a.id} data={a} onRemove={onRemove && (() => onRemove(a.id))} onRetry={onRetry && (() => onRetry(a.id))} />
      ))}
    </div>
  );
}

components/ai/audio-player.tsx.source:
"use client";

import * as React from "react";
import { Download, Pause, Play } from "lucide-react";
import { cn } from "../../lib/cn";
import { Spinner } from "../ui/spinner";

/**
 * AudioPlayer
 * Playback for AI-generated speech and audio: play/pause, a seekable waveform,
 * time, playback speed and download. The waveform doubles as the scrubber.
 * - Click or drag the waveform to seek · ← → seek 5s · Space plays/pauses
 * - Pass real `peaks` (0–1) or get a stable pseudo-waveform from the title
 */
export interface AudioPlayerProps {
  src: string;
  title?: string;
  /** Waveform peaks 0–1. ~48–96 values look best. */
  peaks?: number[];
  /** Show a download button (uses `downloadName`) */
  downloadable?: boolean;
  downloadName?: string;
  rates?: number[];
  className?: string;
}

export function pseudoPeaks(seed: string, count = 64) {
  let h = 2166136261;
  for (const c of seed) h = Math.imul(h ^ c.charCodeAt(0), 16777619);
  return Array.from({ length: count }, (_, i) => {
    h = Math.imul(h ^ (h >>> 13), 1274126177);
    const r = ((h >>> 0) % 1000) / 1000;
    const env = 0.55 + 0.45 * Math.sin((i / count) * Math.PI);
    return Math.max(0.12, Math.min(1, r * env + 0.1));
  });
}

const fmt = (s: number) => (!isFinite(s) ? "0:00" : `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, "0")}`);

export function AudioPlayer({ src, title, peaks, downloadable, downloadName, rates = [1, 1.25, 1.5, 2, 0.75], className }: AudioPlayerProps) {
  const audio = React.useRef<HTMLAudioElement>(null);
  const bar = React.useRef<HTMLDivElement>(null);
  const [playing, setPlaying] = React.useState(false);
  const [loading, setLoading] = React.useState(false);
  const [time, setTime] = React.useState(0);
  const [duration, setDuration] = React.useState(0);
  const [rate, setRate] = React.useState(rates[0]);
  const bars = React.useMemo(() => peaks ?? pseudoPeaks(title ?? src), [peaks, title, src]);
  const progress = duration ? time / duration : 0;
  // Fit bar count to the available width (≈ 4px per bar) by resampling the peaks
  const [fit, setFit] = React.useState(bars.length);
  React.useEffect(() => {
    const el = bar.current;
    if (!el || typeof ResizeObserver === "undefined") return;
    const ro = new ResizeObserver(([e]) => setFit(Math.max(12, Math.floor(e.contentRect.width / 4))));
    ro.observe(el);
    return () => ro.disconnect();
  }, []);
  const shownBars = React.useMemo(() => {
    if (fit >= bars.length) return bars;
    return Array.from({ length: fit }, (_, i) => {
      const a = Math.floor((i * bars.length) / fit), z = Math.max(a + 1, Math.floor(((i + 1) * bars.length) / fit));
      return Math.max(...bars.slice(a, z));
    });
  }, [bars, fit]);

  React.useEffect(() => { if (audio.current) audio.current.playbackRate = rate; }, [rate]);
  React.useEffect(() => {
    const a = audio.current;
    if (!a || !playing) return;
    let raf = 0;
    const loop = () => { setTime(a.currentTime); raf = requestAnimationFrame(loop); };
    raf = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(raf);
  }, [playing]);

  const toggle = async () => {
    const a = audio.current;
    if (!a) return;
    if (a.paused) { setLoading(true); try { await a.play(); } catch { /* blocked */ } setLoading(false); }
    else a.pause();
  };
  const seekTo = (t: number) => { const a = audio.current; if (!a || !duration) return; a.currentTime = Math.max(0, Math.min(duration, t)); setTime(a.currentTime); };
  const seekFromPointer = (clientX: number) => {
    const r = bar.current!.getBoundingClientRect();
    seekTo(((clientX - r.left) / r.width) * duration);
  };

  return (
    <div className={cn("flex w-full items-center gap-3 rounded-xl border border-border bg-bg p-2.5 pr-3", className)}>
      <audio
        ref={audio}
        src={src}
        preload="metadata"
        onLoadedMetadata={(e) => setDuration(e.currentTarget.duration)}
        onDurationChange={(e) => setDuration(e.currentTarget.duration)}
        onPlay={() => setPlaying(true)}
        onPause={() => setPlaying(false)}
        onEnded={(e) => { setPlaying(false); setTime(e.currentTarget.duration); }}
        onWaiting={() => setLoading(true)}
        onPlaying={() => setLoading(false)}
      />
      <button type="button" onClick={toggle} aria-label={playing ? "Pause" : "Play"}
        className="grid size-10 shrink-0 place-items-center rounded-full bg-fg text-bg transition-opacity hover:opacity-90 [&_svg]:size-4">
        {loading ? <Spinner className="size-4" /> : playing ? <Pause className="fill-current" /> : <Play className="ml-0.5 fill-current" />}
      </button>

      <div className="min-w-0 flex-1">
        <div className="flex items-center gap-2">
          <p className="min-w-0 flex-1 truncate text-sm font-medium text-fg">{title}</p>
          <button type="button" onClick={() => setRate(rates[(rates.indexOf(rate) + 1) % rates.length])} aria-label={`Playback speed ${rate}×`}
            className="h-6 min-w-[2.5rem] shrink-0 rounded-md border border-border px-1.5 font-mono text-xs text-fg-muted transition-colors hover:bg-surface-2 hover:text-fg">
            {rate}×
          </button>
          {downloadable && (
            <a href={src} download={downloadName ?? title ?? "audio"} aria-label="Download audio" className="grid size-6 shrink-0 place-items-center rounded-md text-fg-muted transition-colors hover:bg-surface-2 hover:text-fg [&_svg]:size-3.5">
              <Download />
            </a>
          )}
        </div>
        <div className="mt-1 flex items-center gap-3">
          <div
            ref={bar}
            role="slider"
            tabIndex={0}
            aria-label="Seek"
            aria-valuemin={0}
            aria-valuemax={Math.round(duration)}
            aria-valuenow={Math.round(time)}
            aria-valuetext={`${fmt(time)} of ${fmt(duration)}`}
            onPointerDown={(e) => { e.currentTarget.setPointerCapture(e.pointerId); seekFromPointer(e.clientX); }}
            onPointerMove={(e) => { if (e.buttons === 1) seekFromPointer(e.clientX); }}
            onKeyDown={(e) => {
              if (e.key === "ArrowRight") { e.preventDefault(); seekTo(time + 5); }
              else if (e.key === "ArrowLeft") { e.preventDefault(); seekTo(time - 5); }
              else if (e.key === " " || e.key === "Enter") { e.preventDefault(); toggle(); }
              else if (e.key === "Home") { e.preventDefault(); seekTo(0); }
              else if (e.key === "End") { e.preventDefault(); seekTo(duration); }
            }}
            className="flex h-8 min-w-0 flex-1 cursor-pointer touch-none items-center gap-[2px] rounded-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-fg/20"
          >
            {shownBars.map((p, i) => (
              <span key={i} className={cn("min-w-0 flex-1 rounded-full transition-colors", i / shownBars.length < progress ? "bg-fg" : "bg-fg/20")} style={{ height: `${Math.round(p * 100)}%` }} />
            ))}
          </div>
          <span className="shrink-0 font-mono text-xs tabular-nums text-fg-muted">{fmt(time)} / {fmt(duration)}</span>
        </div>
      </div>
    </div>
  );
}

components/ai/branch.tsx.source:
"use client";

import * as React from "react";
import { ChevronLeft, ChevronRight } from "lucide-react";
import { cn } from "../../lib/cn";

/**
 * Branch
 * Navigate between alternative responses (after regenerate) or edited prompts.
 * Renders only the active branch; the pager shows "2 / 3".
 */
export interface BranchProps {
  branches: React.ReactNode[];
  /** Controlled index */
  index?: number;
  defaultIndex?: number;
  onIndexChange?: (i: number) => void;
  /** Where to put the pager relative to content */
  pager?: "top" | "bottom";
  className?: string;
}

export function Branch({ branches, index, defaultIndex, onIndexChange, pager = "bottom", className }: BranchProps) {
  const [inner, setInner] = React.useState(defaultIndex ?? branches.length - 1);
  const i = Math.min(index ?? inner, branches.length - 1);
  const go = (n: number) => { const v = (n + branches.length) % branches.length; setInner(v); onIndexChange?.(v); };
  const nav = branches.length > 1 && <BranchPager index={i} total={branches.length} onPrev={() => go(i - 1)} onNext={() => go(i + 1)} />;
  return (
    <div className={cn("flex flex-col gap-2", className)}>
      {pager === "top" && nav}
      <div key={i} style={{ animation: "pl-in .2s ease-out" }}>{branches[i]}</div>
      {pager === "bottom" && nav}
    </div>
  );
}

export function BranchPager({ index, total, onPrev, onNext, className }: { index: number; total: number; onPrev: () => void; onNext: () => void; className?: string }) {
  const btn = "grid size-6 place-items-center rounded-xs text-fg-muted transition-colors hover:bg-surface-2 hover:text-fg disabled:opacity-40";
  return (
    <div className={cn("inline-flex items-center gap-1 text-xs text-fg-muted", className)} role="group" aria-label="Response versions">
      <button type="button" className={btn} onClick={onPrev} aria-label="Previous version"><ChevronLeft className="size-3.5" /></button>
      <span className="min-w-8 text-center tabular-nums" aria-live="polite">{index + 1} / {total}</span>
      <button type="button" className={btn} onClick={onNext} aria-label="Next version"><ChevronRight className="size-3.5" /></button>
    </div>
  );
}

components/ai/chain-of-thought.tsx.source:
"use client";

import * as React from "react";
import { ChevronDown, Dot, type LucideIcon } from "lucide-react";
import { cn } from "../../lib/cn";
import { Spinner } from "../ui/spinner";
import { Shimmer } from "./loader";
import { Favicon, hostOf } from "./sources";

/**
 * ChainOfThought
 * A visible timeline of what the model did: searched, read, analysed, concluded.
 * More structured than Reasoning — each step can carry search results or images.
 */
export type StepStatus = "complete" | "active" | "pending";

export interface ChainStep {
  label: string;
  description?: string;
  icon?: LucideIcon;
  status?: StepStatus;
  /** Result chips, e.g. URLs visited */
  results?: string[];
  /** Arbitrary content, e.g. an image grid */
  content?: React.ReactNode;
}

export function ChainOfThought({ steps, title = "Chain of thought", defaultOpen = true, className }: { steps: ChainStep[]; title?: string; defaultOpen?: boolean; className?: string }) {
  const [open, setOpen] = React.useState(defaultOpen);
  const active = steps.find((s) => s.status === "active");
  const id = React.useId();
  return (
    <div className={cn("text-sm", className)}>
      <button type="button" aria-expanded={open} aria-controls={id} onClick={() => setOpen((o) => !o)} className="inline-flex h-7 items-center gap-2 text-fg-muted transition-colors hover:text-fg">
        {active ? <Shimmer>{active.label}</Shimmer> : <span className="font-medium">{title}</span>}
        <ChevronDown className={cn("size-3.5 transition-transform duration-200", open && "rotate-180")} />
      </button>
      <ol id={id} hidden={!open} className="mt-3 flex flex-col" style={{ animation: "pl-in .2s ease-out" }}>
        {steps.map((s, i) => {
          const Icon = s.icon ?? Dot;
          const status = s.status ?? "complete";
          return (
            <li key={i} className="relative flex gap-3 pb-4 last:pb-0">
              {i < steps.length - 1 && <span aria-hidden className="absolute left-2 top-6 h-[calc(100%-20px)] w-px bg-border" />}
              <span className={cn("relative mt-0.5 grid size-4 shrink-0 place-items-center", status === "pending" ? "text-fg-subtle" : "text-fg-muted")}>
                {status === "active" ? <Spinner className="size-3.5" /> : <Icon className="size-4" />}
              </span>
              <div className="min-w-0 flex-1">
                <p className={cn(status === "pending" ? "text-fg-subtle" : "text-fg")}>{s.label}</p>
                {s.description && <p className="mt-0.5 text-xs text-fg-muted">{s.description}</p>}
                {s.results && (
                  <div className="mt-2 flex flex-wrap gap-1.5">
                    {s.results.map((r) => (
                      <span key={r} className="inline-flex h-6 items-center gap-1.5 rounded-full border border-border bg-bg pl-1 pr-2 text-xs text-fg-muted">
                        <Favicon url={r} className="size-3.5 ring-0" />
                        {hostOf(r)}
                      </span>
                    ))}
                  </div>
                )}
                {s.content && <div className="mt-2">{s.content}</div>}
              </div>
            </li>
          );
        })}
      </ol>
    </div>
  );
}

components/ai/chat-sidebar.tsx.source:
"use client";

import * as React from "react";
import { MoreHorizontal, PanelLeft, PenSquare, Pin, Search } from "lucide-react";
import { cn } from "../../lib/cn";
import { Button } from "../ui/button";
import { Tooltip } from "../ui/tooltip";

/**
 * ChatSidebar
 * Conversation history: new chat, search, pinned chats, date groups (Today, Yesterday, Previous 7 days…),
 * and a footer slot for usage or the account menu.
 */
export interface ChatItem { id: string; title: string; group: string; pinned?: boolean }

export interface ChatSidebarProps {
  chats: ChatItem[];
  activeId?: string;
  onSelect: (id: string) => void;
  onNew: () => void;
  onMore?: (id: string) => void;
  onCollapse?: () => void;
  header?: React.ReactNode;
  footer?: React.ReactNode;
  className?: string;
}

export function ChatSidebar({ chats, activeId, onSelect, onNew, onMore, onCollapse, header, footer, className }: ChatSidebarProps) {
  const [q, setQ] = React.useState("");
  const list = chats.filter((c) => c.title.toLowerCase().includes(q.toLowerCase()));
  const pinned = list.filter((c) => c.pinned);
  const groups = list.filter((c) => !c.pinned).reduce<[string, ChatItem[]][]>((acc, c) => {
    const g = acc.find(([k]) => k === c.group);
    g ? g[1].push(c) : acc.push([c.group, [c]]);
    return acc;
  }, []);

  const Row = ({ c }: { c: ChatItem }) => (
    <li className="group/row relative">
      <button
        type="button"
        onClick={() => onSelect(c.id)}
        aria-current={c.id === activeId ? "page" : undefined}
        className={cn("flex h-8 w-full items-center rounded-sm px-2 pr-8 text-left text-sm transition-colors", c.id === activeId ? "bg-surface-2 font-medium text-fg" : "text-fg-muted hover:bg-surface-2 hover:text-fg")}
      >
        <span className="truncate">{c.title}</span>
      </button>
      {onMore && (
        <button type="button" onClick={() => onMore(c.id)} aria-label={`Options for ${c.title}`} className="absolute right-1 top-1 grid size-6 place-items-center rounded-xs text-fg-subtle opacity-0 hover:bg-border hover:text-fg focus:opacity-100 group-hover/row:opacity-100 [@media(hover:none)]:opacity-100">
          <MoreHorizontal className="size-4" />
        </button>
      )}
    </li>
  );

  return (
    <aside className={cn("flex h-full w-64 shrink-0 flex-col border-r border-border bg-surface", className)} aria-label="Chat history">
      <div className="flex h-14 items-center gap-1 px-3">
        <div className="min-w-0 flex-1 truncate px-1 text-base font-semibold text-fg">{header}</div>
        {onCollapse && <Tooltip label="Close sidebar" side="bottom"><Button variant="ghost" size="icon-sm" onClick={onCollapse} aria-label="Close sidebar"><PanelLeft /></Button></Tooltip>}
        <Tooltip label="New chat" side="bottom"><Button variant="ghost" size="icon-sm" onClick={onNew} aria-label="New chat"><PenSquare /></Button></Tooltip>
      </div>
      <div className="px-3 pb-2">
        <label className="flex h-8 items-center gap-2 rounded-sm border border-border bg-bg px-2 text-fg-subtle focus-within:border-border-strong">
          <Search className="size-3.5 shrink-0" />
          <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search chats" aria-label="Search chats" className="w-full bg-transparent text-sm text-fg placeholder:text-fg-subtle focus:outline-none" />
        </label>
      </div>
      <nav className="min-h-0 flex-1 space-y-4 overflow-y-auto px-2 pb-4 pt-2">
        {pinned.length > 0 && (
          <div>
            <p className="flex items-center gap-1 px-2 pb-1 text-xs font-medium text-fg-subtle"><Pin className="size-3" />Pinned</p>
            <ul>{pinned.map((c) => <Row key={c.id} c={c} />)}</ul>
          </div>
        )}
        {groups.map(([g, items]) => (
          <div key={g}>
            <p className="px-2 pb-1 text-xs font-medium text-fg-subtle">{g}</p>
            <ul>{items.map((c) => <Row key={c.id} c={c} />)}</ul>
          </div>
        ))}
        {!list.length && <p className="px-2 py-8 text-center text-sm text-fg-subtle">No chats match "{q}"</p>}
      </nav>
      {footer && <div className="border-t border-border p-3">{footer}</div>}
    </aside>
  );
}

components/ai/clarifying-question.tsx.source:
"use client";

import * as React from "react";
import { Check, HelpCircle, CornerDownLeft } from "lucide-react";
import { cn } from "../../lib/cn";
import { Button } from "../ui/button";

/**
 * ClarifyingQuestion
 * The agent asks before it acts: a short question with 2–4 answers, an optional "Other" answer,
 * and Skip. One click answers; the card then collapses to a record of the choice.
 * Number keys 1–9 pick an option.
 */
export interface QuestionOption { value: string; label: string; description?: string; recommended?: boolean }

export interface ClarifyingQuestionProps {
  question: string;
  options: QuestionOption[];
  multiple?: boolean;
  allowOther?: boolean;
  onAnswer: (answer: { values: string[]; other?: string }) => void;
  onSkip?: () => void;
  /** Answered state — shows the chosen labels */
  answered?: string[];
  className?: string;
}

export function ClarifyingQuestion({ question, options, multiple, allowOther = true, onAnswer, onSkip, answered, className }: ClarifyingQuestionProps) {
  const [picked, setPicked] = React.useState<string[]>([]);
  const [other, setOther] = React.useState("");
  const [otherOn, setOtherOn] = React.useState(false);
  const submit = (vals = picked) => onAnswer({ values: vals, other: otherOn && other.trim() ? other.trim() : undefined });
  const choose = (v: string) => {
    if (!multiple) { setPicked([v]); submit([v]); return; }
    setPicked((p) => (p.includes(v) ? p.filter((x) => x !== v) : [...p, v]));
  };

  if (answered)
    return (
      <div className={cn("inline-flex max-w-full items-center gap-2 rounded-lg border border-border bg-surface px-3 py-2 text-sm", className)}>
        <Check className="size-4 shrink-0 text-success" />
        <span className="truncate text-fg-muted">{question}</span>
        <span className="shrink-0 font-medium text-fg">{answered.join(", ")}</span>
      </div>
    );

  return (
    <div
      role="group"
      aria-label={question}
      className={cn("overflow-hidden rounded-lg border border-border bg-bg text-sm shadow-xs", className)}
      onKeyDown={(e) => {
        if ((e.target as HTMLElement).tagName === "INPUT") return;
        const n = Number(e.key);
        if (n >= 1 && n <= options.length) { e.preventDefault(); choose(options[n - 1].value); }
      }}
    >
      <div className="flex items-start gap-3 p-4 pb-3">
        <HelpCircle className="mt-0.5 size-4 shrink-0 text-fg-muted" />
        <p className="text-base font-medium text-fg">{question}</p>
      </div>
      <div className="space-y-1.5 px-3 pb-3" role={multiple ? "group" : "radiogroup"}>
        {options.map((o, i) => {
          const on = picked.includes(o.value);
          return (
            <button
              key={o.value}
              type="button"
              role={multiple ? "checkbox" : "radio"}
              aria-checked={on}
              onClick={() => choose(o.value)}
              className={cn("flex w-full items-start gap-3 rounded-md border px-3 py-2.5 text-left transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-fg/20", on ? "border-fg bg-surface" : "border-border hover:border-border-strong hover:bg-surface")}
            >
              <span className="mt-0.5 grid size-5 shrink-0 place-items-center rounded-xs border border-border bg-surface text-2xs font-medium tabular-nums text-fg-muted">{i + 1}</span>
              <span className="min-w-0 flex-1">
                <span className="flex items-center gap-2 font-medium text-fg">{o.label}{o.recommended && <span className="text-2xs font-medium text-info">Recommended</span>}</span>
                {o.description && <span className="mt-0.5 block text-xs text-fg-muted">{o.description}</span>}
              </span>
              {multiple && <span className={cn("mt-0.5 grid size-4 shrink-0 place-items-center rounded-xs border", on ? "border-accent bg-accent text-accent-fg" : "border-border-strong")}>{on && <Check className="size-3" strokeWidth={3} />}</span>}
            </button>
          );
        })}
        {allowOther && (
          otherOn ? (
            <form className="flex gap-2" onSubmit={(e) => { e.preventDefault(); if (other.trim()) submit(multiple ? picked : []); }}>
              <input autoFocus value={other} onChange={(e) => setOther(e.target.value)} placeholder="Type your answer…" aria-label="Other answer" className="h-9 flex-1 rounded-md border border-border-strong bg-bg px-3 text-base text-fg focus:outline-none focus:ring-4 focus:ring-fg/5" />
              {!multiple && <Button type="submit" size="icon" disabled={!other.trim()} aria-label="Send answer"><CornerDownLeft /></Button>}
            </form>
          ) : (
            <button type="button" onClick={() => setOtherOn(true)} className="flex h-9 w-full items-center rounded-md px-3 text-left text-fg-muted hover:bg-surface hover:text-fg">Something else…</button>
          )
        )}
      </div>
      {(multiple || onSkip) && (
        <div className="flex items-center justify-between border-t border-border bg-surface px-4 py-2">
          {onSkip ? <button type="button" onClick={onSkip} className="text-sm text-fg-muted hover:text-fg">Skip, you decide</button> : <span />}
          {multiple && <Button size="sm" onClick={() => submit()} disabled={!picked.length && !other.trim()}>Continue</Button>}
        </div>
      )}
    </div>
  );
}

components/ai/code-block.tsx.source:
"use client";

import * as React from "react";
import { Check, Copy, Download, WrapText } from "lucide-react";
import { cn } from "../../lib/cn";
import { useCopy } from "../../lib/hooks";
import { Tooltip } from "../ui/tooltip";

/**
 * CodeBlock
 * Header (filename or language) · copy · optional download & wrap toggle · line numbers · line highlight.
 * Ships with a tiny zero-dependency highlighter for JS/TS/Python/Bash/JSON.
 * For full grammar support, pass pre-highlighted nodes via `children` (e.g. from Shiki).
 */
export interface CodeBlockProps {
  code: string;
  language?: string;
  filename?: string;
  showLineNumbers?: boolean;
  /** 1-based line numbers to highlight */
  highlightLines?: number[];
  downloadable?: boolean;
  wrap?: boolean;
  maxHeight?: number;
  children?: React.ReactNode;
  className?: string;
}

const KW = new Set("const let var function return if else for while of in new class extends import from export default async await try catch finally throw typeof interface type enum implements public private readonly def lambda pass None True False self elif with as yield not and or is null undefined true false this echo fi then do done".split(" "));

type Tok = { t: string; c?: "kw" | "str" | "com" | "num" | "fn" };
export function highlight(code: string): Tok[][] {
  const re = /(\/\/.*|#.*|\/\*[\s\S]*?\*\/)|("(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|`(?:\\.|[^`\\])*`)|(\b\d+(?:\.\d+)?\b)|([A-Za-z_$][\w$]*)(?=\s*\()|([A-Za-z_$][\w$]*)/g;
  return code.split("\n").map((line) => {
    const out: Tok[] = [];
    let last = 0;
    for (const m of line.matchAll(re)) {
      if (m.index! > last) out.push({ t: line.slice(last, m.index) });
      if (m[1]) out.push({ t: m[1], c: "com" });
      else if (m[2]) out.push({ t: m[2], c: "str" });
      else if (m[3]) out.push({ t: m[3], c: "num" });
      else if (m[4]) out.push({ t: m[4], c: KW.has(m[4]) ? "kw" : "fn" });
      else out.push({ t: m[5], c: KW.has(m[5]) ? "kw" : undefined });
      last = m.index! + m[0].length;
    }
    if (last < line.length) out.push({ t: line.slice(last) });
    return out;
  });
}

const tokCls = { kw: "text-[rgb(var(--syn-keyword))]", str: "text-[rgb(var(--syn-string))]", com: "text-[rgb(var(--syn-comment))] italic", num: "text-[rgb(var(--syn-number))]", fn: "text-[rgb(var(--syn-fn))]" };

export function CodeBlock({ code, language = "text", filename, showLineNumbers, highlightLines = [], downloadable, wrap: wrapDefault = false, maxHeight, children, className }: CodeBlockProps) {
  const { copied, copy } = useCopy();
  const [wrap, setWrap] = React.useState(wrapDefault);
  const lines = React.useMemo(() => highlight(code), [code]);
  const hl = new Set(highlightLines);
  const btn = "grid size-7 place-items-center rounded-sm text-fg-subtle transition-colors hover:bg-surface-2 hover:text-fg";

  const download = () => {
    const url = URL.createObjectURL(new Blob([code], { type: "text/plain" }));
    const a = Object.assign(document.createElement("a"), { href: url, download: filename ?? `snippet.${language}` });
    a.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div className={cn("overflow-hidden rounded-lg border border-border bg-surface", className)}>
      <div className="flex h-10 items-center gap-1 border-b border-border pl-4 pr-2">
        <span className="flex-1 truncate font-mono text-xs text-fg-muted">{filename ?? language}</span>
        <Tooltip label={wrap ? "Don't wrap" : "Wrap lines"}><button type="button" className={cn(btn, wrap && "text-fg")} onClick={() => setWrap((w) => !w)} aria-pressed={wrap} aria-label="Toggle line wrap"><WrapText className="size-3.5" /></button></Tooltip>
        {downloadable && <Tooltip label="Download"><button type="button" className={btn} onClick={download} aria-label="Download file"><Download className="size-3.5" /></button></Tooltip>}
        <Tooltip label={copied ? "Copied" : "Copy"}><button type="button" className={btn} onClick={() => copy(code)} aria-label="Copy code">{copied ? <Check className="size-3.5 text-fg" /> : <Copy className="size-3.5" />}</button></Tooltip>
      </div>
      <pre className={cn("overflow-auto py-4 font-mono text-sm leading-6 text-fg", wrap ? "whitespace-pre-wrap break-words" : "whitespace-pre")} style={{ maxHeight }}>
        {children ?? (
          <code className="block min-w-fit">
            {lines.map((toks, i) => (
              <span key={i} className={cn("flex px-4", hl.has(i + 1) && "bg-info/[0.08] shadow-[inset_2px_0_0_rgb(var(--info))]")}>
                {showLineNumbers && <span aria-hidden className="mr-4 inline-block w-6 shrink-0 select-none text-right text-fg-subtle">{i + 1}</span>}
                <span className="flex-1">
                  {toks.length ? toks.map((tk, j) => <span key={j} className={tk.c && tokCls[tk.c]}>{tk.t}</span>) : "​"}
                </span>
              </span>
            ))}
          </code>
        )}
      </pre>
    </div>
  );
}

components/ai/command-bar.tsx.source:
"use client";

import * as React from "react";
import { ArrowRight, CornerDownLeft, Search, Sparkles } from "lucide-react";
import { cn } from "../../lib/cn";
import { Kbd } from "../ui/kbd";
import { Dialog } from "../ui/dialog";

/**
 * CommandBar
 * ⌘K palette that blends commands with AI: typing filters commands, and the first row is
 * always "Ask AI: <query>" so any question has somewhere to go.
 * Opens with ⌘K / Ctrl+K when `hotkey` is true.
 */
export interface Command { id: string; label: string; group?: string; icon?: React.ReactNode; shortcut?: string[] }

export interface CommandBarProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  commands: Command[];
  onCommand: (id: string) => void;
  /** Omit to hide the "Ask AI" row (plain command palette) */
  onAsk?: (query: string) => void;
  placeholder?: string;
  hotkey?: boolean;
}

export function CommandBar({ open, onOpenChange, commands, onCommand, onAsk, placeholder = "Search or ask AI…", hotkey = true }: CommandBarProps) {
  const [q, setQ] = React.useState("");
  const [active, setActive] = React.useState(0);
  const listRef = React.useRef<HTMLUListElement>(null);

  React.useEffect(() => {
    if (!hotkey) return;
    const k = (e: KeyboardEvent) => { if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "k") { e.preventDefault(); onOpenChange(!open); } };
    window.addEventListener("keydown", k);
    return () => window.removeEventListener("keydown", k);
  }, [hotkey, open, onOpenChange]);
  React.useEffect(() => { if (open) { setQ(""); setActive(0); } }, [open]);

  const filtered = commands.filter((c) => c.label.toLowerCase().includes(q.toLowerCase()));
  const rows: ({ kind: "ask" } | { kind: "cmd"; c: Command })[] = [...(q.trim() && onAsk ? [{ kind: "ask" as const }] : []), ...filtered.map((c) => ({ kind: "cmd" as const, c }))];
  const run = (i: number) => {
    const r = rows[i];
    if (!r) return;
    r.kind === "ask" ? onAsk?.(q) : onCommand(r.c.id);
    onOpenChange(false);
  };
  React.useEffect(() => { listRef.current?.querySelector(`[data-i="${active}"]`)?.scrollIntoView({ block: "nearest" }); }, [active]);

  let lastGroup: string | undefined;
  return (
    <Dialog open={open} onClose={() => onOpenChange(false)} label="Command bar" position="top" showClose={false} className="max-w-xl overflow-hidden">
      <div
        onKeyDown={(e) => {
          if (e.key === "ArrowDown") { e.preventDefault(); setActive((a) => Math.min(a + 1, rows.length - 1)); }
          if (e.key === "ArrowUp") { e.preventDefault(); setActive((a) => Math.max(a - 1, 0)); }
          if (e.key === "Enter") { e.preventDefault(); run(active); }
        }}
      >
        <label className="flex h-12 items-center gap-3 border-b border-border px-4">
          <Search className="size-4 shrink-0 text-fg-subtle" />
          <input data-autofocus value={q} onChange={(e) => { setQ(e.target.value); setActive(0); }} placeholder={placeholder} aria-label="Search or ask" className="min-w-0 flex-1 bg-transparent text-base text-fg placeholder:text-fg-subtle focus:outline-none" />
          <Kbd>Esc</Kbd>
        </label>
        <ul ref={listRef} role="listbox" className="max-h-80 overflow-y-auto p-2">
          {rows.map((r, i) => {
            if (r.kind === "ask")
              return (
                <li key="ask" data-i={i} role="option" aria-selected={active === i} onMouseEnter={() => setActive(i)} onClick={() => run(i)} className={cn("flex h-11 cursor-pointer items-center gap-3 rounded-md px-3", active === i && "bg-surface-2")}>
                  <span className="grid size-6 place-items-center rounded-sm bg-fg text-bg"><Sparkles className="size-3.5" /></span>
                  <span className="min-w-0 flex-1 truncate text-base text-fg">Ask AI: <span className="font-medium">{q}</span></span>
                  <ArrowRight className="size-4 text-fg-subtle" />
                </li>
              );
            const showGroup = r.c.group && r.c.group !== lastGroup;
            lastGroup = r.c.group;
            return (
              <React.Fragment key={r.c.id}>
                {showGroup && <li role="presentation" className="px-3 pb-1 pt-3 text-xs font-medium text-fg-subtle">{r.c.group}</li>}
                <li data-i={i} role="option" aria-selected={active === i} onMouseEnter={() => setActive(i)} onClick={() => run(i)} className={cn("flex h-9 cursor-pointer items-center gap-3 rounded-md px-3 text-base text-fg-muted", active === i && "bg-surface-2 text-fg")}>
                  <span className="text-fg-subtle [&_svg]:size-4">{r.c.icon}</span>
                  <span className="flex-1 truncate">{r.c.label}</span>
                  {r.c.shortcut && <span className="flex gap-1">{r.c.shortcut.map((k) => <Kbd key={k}>{k}</Kbd>)}</span>}
                </li>
              </React.Fragment>
            );
          })}
          {!rows.length && <li className="px-3 py-8 text-center text-sm text-fg-subtle">{q ? "No results" : "Type to search"}</li>}
        </ul>
        <div className="flex h-10 items-center gap-4 border-t border-border bg-surface px-4 text-xs text-fg-subtle">
          <span className="flex items-center gap-1"><Kbd>↑</Kbd><Kbd>↓</Kbd>navigate</span>
          <span className="flex items-center gap-1"><Kbd><CornerDownLeft className="size-2.5" /></Kbd>select</span>
        </div>
      </div>
    </Dialog>
  );
}

components/ai/confidence.tsx.source:
import * as React from "react";
import { AlertTriangle, CircleCheck, CircleHelp, ExternalLink } from "lucide-react";
import { cn } from "../../lib/cn";

/**
 * Confidence & Verify
 * Honest signals about how much to trust an answer.
 * - <ConfidenceBadge level/> next to a claim or at the top of a result
 * - <VerifyNote/> under answers in high-stakes domains (medical, legal, finance, numbers)
 * Only show confidence if your system can actually estimate it — fake confidence erodes trust.
 */
export type ConfidenceLevel = "high" | "medium" | "low";

const meta: Record<ConfidenceLevel, { label: string; cls: string; Icon: typeof CircleCheck; hint: string }> = {
  high: { label: "High confidence", cls: "bg-success/10 text-success", Icon: CircleCheck, hint: "Backed by multiple consistent sources." },
  medium: { label: "Medium confidence", cls: "bg-warning/10 text-warning", Icon: CircleHelp, hint: "Some sources disagree or are dated." },
  low: { label: "Low confidence", cls: "bg-danger/10 text-danger", Icon: AlertTriangle, hint: "Limited or conflicting evidence. Verify before relying on this." },
};

export function ConfidenceBadge({ level, showHint, className }: { level: ConfidenceLevel; showHint?: boolean; className?: string }) {
  const m = meta[level];
  return (
    <span className={cn("inline-flex flex-col gap-1", className)}>
      <span className={cn("inline-flex h-6 w-fit items-center gap-1.5 rounded-full px-2.5 text-xs font-medium", m.cls)} title={m.hint}>
        <m.Icon className="size-3.5" />{m.label}
      </span>
      {showHint && <span className="text-xs text-fg-subtle">{m.hint}</span>}
    </span>
  );
}

export function VerifyNote({ children, href, linkLabel = "Learn more", className }: { children?: React.ReactNode; href?: string; linkLabel?: string; className?: string }) {
  return (
    <p className={cn("flex items-start gap-2 rounded-md border border-border bg-surface px-3 py-2 text-xs text-fg-muted", className)}>
      <AlertTriangle className="mt-px size-3.5 shrink-0 text-warning" />
      <span>
        {children ?? "AI can make mistakes. Double-check important facts with a qualified source."}
        {href && <a href={href} target="_blank" rel="noreferrer" className="ml-1 inline-flex items-center gap-0.5 font-medium text-fg underline-offset-4 hover:underline">{linkLabel}<ExternalLink className="size-3" /></a>}
      </span>
    </p>
  );
}

/** Highlight a span the model is unsure about; hover explains why. */
export function UncertainText({ children, reason }: { children: React.ReactNode; reason: string }) {
  return (
    <mark title={reason} className="cursor-help rounded-xs bg-warning/15 px-0.5 text-inherit underline decoration-warning/60 decoration-dotted underline-offset-4">{children}</mark>
  );
}

components/ai/confirmation.tsx.source:
"use client";

import * as React from "react";
import { Check, ShieldAlert, X } from "lucide-react";
import { cn } from "../../lib/cn";
import { Button } from "../ui/button";

/**
 * Confirmation
 * Human-in-the-loop approval before an agent does something consequential
 * (sends email, spends money, deletes data, writes to production).
 * Rules: say exactly what will happen, show the target, make "Deny" as easy as "Approve".
 */
export type ConfirmationState = "pending" | "approved" | "denied";

export interface ConfirmationProps {
  title: string;
  description?: React.ReactNode;
  /** Key facts about the action — shown as a definition list */
  details?: { label: string; value: React.ReactNode }[];
  state?: ConfirmationState;
  risk?: "low" | "high";
  approveLabel?: string;
  denyLabel?: string;
  onApprove?: () => void;
  onDeny?: () => void;
  /** Optional "always allow" for this tool */
  onAlwaysAllow?: () => void;
  className?: string;
}

export function Confirmation({ title, description, details, state = "pending", risk = "low", approveLabel = "Approve", denyLabel = "Deny", onApprove, onDeny, onAlwaysAllow, className }: ConfirmationProps) {
  return (
    <div role="group" aria-label={title} className={cn("overflow-hidden rounded-lg border bg-bg text-sm", risk === "high" && state === "pending" ? "border-warning/40" : "border-border", className)}>
      <div className="flex gap-3 p-4">
        <span className={cn("grid size-8 shrink-0 place-items-center rounded-full", risk === "high" ? "bg-warning/10 text-warning" : "bg-surface-2 text-fg-muted")}>
          <ShieldAlert className="size-4" />
        </span>
        <div className="min-w-0 flex-1">
          <p className="text-base font-medium text-fg">{title}</p>
          {description && <p className="mt-1 text-fg-muted">{description}</p>}
          {details && (
            <dl className="mt-3 grid grid-cols-[auto_1fr] gap-x-4 gap-y-1 rounded-md bg-surface p-3 text-sm">
              {details.map((d) => (
                <React.Fragment key={d.label}>
                  <dt className="text-fg-subtle">{d.label}</dt>
                  <dd className="min-w-0 truncate text-fg">{d.value}</dd>
                </React.Fragment>
              ))}
            </dl>
          )}
        </div>
      </div>
      <div className="flex min-h-12 items-center gap-2 border-t border-border bg-surface px-4 py-2">
        {state === "pending" ? (
          <>
            {onAlwaysAllow && <button type="button" onClick={onAlwaysAllow} className="mr-auto text-sm text-fg-muted underline-offset-4 hover:text-fg hover:underline">Always allow</button>}
            <div className="ml-auto flex gap-2">
              <Button size="sm" variant="outline" onClick={onDeny}>{denyLabel}</Button>
              <Button size="sm" onClick={onApprove}>{approveLabel}</Button>
            </div>
          </>
        ) : (
          <p className={cn("inline-flex items-center gap-2 text-sm font-medium", state === "approved" ? "text-success" : "text-fg-muted")} role="status">
            {state === "approved" ? <Check className="size-4" /> : <X className="size-4" />}
            {state === "approved" ? "Approved" : "Denied — the agent will not continue with this action"}
          </p>
        )}
      </div>
    </div>
  );
}

components/ai/connectors.tsx.source:
"use client";

import * as React from "react";
import { AlertTriangle, Check, MoreHorizontal, RefreshCw } from "lucide-react";
import { cn } from "../../lib/cn";
import { Button } from "../ui/button";
import { Spinner } from "../ui/spinner";
import { DropdownMenu } from "../ui/menu";

/**
 * Connectors
 * Tiles for connecting the apps your AI reads from. Every state has its own look and
 * exactly one obvious next action: Connect → Connecting… → Connected (manage) / Syncing / Error (reconnect).
 */
export type ConnectorStatus = "disconnected" | "connecting" | "connected" | "syncing" | "error";

export interface ConnectorCardProps {
  name: string;
  description: string;
  icon: React.ReactNode;
  status: ConnectorStatus;
  /** Signed-in account, e.g. "maya@acme.com" */
  account?: string;
  /** e.g. "Synced 5 min ago" / "Syncing 128 of 412 files" */
  detail?: string;
  error?: string;
  onConnect?: () => void;
  onDisconnect?: () => void;
  onSync?: () => void;
  onSettings?: () => void;
  className?: string;
}

export function ConnectorCard({ name, description, icon, status, account, detail, error, onConnect, onDisconnect, onSync, onSettings, className }: ConnectorCardProps) {
  const live = status === "connected" || status === "syncing";
  return (
    <div className={cn("flex flex-col rounded-xl border bg-bg p-4 transition-colors", status === "error" ? "border-danger/30" : "border-border", className)}>
      <div className="flex items-start gap-3">
        <span className="grid size-10 shrink-0 place-items-center rounded-lg border border-border bg-surface text-fg [&_svg]:size-5">{icon}</span>
        <div className="min-w-0 flex-1">
          <p className="flex items-center gap-2 text-sm font-semibold text-fg">
            <span className="truncate">{name}</span>
            {live && <span className="inline-flex shrink-0 items-center gap-1 text-xs font-medium text-success"><Check className="size-3" strokeWidth={3} />Connected</span>}
          </p>
          <p className="mt-0.5 line-clamp-2 text-sm text-fg-muted">{description}</p>
        </div>
        {live && (onDisconnect || onSettings || onSync) && (
          <DropdownMenu align="end" trigger={<button type="button" aria-label={`${name} options`} className="grid size-8 shrink-0 place-items-center rounded-sm text-fg-subtle hover:bg-surface-2 hover:text-fg"><MoreHorizontal className="size-4" /></button>}
            items={[
              ...(onSync ? [{ label: "Sync now", icon: <RefreshCw />, onSelect: onSync }] : []),
              ...(onSettings ? [{ label: "Settings", onSelect: onSettings }] : []),
              ...(onDisconnect ? [{ type: "separator" as const }, { label: "Disconnect", danger: true, onSelect: onDisconnect }] : []),
            ]} />
        )}
      </div>

      <div className="mt-4 flex min-h-8 items-center gap-2">
        {status === "disconnected" && <Button size="sm" variant="outline" onClick={onConnect}>Connect</Button>}
        {status === "connecting" && <Button size="sm" variant="outline" disabled><Spinner className="size-3.5" />Waiting for {name}…</Button>}
        {status === "connected" && <p className="min-w-0 truncate text-xs text-fg-subtle">{[account, detail].filter(Boolean).join(" · ")}</p>}
        {status === "syncing" && <p className="flex min-w-0 items-center gap-2 text-xs text-fg-muted"><Spinner className="size-3 shrink-0" /><span className="truncate">{detail ?? "Syncing…"}</span></p>}
        {status === "error" && (
          <>
            <p className="flex min-w-0 flex-1 items-center gap-1.5 text-xs text-danger"><AlertTriangle className="size-3.5 shrink-0" /><span className="truncate">{error ?? "Connection lost"}</span></p>
            <Button size="sm" variant="outline" onClick={onConnect} className="shrink-0">Reconnect</Button>
          </>
        )}
      </div>
    </div>
  );
}

export function ConnectorGrid({ className, ...p }: React.HTMLAttributes<HTMLDivElement>) {
  return <div className={cn("grid w-full gap-3 sm:grid-cols-2", className)} {...p} />;
}

