"use client";

import * as React from "react";
import { cn } from "../../lib/cn";
import { Button } from "../ui/button";
import { Dialog } from "../ui/dialog";

/**
 * FeedbackDialog
 * Opens after 👎 to learn *why*. One tap on a reason is enough; the text box is optional.
 * The reasons map to issues you can actually fix — keep them specific.
 */
export const defaultReasons = ["Not factually correct", "Didn't follow instructions", "Too long", "Too short", "Unsafe or harmful", "Out of date", "Other"];

export interface FeedbackDialogProps {
  open: boolean;
  onClose: () => void;
  onSubmit: (data: { reasons: string[]; comment: string }) => void;
  reasons?: string[];
  title?: string;
}

export function FeedbackDialog({ open, onClose, onSubmit, reasons = defaultReasons, title = "What went wrong?" }: FeedbackDialogProps) {
  const [picked, setPicked] = React.useState<string[]>([]);
  const [comment, setComment] = React.useState("");
  React.useEffect(() => { if (open) { setPicked([]); setComment(""); } }, [open]);
  const toggle = (r: string) => setPicked((p) => (p.includes(r) ? p.filter((x) => x !== r) : [...p, r]));

  return (
    <Dialog open={open} onClose={onClose} labelledBy="pl-fb-title" className="max-w-md">
      <form className="p-6" onSubmit={(e) => { e.preventDefault(); onSubmit({ reasons: picked, comment }); }}>
        <h2 id="pl-fb-title" className="pr-8 text-xl font-semibold text-fg">{title}</h2>
        <p className="mt-1 text-sm text-fg-muted">Your feedback helps improve future answers.</p>
        <div className="mt-6 flex flex-wrap gap-2" role="group" aria-label="Reasons">
          {reasons.map((r) => (
            <button
              key={r}
              type="button"
              aria-pressed={picked.includes(r)}
              onClick={() => toggle(r)}
              className={cn("h-8 rounded-full border px-3 text-sm transition-colors", picked.includes(r) ? "border-fg bg-fg text-bg" : "border-border text-fg-muted hover:border-border-strong hover:text-fg")}
            >
              {r}
            </button>
          ))}
        </div>
        <label className="mt-6 block text-sm font-medium text-fg" htmlFor="pl-fb-comment">Anything else? <span className="font-normal text-fg-subtle">(optional)</span></label>
        <textarea id="pl-fb-comment" value={comment} onChange={(e) => setComment(e.target.value)} rows={3} placeholder="What should the answer have said?" className="mt-2 w-full resize-none rounded-md border border-border bg-bg px-3 py-2 text-base text-fg shadow-xs placeholder:text-fg-subtle focus:border-border-strong focus:outline-none focus:ring-4 focus:ring-fg/5" />
        <div className="mt-6 flex justify-end gap-2">
          <Button variant="outline" onClick={onClose}>Cancel</Button>
          <Button type="submit" disabled={!picked.length && !comment.trim()}>Send feedback</Button>
        </div>
      </form>
    </Dialog>
  );
}

components/ai/file-tree.tsx.source:
"use client";

import * as React from "react";
import { ChevronRight, File, Folder, FolderOpen } from "lucide-react";
import { cn } from "../../lib/cn";

/**
 * FileTree
 * Project files for coding agents, with change markers: A (added), M (modified), D (deleted).
 * Folders roll up change counts so users see where the agent worked without expanding everything.
 * Keyboard: ↑ ↓ move, → expand / enter folder, ← collapse / go to parent, Enter select.
 */
export type ChangeKind = "added" | "modified" | "deleted";
export interface TreeNode { name: string; path: string; children?: TreeNode[]; change?: ChangeKind }

export interface FileTreeProps {
  nodes: TreeNode[];
  selected?: string;
  onSelect?: (path: string) => void;
  defaultExpanded?: string[];
  className?: string;
}

const mark: Record<ChangeKind, { label: string; cls: string }> = {
  added: { label: "A", cls: "text-success" },
  modified: { label: "M", cls: "text-warning" },
  deleted: { label: "D", cls: "text-danger" },
};

const countChanges = (n: TreeNode): number => (n.children ? n.children.reduce((s, c) => s + countChanges(c), 0) : n.change ? 1 : 0);

export function FileTree({ nodes, selected, onSelect, defaultExpanded = [], className }: FileTreeProps) {
  const [open, setOpen] = React.useState<Set<string>>(new Set(defaultExpanded));
  const [focus, setFocus] = React.useState<string | null>(null);
  const ref = React.useRef<HTMLUListElement>(null);

  const flat: { node: TreeNode; depth: number; parent?: string }[] = [];
  const walk = (list: TreeNode[], depth: number, parent?: string) => list.forEach((n) => { flat.push({ node: n, depth, parent }); if (n.children && open.has(n.path)) walk(n.children, depth + 1, n.path); });
  walk(nodes, 0);

  const toggle = (p: string, v?: boolean) => setOpen((s) => { const n = new Set(s); (v ?? !n.has(p)) ? n.add(p) : n.delete(p); return n; });
  React.useEffect(() => { if (focus) (ref.current?.querySelector(`[data-path="${CSS.escape(focus)}"]`) as HTMLElement | null)?.focus(); }, [focus]);

  return (
    <ul
      ref={ref}
      role="tree"
      aria-label="Files"
      className={cn("select-none py-1 font-mono text-sm", className)}
      onKeyDown={(e) => {
        const i = flat.findIndex((f) => f.node.path === (focus ?? selected));
        const cur = flat[i];
        if (!cur) return;
        if (e.key === "ArrowDown") { e.preventDefault(); setFocus(flat[Math.min(i + 1, flat.length - 1)].node.path); }
        if (e.key === "ArrowUp") { e.preventDefault(); setFocus(flat[Math.max(i - 1, 0)].node.path); }
        if (e.key === "ArrowRight" && cur.node.children) { e.preventDefault(); open.has(cur.node.path) ? setFocus(flat[i + 1]?.node.path ?? cur.node.path) : toggle(cur.node.path, true); }
        if (e.key === "ArrowLeft") { e.preventDefault(); cur.node.children && open.has(cur.node.path) ? toggle(cur.node.path, false) : cur.parent && setFocus(cur.parent); }
        if (e.key === "Enter") { e.preventDefault(); cur.node.children ? toggle(cur.node.path) : onSelect?.(cur.node.path); }
      }}
    >
      {flat.map(({ node, depth }, i) => {
        const isDir = !!node.children;
        const isOpen = open.has(node.path);
        const changes = isDir ? countChanges(node) : 0;
        const tabbable = (focus ?? selected ?? flat[0]?.node.path) === node.path;
        return (
          <li
            key={node.path}
            role="treeitem"
            data-path={node.path}
            aria-expanded={isDir ? isOpen : undefined}
            aria-selected={selected === node.path}
            aria-level={depth + 1}
            tabIndex={tabbable ? 0 : -1}
            onClick={() => { setFocus(node.path); isDir ? toggle(node.path) : onSelect?.(node.path); }}
            className={cn(
              "flex h-7 cursor-default items-center gap-1.5 rounded-sm pr-2 text-fg-muted outline-none hover:bg-surface-2 hover:text-fg focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-fg/20",
              selected === node.path && "bg-surface-2 text-fg",
              node.change === "deleted" && "line-through decoration-danger/50"
            )}
            style={{ paddingLeft: 8 + depth * 16 }}
          >
            {isDir ? <ChevronRight className={cn("size-3.5 shrink-0 transition-transform", isOpen && "rotate-90")} /> : <span className="w-3.5 shrink-0" />}
            {isDir ? (isOpen ? <FolderOpen className="size-4 shrink-0" /> : <Folder className="size-4 shrink-0" />) : <File className="size-4 shrink-0" />}
            <span className="min-w-0 flex-1 truncate">{node.name}</span>
            {isDir && changes > 0 && !isOpen && <span className="size-1.5 rounded-full bg-warning" aria-label={`${changes} changes`} />}
            {node.change && <span className={cn("w-3 text-center text-xs font-semibold", mark[node.change].cls)} aria-label={node.change}>{mark[node.change].label}</span>}
          </li>
        );
      })}
    </ul>
  );
}

components/ai/generate-button.tsx.source:
"use client";

import * as React from "react";
import { Check, Sparkles, Square } from "lucide-react";
import { cn } from "../../lib/cn";
import { Spinner } from "../ui/spinner";

/**
 * GenerateButton
 * The single "✨ Generate" button that appears all over AI products (write a description,
 * fill a form, summarise). States: idle → generating (cancellable) → done (brief check) → idle.
 * Keeps its width while the label changes so the layout doesn't shift.
 */
export type GenerateState = "idle" | "generating" | "done";

export interface GenerateButtonProps {
  state: GenerateState;
  onGenerate: () => void;
  onCancel?: () => void;
  label?: string;
  generatingLabel?: string;
  doneLabel?: string;
  variant?: "primary" | "outline" | "ghost";
  size?: "sm" | "md";
  className?: string;
}

export function GenerateButton({ state, onGenerate, onCancel, label = "Generate", generatingLabel = "Generating…", doneLabel = "Done", variant = "outline", size = "md", className }: GenerateButtonProps) {
  const v = {
    primary: "bg-accent text-accent-fg hover:bg-accent/85",
    outline: "border border-border bg-bg text-fg shadow-xs hover:bg-surface-2 hover:border-border-strong",
    ghost: "text-fg-muted hover:bg-surface-2 hover:text-fg",
  }[variant];
  const s = size === "sm" ? "h-8 px-3 text-sm gap-1.5" : "h-9 px-4 text-base gap-2";
  const gen = state === "generating";

  return (
    <button
      type="button"
      onClick={gen ? onCancel : onGenerate}
      aria-live="polite"
      aria-busy={gen}
      className={cn("group/gen relative inline-grid place-items-center rounded-md font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-fg/20 [&_svg]:size-4", v, s, className)}
    >
      {/* width reservation: render all labels invisibly in the same cell */}
      {[label, generatingLabel, doneLabel].map((l) => <span key={l} aria-hidden className="invisible col-start-1 row-start-1 flex items-center gap-2"><Sparkles />{l}</span>)}
      <span className="col-start-1 row-start-1 flex items-center gap-2">
        {state === "idle" && <><Sparkles />{label}</>}
        {gen && (
          <>
            <span className="relative grid place-items-center">
              <Spinner className="size-4 group-hover/gen:opacity-0" />
              {onCancel && <Square className="absolute !size-3 fill-current opacity-0 group-hover/gen:opacity-100" />}
            </span>
            <span className="group-hover/gen:hidden">{generatingLabel}</span>
            {onCancel && <span className="hidden group-hover/gen:inline">Stop</span>}
          </>
        )}
        {state === "done" && <><Check className="text-success" />{doneLabel}</>}
      </span>
    </button>
  );
}

