"use client";

import * as React from "react";
import { Download, Expand, RotateCcw, ImageOff } from "lucide-react";
import { cn } from "../../lib/cn";
import { Button } from "../ui/button";
import { Tooltip } from "../ui/tooltip";
import { Shimmer } from "./loader";

/**
 * GeneratedImage
 * Image output with honest states: generating (progress + prompt echo) → done → error.
 * Reserve the final aspect ratio up front so the layout never jumps.
 */
export interface GeneratedImageProps {
  src?: string;
  alt: string;
  status?: "generating" | "done" | "error";
  progress?: number;
  aspectRatio?: string;
  onRetry?: () => void;
  onExpand?: () => void;
  className?: string;
}

export function GeneratedImage({ src, alt, status = "done", progress, aspectRatio = "1 / 1", onRetry, onExpand, className }: GeneratedImageProps) {
  const download = () => { if (src) Object.assign(document.createElement("a"), { href: src, download: "image.png" }).click(); };
  return (
    <figure className={cn("group relative w-full max-w-sm overflow-hidden rounded-lg border border-border bg-surface", className)} style={{ aspectRatio }}>
      {status === "done" && src && <img src={src} alt={alt} className="size-full object-cover" style={{ animation: "pl-in .4s ease-out" }} />}

      {status === "generating" && (
        <div className="absolute inset-0 flex flex-col items-center justify-center gap-3 p-6 text-center">
          <div className="absolute inset-0 overflow-hidden">
            <div className="absolute inset-0 -translate-x-full bg-gradient-to-r from-transparent via-fg/[0.05] to-transparent" style={{ animation: "pl-shimmer-x 1.8s infinite" }} />
          </div>
          <Shimmer className="text-sm">Creating image…</Shimmer>
          {progress != null && (
            <div className="h-1 w-32 overflow-hidden rounded-full bg-border" role="progressbar" aria-valuenow={progress} aria-valuemin={0} aria-valuemax={100}>
              <div className="h-full rounded-full bg-fg transition-[width] duration-300" style={{ width: `${progress}%` }} />
            </div>
          )}
          <p className="line-clamp-2 max-w-60 text-xs text-fg-subtle">{alt}</p>
        </div>
      )}

      {status === "error" && (
        <div className="absolute inset-0 flex flex-col items-center justify-center gap-3 p-6 text-center">
          <ImageOff className="size-6 text-fg-subtle" />
          <p className="text-sm text-fg-muted">Couldn't create this image.</p>
          {onRetry && <Button size="sm" variant="outline" onClick={onRetry}><RotateCcw />Try again</Button>}
        </div>
      )}

      {status === "done" && src && (
        <div className="absolute right-2 top-2 flex gap-1 opacity-0 transition-opacity focus-within:opacity-100 group-hover:opacity-100 [@media(hover:none)]:opacity-100">
          {onExpand && <Tooltip label="Expand"><Button size="icon-xs" variant="outline" onClick={onExpand} aria-label="Expand image"><Expand /></Button></Tooltip>}
          <Tooltip label="Download"><Button size="icon-xs" variant="outline" onClick={download} aria-label="Download image"><Download /></Button></Tooltip>
        </div>
      )}
      <figcaption className="sr-only">{alt}</figcaption>
    </figure>
  );
}

components/ai/image-variations.tsx.source:
"use client";

import * as React from "react";
import { createPortal } from "react-dom";
import { Check, ChevronLeft, ChevronRight, Download, Maximize2, Shuffle, X } from "lucide-react";
import { cn } from "../../lib/cn";
import { Button } from "../ui/button";

/**
 * ImageVariations
 * A 2×2 grid of generated options. Pick one, open it full screen (← → to browse, Esc to close),
 * or ask for variations of a favourite. Selection is explicit so the next step knows which image to use.
 */
export interface Variation { id: string; src?: string; alt: string }

export interface ImageVariationsProps {
  images: Variation[];
  selected?: string;
  onSelect?: (id: string) => void;
  onVary?: (id: string) => void;
  loading?: boolean;
  className?: string;
}

export function ImageVariations({ images, selected, onSelect, onVary, loading, className }: ImageVariationsProps) {
  const [view, setView] = React.useState<number | null>(null);
  React.useEffect(() => {
    if (view == null) return;
    const k = (e: KeyboardEvent) => {
      if (e.key === "Escape") setView(null);
      if (e.key === "ArrowRight") setView((v) => ((v ?? 0) + 1) % images.length);
      if (e.key === "ArrowLeft") setView((v) => ((v ?? 0) - 1 + images.length) % images.length);
    };
    window.addEventListener("keydown", k);
    return () => window.removeEventListener("keydown", k);
  }, [view, images.length]);

  return (
    <div className={cn("space-y-3", className)}>
      <div role="radiogroup" aria-label="Image options" className="grid grid-cols-2 gap-2">
        {images.map((img, i) => {
          const on = selected === img.id;
          return (
            <div key={img.id} className={cn("group relative aspect-square overflow-hidden rounded-lg bg-surface-2 ring-offset-2 ring-offset-bg transition-shadow", on && "ring-2 ring-fg")}>
              {loading || !img.src ? (
                <div className="absolute inset-0 overflow-hidden"><div className="absolute inset-0 -translate-x-full bg-gradient-to-r from-transparent via-fg/[0.06] to-transparent" style={{ animation: `pl-shimmer-x 1.6s ${i * 0.15}s infinite` }} /></div>
              ) : (
                <>
                  <button type="button" role="radio" aria-checked={on} aria-label={`Option ${i + 1}: ${img.alt}`} onClick={() => onSelect?.(img.id)} className="absolute inset-0 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-fg">
                    <img src={img.src} alt="" className="size-full object-cover transition-transform duration-300 group-hover:scale-[1.02]" />
                  </button>
                  <span className="pointer-events-none absolute left-2 top-2 grid size-6 place-items-center rounded-full bg-bg/90 text-2xs font-semibold text-fg shadow-sm">{on ? <Check className="size-3.5" /> : i + 1}</span>
                  <div className="absolute bottom-2 right-2 flex gap-1 opacity-0 transition-opacity focus-within:opacity-100 group-hover:opacity-100 [@media(hover:none)]:opacity-100">
                    {onVary && <Button size="icon-xs" variant="outline" aria-label="More like this" onClick={() => onVary(img.id)}><Shuffle /></Button>}
                    <Button size="icon-xs" variant="outline" aria-label="View full size" onClick={() => setView(i)}><Maximize2 /></Button>
                  </div>
                </>
              )}
            </div>
          );
        })}
      </div>
      {!loading && <p className="text-xs text-fg-subtle">{selected ? `Option ${images.findIndex((i) => i.id === selected) + 1} selected` : "Pick an option to continue"}</p>}

      {view != null && createPortal(
        <div className="fixed inset-0 z-[150] flex flex-col bg-black/90 p-4" role="dialog" aria-modal="true" aria-label="Image viewer" style={{ animation: "pl-in .15s ease-out" }}>
          <div className="flex items-center justify-between text-sm text-white/80">
            <span className="tabular-nums">{view + 1} / {images.length}</span>
            <div className="flex gap-1">
              {images[view].src && <a href={images[view].src} download="image.png" aria-label="Download" className="grid size-9 place-items-center rounded-md hover:bg-white/10"><Download className="size-4" /></a>}
              <button type="button" onClick={() => setView(null)} aria-label="Close" className="grid size-9 place-items-center rounded-md hover:bg-white/10"><X className="size-4" /></button>
            </div>
          </div>
          <div className="relative flex min-h-0 flex-1 items-center justify-center">
            <button type="button" onClick={() => setView((view - 1 + images.length) % images.length)} aria-label="Previous" className="absolute left-0 grid size-10 place-items-center rounded-full text-white/80 hover:bg-white/10"><ChevronLeft className="size-5" /></button>
            <img src={images[view].src} alt={images[view].alt} className="max-h-full max-w-full rounded-lg object-contain" />
            <button type="button" onClick={() => setView((view + 1) % images.length)} aria-label="Next" className="absolute right-0 grid size-10 place-items-center rounded-full text-white/80 hover:bg-white/10"><ChevronRight className="size-5" /></button>
          </div>
          <div className="flex justify-center pt-3">
            <Button variant="secondary" onClick={() => { onSelect?.(images[view].id); setView(null); }}><Check />Use this image</Button>
          </div>
        </div>,
        document.body
      )}
    </div>
  );
}

components/ai/inline-ai.tsx.source:
"use client";

import * as React from "react";
import { ArrowUp, Check, CornerDownLeft, RotateCcw, Sparkles, X } from "lucide-react";
import { cn } from "../../lib/cn";
import { Button } from "../ui/button";
import { Kbd } from "../ui/kbd";
import { Spinner } from "../ui/spinner";

/**
 * InlineAI
 * AI inside a document or editor instead of a chat: select text → quick actions or a custom instruction
 * → a suggested rewrite shown as a diff → Accept / Retry / Discard.
 * Keeps the user in their work; the AI edits in place.
 */
export interface InlineAIAction { id: string; label: string; icon?: React.ReactNode }

export const defaultInlineActions: InlineAIAction[] = [
  { id: "improve", label: "Improve writing" },
  { id: "shorten", label: "Make shorter" },
  { id: "friendly", label: "Friendlier tone" },
  { id: "fix", label: "Fix spelling & grammar" },
];

export type InlineAIState = "idle" | "generating" | "review";

export interface InlineAIProps {
  /** The selected text */
  original: string;
  /** The AI rewrite (shown in review state) */
  suggestion?: string;
  state: InlineAIState;
  actions?: InlineAIAction[];
  onAction: (id: string) => void;
  onPrompt: (instruction: string) => void;
  onAccept: () => void;
  onRetry: () => void;
  onDiscard: () => void;
  className?: string;
}

export function InlineAI({ original, suggestion, state, actions = defaultInlineActions, onAction, onPrompt, onAccept, onRetry, onDiscard, className }: InlineAIProps) {
  const [instruction, setInstruction] = React.useState("");
  return (
    <div
      role="dialog"
      aria-label="Edit with AI"
      className={cn("w-full max-w-md overflow-hidden rounded-lg border border-border bg-bg text-sm shadow-lg", className)}
      style={{ animation: "pl-pop .15s var(--ease-out)" }}
      onKeyDown={(e) => { if (e.key === "Escape") onDiscard(); }}
    >
      {state !== "review" ? (
        <>
          <form onSubmit={(e) => { e.preventDefault(); if (instruction.trim()) onPrompt(instruction); }} className="flex h-11 items-center gap-2 border-b border-border px-3">
            {state === "generating" ? <Spinner className="size-4 text-fg-muted" /> : <Sparkles className="size-4 shrink-0 text-fg-muted" />}
            <input
              autoFocus
              disabled={state === "generating"}
              value={instruction}
              onChange={(e) => setInstruction(e.target.value)}
              placeholder={state === "generating" ? "Writing…" : "Tell AI what to do with the selection…"}
              aria-label="Instruction"
              className="min-w-0 flex-1 bg-transparent text-sm text-fg placeholder:text-fg-subtle focus:outline-none disabled:opacity-60"
            />
            <Button type="submit" size="icon-xs" disabled={!instruction.trim() || state === "generating"} aria-label="Run" className="rounded-full"><ArrowUp /></Button>
          </form>
          <ul className="p-1" role="menu" aria-label="Quick actions">
            {actions.map((a) => (
              <li key={a.id} role="none">
                <button type="button" role="menuitem" disabled={state === "generating"} onClick={() => onAction(a.id)} className="flex h-8 w-full items-center gap-2 rounded-sm px-2 text-left text-fg-muted transition-colors hover:bg-surface-2 hover:text-fg disabled:opacity-50 [&_svg]:size-4">
                  {a.icon}{a.label}
                </button>
              </li>
            ))}
          </ul>
        </>
      ) : (
        <>
          <div className="space-y-2 p-3">
            <p className="text-xs font-medium text-fg-subtle">Suggested edit</p>
            <p className="rounded-sm bg-danger/[0.06] px-2 py-1 text-fg-muted line-through decoration-danger/40">{original}</p>
            <p className="rounded-sm bg-success/[0.08] px-2 py-1 text-fg">{suggestion}</p>
          </div>
          <div className="flex items-center gap-2 border-t border-border bg-surface px-3 py-2">
            <Button size="xs" onClick={onAccept} autoFocus><Check />Accept <Kbd className="ml-1 border-accent-fg/20 bg-transparent text-accent-fg/70"><CornerDownLeft className="!size-2.5" /></Kbd></Button>
            <Button size="xs" variant="ghost" onClick={onRetry}><RotateCcw />Retry</Button>
            <Button size="xs" variant="ghost" onClick={onDiscard} className="ml-auto"><X />Discard</Button>
          </div>
        </>
      )}
    </div>
  );
}

/** Floating trigger shown next to a text selection. */
export function InlineAITrigger({ onClick, className }: { onClick: () => void; className?: string }) {
  return (
    <button type="button" onClick={onClick} className={cn("inline-flex h-8 items-center gap-1.5 rounded-md border border-border bg-bg px-2.5 text-sm font-medium text-fg shadow-md transition-colors hover:bg-surface-2", className)}>
      <Sparkles className="size-3.5" />Edit with AI <Kbd>⌘J</Kbd>
    </button>
  );
}

components/ai/inline-citation.tsx.source:
"use client";

import * as React from "react";
import { ChevronLeft, ChevronRight } from "lucide-react";
import { cn } from "../../lib/cn";
import { Favicon, hostOf, type SourceItem } from "./sources";

/**
 * InlineCitation
 * A pill placed right after the claim it supports: "…reduces wait time [nngroup.com +1]".
 * Hover or focus opens a preview card; multiple sources page with ‹ ›.
 * Show the domain, not a bare number — users trust names, not footnotes.
 */
export function InlineCitation({ sources, className }: { sources: SourceItem[]; className?: string }) {
  const [open, setOpen] = React.useState(false);
  const [i, setI] = React.useState(0);
  const t = React.useRef<number | undefined>(undefined);
  const show = () => { window.clearTimeout(t.current); setOpen(true); };
  const hide = () => { t.current = window.setTimeout(() => setOpen(false), 120); };
  const s = sources[i];
  if (!s) return null;

  return (
    <span className={cn("relative inline-block align-baseline", className)} onMouseEnter={show} onMouseLeave={hide} onFocus={show} onBlur={hide}>
      <a
        href={sources[0].url}
        target="_blank"
        rel="noreferrer"
        className="ml-1 inline-flex h-5 items-center gap-1 rounded-full bg-surface-2 px-2 align-[1px] text-2xs font-medium text-fg-muted no-underline transition-colors hover:bg-fg hover:text-bg"
      >
        {hostOf(sources[0].url)}
        {sources.length > 1 && <span className="opacity-70">+{sources.length - 1}</span>}
      </a>
      {open && (
        <span
          role="tooltip"
          className="absolute bottom-full left-0 z-50 mb-2 block w-72 rounded-lg border border-border bg-bg p-3 text-left shadow-lg"
          style={{ animation: "pl-pop .15s var(--ease-out)" }}
          onMouseEnter={show}
          onMouseLeave={hide}
        >
          {sources.length > 1 && (
            <span className="mb-2 flex items-center justify-between text-xs text-fg-subtle">
              <span className="tabular-nums">{i + 1} of {sources.length}</span>
              <span className="flex gap-1">
                <button type="button" aria-label="Previous source" onClick={() => setI((i - 1 + sources.length) % sources.length)} className="grid size-6 place-items-center rounded-xs hover:bg-surface-2 hover:text-fg"><ChevronLeft className="size-3.5" /></button>
                <button type="button" aria-label="Next source" onClick={() => setI((i + 1) % sources.length)} className="grid size-6 place-items-center rounded-xs hover:bg-surface-2 hover:text-fg"><ChevronRight className="size-3.5" /></button>
              </span>
            </span>
          )}
          <a href={s.url} target="_blank" rel="noreferrer" className="block no-underline">
            <span className="flex items-center gap-2 text-xs text-fg-subtle"><Favicon url={s.url} src={s.favicon} className="ring-0" />{hostOf(s.url)}</span>
            <span className="mt-1 block text-sm font-medium text-fg">{s.title}</span>
            {s.description && <span className="mt-1 line-clamp-3 block text-xs text-fg-muted">{s.description}</span>}
          </a>
        </span>
      )}
    </span>
  );
}

components/ai/json-viewer.tsx.source:
"use client";

import * as React from "react";
import { Check, ChevronRight, Copy, ChevronsDownUp, ChevronsUpDown } from "lucide-react";
import { cn } from "../../lib/cn";
import { useCopy } from "../../lib/hooks";

/**
 * JsonViewer
 * Structured output and tool results as a collapsible tree.
 * - Type-coloured values using the syntax tokens
 * - Collapsed nodes show a summary ({4} / [12]) so you can scan without expanding
 * - Copy the whole document, or any value by its row
 * - Expand / collapse all
 */
export interface JsonViewerProps {
  data: unknown;
  /** Levels open on first render (default 2) */
  defaultExpandDepth?: number;
  /** Header label, e.g. the tool name */
  label?: React.ReactNode;
  maxHeight?: number;
  className?: string;
}

type Path = string;

export function JsonViewer({ data, defaultExpandDepth = 2, label = "JSON", maxHeight = 420, className }: JsonViewerProps) {
  const { copied, copy } = useCopy();
  const [mode, setMode] = React.useState<{ all: boolean | null; n: number }>({ all: null, n: 0 });
  const text = React.useMemo(() => JSON.stringify(data, null, 2), [data]);
  return (
    <div className={cn("w-full overflow-hidden rounded-lg border border-border bg-bg", className)}>
      <div className="flex h-10 items-center gap-2 border-b border-border bg-surface px-3">
        <span className="min-w-0 flex-1 truncate font-mono text-xs text-fg-muted">{label}</span>
        <button type="button" onClick={() => setMode((m) => ({ all: !(m.all ?? false), n: m.n + 1 }))} aria-label={mode.all ? "Collapse all" : "Expand all"}
          className="grid size-7 place-items-center rounded-sm text-fg-subtle hover:bg-surface-2 hover:text-fg [&_svg]:size-3.5">
          {mode.all ? <ChevronsDownUp /> : <ChevronsUpDown />}
        </button>
        <button type="button" onClick={() => copy(text)} className="inline-flex h-7 items-center gap-1.5 rounded-sm px-2 text-xs font-medium text-fg-muted hover:bg-surface-2 hover:text-fg [&_svg]:size-3.5">
          {copied ? <Check /> : <Copy />}{copied ? "Copied" : "Copy"}
        </button>
      </div>
      <div role="tree" aria-label="JSON" className="overflow-auto py-2 font-mono text-[13px] leading-6" style={{ maxHeight }}>
        <Node k={null} v={data} depth={0} path="$" defaultDepth={defaultExpandDepth} mode={mode} last />
      </div>
    </div>
  );
}

const isObj = (v: unknown): v is Record<string, unknown> | unknown[] => typeof v === "object" && v !== null;

function Value({ v }: { v: unknown }) {
  if (v === null) return <span className="text-[rgb(var(--syn-keyword))]">null</span>;
  if (typeof v === "string") return <span className="text-[rgb(var(--syn-string))] [overflow-wrap:anywhere]">"{v}"</span>;
  if (typeof v === "number") return <span className="text-[rgb(var(--syn-number))]">{v}</span>;
  if (typeof v === "boolean") return <span className="text-[rgb(var(--syn-keyword))]">{String(v)}</span>;
  return <span className="text-fg-muted">{String(v)}</span>;
}

function Node({ k, v, depth, path, defaultDepth, mode, last }: { k: string | number | null; v: unknown; depth: number; path: Path; defaultDepth: number; mode: { all: boolean | null; n: number }; last: boolean }) {
  const [open, setOpen] = React.useState(depth < defaultDepth);
  const { copied, copy } = useCopy(1200);
  React.useEffect(() => { if (mode.all !== null) setOpen(mode.all); }, [mode.n]); // eslint-disable-line react-hooks/exhaustive-deps
  const pad = { paddingLeft: 26 + depth * 16 };
  const keyEl = k === null ? null : <><span className={typeof k === "number" ? "text-fg-subtle" : "text-[rgb(var(--syn-fn))]"}>{typeof k === "number" ? k : `"${k}"`}</span><span className="text-fg-subtle">: </span></>;
  const comma = last ? null : <span className="text-fg-subtle">,</span>;
  const copyBtn = (
    <button type="button" tabIndex={-1} onClick={(e) => { e.stopPropagation(); copy(typeof v === "string" ? v : JSON.stringify(v, null, 2)); }} aria-label="Copy value"
      className="ml-2 inline-grid size-5 place-items-center rounded-xs align-middle text-fg-subtle opacity-0 hover:bg-surface-2 hover:text-fg group-hover/row:opacity-100 [&_svg]:size-3">
      {copied ? <Check /> : <Copy />}
    </button>
  );

  if (!isObj(v)) {
    return <div role="treeitem" className="group/row whitespace-pre-wrap pr-3 hover:bg-surface" style={pad}>{keyEl}<Value v={v} />{comma}{copyBtn}</div>;
  }
  const arr = Array.isArray(v);
  const entries = arr ? (v as unknown[]).map((x, i) => [i, x] as const) : Object.entries(v);
  const [o, c] = arr ? ["[", "]"] : ["{", "}"];
  return (
    <div role="treeitem" aria-expanded={open}>
      <div className="group/row flex cursor-pointer items-center pr-3 hover:bg-surface" style={{ paddingLeft: pad.paddingLeft - 16 }} onClick={() => setOpen((x) => !x)}
        onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); setOpen((x) => !x); } if (e.key === "ArrowRight") setOpen(true); if (e.key === "ArrowLeft") setOpen(false); }} tabIndex={0}>
        <ChevronRight className={cn("mr-0.5 size-3 shrink-0 text-fg-subtle transition-transform", open && "rotate-90")} />
        <span className="min-w-0">
          {keyEl}<span className="text-fg-muted">{o}</span>
          {!open && <><span className="mx-1 rounded-xs bg-surface-2 px-1 text-xs text-fg-subtle">{entries.length} {arr ? (entries.length === 1 ? "item" : "items") : (entries.length === 1 ? "key" : "keys")}</span><span className="text-fg-muted">{c}</span>{comma}</>}
        </span>
        {copyBtn}
      </div>
      {open && (
        <div role="group">
          {entries.map(([ck, cv], i) => <Node key={String(ck)} k={ck} v={cv} depth={depth + 1} path={`${path}.${ck}`} defaultDepth={defaultDepth} mode={mode} last={i === entries.length - 1} />)}
          <div style={pad} className="text-fg-muted">{c}{comma}</div>
        </div>
      )}
    </div>
  );
}

components/ai/knowledge-upload.tsx.source:
"use client";

import * as React from "react";
import { UploadCloud, FileText, Check, AlertCircle, X, RotateCcw, Loader2 } from "lucide-react";
import { cn } from "../../lib/cn";
import { formatBytes } from "./attachments";

/**
 * KnowledgeUpload
 * Upload documents the assistant should learn from (RAG / knowledge base).
 * Validates type and size up front with specific messages, then shows each file moving through
 * uploading → processing (reading & indexing) → ready (with chunk count) or error (with retry).
 */
export type KnowledgeStatus = "uploading" | "processing" | "ready" | "error";
export interface KnowledgeFile { id: string; name: string; size: number; status: KnowledgeStatus; progress?: number; chunks?: number; error?: string }

export interface KnowledgeUploadProps {
  files: KnowledgeFile[];
  onFiles: (files: File[]) => void;
  onRemove?: (id: string) => void;
  onRetry?: (id: string) => void;
  /** e.g. [".pdf", ".docx", ".md", ".txt", ".csv"] */
  accept?: string[];
  maxSize?: number;
  maxFiles?: number;
  /** Storage used / limit, shown in the footer */
  usage?: { used: number; limit: number };
  className?: string;
}

export function KnowledgeUpload({ files, onFiles, onRemove, onRetry, accept = [".pdf", ".docx", ".md", ".txt", ".csv"], maxSize = 20 * 1048576, maxFiles = 50, usage, className }: KnowledgeUploadProps) {
  const [drag, setDrag] = React.useState(false);
  const [errors, setErrors] = React.useState<string[]>([]);
  const input = React.useRef<HTMLInputElement>(null);

  const take = (list: File[]) => {
    const errs: string[] = [], ok: File[] = [];
    list.forEach((f) => {
      const ext = "." + (f.name.split(".").pop() ?? "").toLowerCase();
      if (!accept.includes(ext)) errs.push(`${f.name}: ${ext.toUpperCase().slice(1)} files aren't supported`);
      else if (f.size > maxSize) errs.push(`${f.name}: larger than ${formatBytes(maxSize)}`);
      else ok.push(f);
    });
    if (files.length + ok.length > maxFiles) { errs.push(`You can add up to ${maxFiles} files`); ok.splice(maxFiles - files.length); }
    setErrors(errs);
    if (ok.length) onFiles(ok);
  };
  const ready = files.filter((f) => f.status === "ready").length;

  return (
    <div className={cn("space-y-3", className)}>
      <div
        role="button"
        tabIndex={0}
        aria-label="Upload files"
        onClick={() => input.current?.click()}
        onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); input.current?.click(); } }}
        onDragOver={(e) => { e.preventDefault(); setDrag(true); }}
        onDragLeave={() => setDrag(false)}
        onDrop={(e) => { e.preventDefault(); setDrag(false); take(Array.from(e.dataTransfer.files)); }}
        className={cn(
          "flex cursor-pointer flex-col items-center justify-center gap-2 rounded-xl border border-dashed px-6 py-8 text-center transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-fg/20",
          drag ? "border-fg bg-surface-2" : "border-border-strong bg-surface hover:bg-surface-2/60"
        )}
      >
        <span className={cn("grid size-10 place-items-center rounded-full border border-border bg-bg shadow-xs transition-transform", drag && "scale-110")}><UploadCloud className="size-5 text-fg-muted" /></span>
        <p className="text-base font-medium text-fg">{drag ? "Drop to upload" : "Drop files or click to upload"}</p>
        <p className="text-xs text-fg-subtle">{accept.map((a) => a.slice(1).toUpperCase()).join(", ")} · up to {formatBytes(maxSize)} each</p>
        <input ref={input} type="file" multiple hidden accept={accept.join(",")} onChange={(e) => { take(Array.from(e.target.files ?? [])); e.target.value = ""; }} />
      </div>

      {errors.length > 0 && (
        <ul className="space-y-1 rounded-md border border-danger/25 bg-danger/[0.04] p-3 text-xs text-danger" role="alert">
          {errors.map((e) => <li key={e} className="flex gap-2"><AlertCircle className="mt-px size-3.5 shrink-0" />{e}</li>)}
        </ul>
      )}

      {files.length > 0 && (
        <ul className="divide-y divide-border overflow-hidden rounded-lg border border-border">
          {files.map((f) => (
            <li key={f.id} className="flex items-center gap-3 px-3 py-2.5">
              <span className={cn("grid size-8 shrink-0 place-items-center rounded-sm", f.status === "error" ? "bg-danger/10 text-danger" : "bg-surface-2 text-fg-muted")}><FileText className="size-4" /></span>
              <div className="min-w-0 flex-1">
                <p className="truncate text-sm font-medium text-fg">{f.name}</p>
                <p className={cn("flex items-center gap-1.5 text-xs", f.status === "error" ? "text-danger" : "text-fg-subtle")} aria-live="polite">
                  {f.status === "uploading" && <>Uploading · {Math.round(f.progress ?? 0)}%</>}
                  {f.status === "processing" && <><Loader2 className="size-3 animate-spin" />Reading and indexing…</>}
                  {f.status === "ready" && <>{formatBytes(f.size)} · {f.chunks ?? 0} chunks</>}
                  {f.status === "error" && (f.error ?? "Couldn't process this file")}
                </p>
                {f.status === "uploading" && <div className="mt-1.5 h-1 overflow-hidden rounded-full bg-surface-2"><div className="h-full rounded-full bg-fg transition-[width] duration-300" style={{ width: `${f.progress ?? 0}%` }} /></div>}
              </div>
              {f.status === "ready" && <Check className="size-4 shrink-0 text-success" aria-label="Ready" />}
              {f.status === "error" && onRetry && <button type="button" onClick={() => onRetry(f.id)} aria-label={`Retry ${f.name}`} className="grid size-7 place-items-center rounded-sm text-fg-muted hover:bg-surface-2 hover:text-fg"><RotateCcw className="size-3.5" /></button>}
              {onRemove && <button type="button" onClick={() => onRemove(f.id)} aria-label={`Remove ${f.name}`} className="grid size-7 place-items-center rounded-sm text-fg-subtle hover:bg-surface-2 hover:text-fg"><X className="size-3.5" /></button>}
            </li>
          ))}
        </ul>
      )}

      {(files.length > 0 || usage) && (
        <div className="flex items-center justify-between text-xs text-fg-subtle">
          <span>{ready} of {files.length} ready</span>
          {usage && <span className="tabular-nums">{formatBytes(usage.used)} of {formatBytes(usage.limit)} used</span>}
        </div>
      )}
    </div>
  );
}

components/ai/loader.tsx.source:
import * as React from "react";
import { cn } from "../../lib/cn";

/**
 * Loader & streaming states
 * - <Loader variant="dots" | "pulse" | "bars" /> before the first token (show within 300ms of submit)
 * - <Shimmer>Searching the web…</Shimmer> for live status text
 * - <StreamingCursor/> appended to text while it streams
 */
export function Loader({ variant = "dots", label, className }: { variant?: "dots" | "pulse" | "bars"; label?: string; className?: string }) {
  return (
    <div role="status" aria-live="polite" className={cn("inline-flex items-center gap-2 text-sm text-fg-muted", className)}>
      {variant === "dots" && (
        <span className="inline-flex gap-1" aria-hidden>
          {[0, 1, 2].map((i) => <span key={i} className="size-1.5 rounded-full bg-current" style={{ animation: `pl-bounce 1.2s ${i * 0.15}s infinite ease-in-out` }} />)}
        </span>
      )}
      {variant === "pulse" && <span aria-hidden className="size-3 rounded-full bg-fg" style={{ animation: "pl-pulse 1.4s ease-in-out infinite" }} />}
      {variant === "bars" && (
        <span className="inline-flex h-4 items-center gap-[3px]" aria-hidden>
          {[0, 1, 2, 3].map((i) => <span key={i} className="h-full w-[3px] origin-center rounded-full bg-current" style={{ animation: `pl-wave 1s ${i * 0.12}s infinite ease-in-out` }} />)}
        </span>
      )}
      {label ? <Shimmer>{label}</Shimmer> : <span className="sr-only">Generating response</span>}
    </div>
  );
}

export function Shimmer({ children, className, as: Tag = "span" }: { children: React.ReactNode; className?: string; as?: "span" | "p" }) {
  return <Tag className={cn("pl-shimmer-text font-medium", className)}>{children}</Tag>;
}

export function StreamingCursor({ className }: { className?: string }) {
  return <span aria-hidden className={cn("ml-0.5 inline-block h-[1em] w-2 translate-y-[2px] rounded-[1px] bg-fg", className)} style={{ animation: "pl-blink 1s steps(2) infinite" }} />;
}

components/ai/memory.tsx.source:
"use client";

import * as React from "react";
import { Brain, Pencil, Search, Trash2 } from "lucide-react";
import { cn } from "../../lib/cn";
import { Button } from "../ui/button";
import { Switch } from "../ui/switch";

/**
 * Memory
 * What the assistant remembers about the user — visible, editable, deletable.
 * - <MemoryUpdated/>: inline chip in the conversation when something new is saved
 * - <MemoryManager/>: settings panel with master toggle, search, edit and delete
 * Users trust memory they can see and control.
 */
export interface MemoryItem { id: string; text: string; date?: string }

export function MemoryUpdated({ text, onManage, className }: { text: string; onManage?: () => void; className?: string }) {
  return (
    <div className={cn("inline-flex max-w-full items-center gap-2 rounded-full border border-border bg-surface py-1 pl-2 pr-3 text-xs text-fg-muted", className)} role="status">
      <Brain className="size-3.5 shrink-0" />
      <span className="truncate">Memory updated: <span className="text-fg">{text}</span></span>
      {onManage && <button type="button" onClick={onManage} className="shrink-0 font-medium text-fg underline-offset-4 hover:underline">Manage</button>}
    </div>
  );
}

export interface MemoryManagerProps {
  enabled: boolean;
  onEnabledChange: (v: boolean) => void;
  items: MemoryItem[];
  onDelete: (id: string) => void;
  onEdit?: (id: string, text: string) => void;
  onClearAll?: () => void;
  className?: string;
}

export function MemoryManager({ enabled, onEnabledChange, items, onDelete, onEdit, onClearAll, className }: MemoryManagerProps) {
  const [q, setQ] = React.useState("");
  const [editing, setEditing] = React.useState<string | null>(null);
  const [draft, setDraft] = React.useState("");
  const list = items.filter((i) => i.text.toLowerCase().includes(q.toLowerCase()));

  return (
    <section className={cn("overflow-hidden rounded-lg border border-border bg-bg text-sm", className)} aria-labelledby="pl-mem-title">
      <div className="flex items-start gap-4 p-4">
        <div className="flex-1">
          <h3 id="pl-mem-title" className="text-base font-medium text-fg">Memory</h3>
          <p className="mt-1 text-fg-muted">Let the assistant remember details across chats to personalise answers.</p>
        </div>
        <Switch checked={enabled} onCheckedChange={onEnabledChange} label="Use memory" />
      </div>
      <div className={cn("border-t border-border", !enabled && "pointer-events-none opacity-50")} aria-disabled={!enabled}>
        <div className="flex items-center gap-2 px-4 py-3">
          <label className="flex h-8 flex-1 items-center gap-2 rounded-sm border border-border px-2 text-fg-subtle focus-within:border-border-strong">
            <Search className="size-3.5" />
            <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search memories" aria-label="Search memories" className="w-full bg-transparent text-sm text-fg placeholder:text-fg-subtle focus:outline-none" />
          </label>
          {onClearAll && <Button size="sm" variant="ghost" onClick={onClearAll} className="text-danger hover:bg-danger/10 hover:text-danger">Clear all</Button>}
        </div>
        <ul className="max-h-72 divide-y divide-border overflow-y-auto border-t border-border">
          {list.map((m) => (
            <li key={m.id} className="group flex items-start gap-3 px-4 py-3">
              {editing === m.id ? (
                <form className="flex flex-1 gap-2" onSubmit={(e) => { e.preventDefault(); onEdit?.(m.id, draft); setEditing(null); }}>
                  <input autoFocus value={draft} onChange={(e) => setDraft(e.target.value)} aria-label="Edit memory" className="h-8 flex-1 rounded-sm border border-border-strong bg-bg px-2 text-sm text-fg focus:outline-none" />
                  <Button size="sm" type="submit">Save</Button>
                  <Button size="sm" variant="ghost" onClick={() => setEditing(null)}>Cancel</Button>
                </form>
              ) : (
                <>
                  <div className="min-w-0 flex-1">
                    <p className="text-fg">{m.text}</p>
                    {m.date && <p className="mt-0.5 text-xs text-fg-subtle">{m.date}</p>}
                  </div>
                  <div className="flex gap-0.5 opacity-0 transition-opacity focus-within:opacity-100 group-hover:opacity-100 [@media(hover:none)]:opacity-100">
                    {onEdit && <button type="button" aria-label="Edit memory" onClick={() => { setEditing(m.id); setDraft(m.text); }} className="grid size-7 place-items-center rounded-sm text-fg-subtle hover:bg-surface-2 hover:text-fg"><Pencil className="size-3.5" /></button>}
                    <button type="button" aria-label="Delete memory" onClick={() => onDelete(m.id)} className="grid size-7 place-items-center rounded-sm text-fg-subtle hover:bg-danger/10 hover:text-danger"><Trash2 className="size-3.5" /></button>
                  </div>
                </>
              )}
            </li>
          ))}
          {!list.length && <li className="px-4 py-8 text-center text-fg-subtle">{items.length ? "No memories match your search" : "Nothing saved yet"}</li>}
        </ul>
      </div>
    </section>
  );
}

components/ai/mention-picker.tsx.source:
"use client";

import * as React from "react";
import { AtSign, Bot, FileText, User, X } from "lucide-react";
import { cn } from "../../lib/cn";

/**
 * MentionPicker
 * Type "@" to reference a file, agent or person. The chosen item becomes a context chip
 * (render `MentionChip`s in the input's attachments slot) and the "@query" text is removed.
 * Wraps any text input through a render prop: pass the provided `onKeyDown` to it.
 */
export type MentionType = "file" | "agent" | "person";

export interface MentionItem {
  id: string;
  label: string;
  type?: MentionType;
  description?: string;
  icon?: React.ReactNode;
}

export interface MentionPickerProps {
  value: string;
  onValueChange: (v: string) => void;
  items: MentionItem[];
  onSelect: (item: MentionItem) => void;
  /** Ids already mentioned — hidden from the list */
  selected?: string[];
  children: (input: { onKeyDown: (e: React.KeyboardEvent) => void; open: boolean }) => React.ReactNode;
  /** Max results shown */
  limit?: number;
  className?: string;
}

const typeIcon: Record<MentionType, React.ReactNode> = { file: <FileText />, agent: <Bot />, person: <User /> };
const typeLabel: Record<MentionType, string> = { file: "Files", agent: "Agents", person: "People" };
const TRIGGER = /(^|\s)@([^\s@]*)$/;

export function MentionPicker({ value, onValueChange, items, onSelect, selected = [], children, limit = 8, className }: MentionPickerProps) {
  const m = TRIGGER.exec(value);
  const [dismissed, setDismissed] = React.useState<string | null>(null);
  const open = !!m && dismissed !== value;
  const q = (m?.[2] ?? "").toLowerCase();
  const results = React.useMemo(
    () => (open ? items.filter((i) => !selected.includes(i.id) && (i.label.toLowerCase().includes(q) || i.description?.toLowerCase().includes(q))).slice(0, limit) : []),
    [open, items, selected, q, limit]
  );
  const [active, setActive] = React.useState(0);
  React.useEffect(() => setActive(0), [q]);
  React.useEffect(() => { if (!m) setDismissed(null); }, [m]);

  const pick = (item: MentionItem) => { onValueChange(value.replace(/@[^\s@]*$/, "")); onSelect(item); };

  const onKeyDown = (e: React.KeyboardEvent) => {
    if (!open) return;
    if (e.key === "ArrowDown") { e.preventDefault(); setActive((a) => (results.length ? (a + 1) % results.length : 0)); }
    else if (e.key === "ArrowUp") { e.preventDefault(); setActive((a) => (results.length ? (a - 1 + results.length) % results.length : 0)); }
    else if ((e.key === "Enter" || e.key === "Tab") && results[active] && !(e.nativeEvent as KeyboardEvent).isComposing) { e.preventDefault(); pick(results[active]); }
    else if (e.key === "Escape") { e.preventDefault(); setDismissed(value); }
  };

  let lastType: MentionType | undefined;
  return (
    <div className={cn("relative", className)}>
      {open && (
        <div role="listbox" aria-label="Mention" className="absolute bottom-full left-0 z-30 mb-2 max-h-64 w-full max-w-xs overflow-y-auto rounded-lg border border-border bg-bg p-1 shadow-lg" style={{ animation: "pl-in .12s ease-out" }} onMouseDown={(e) => e.preventDefault()}>
          {results.length === 0 ? (
            <p className="px-3 py-4 text-center text-sm text-fg-subtle">No matches for “{q}”</p>
          ) : results.map((it, i) => {
            const header = it.type && it.type !== lastType ? typeLabel[it.type] : null;
            lastType = it.type;
            return (
              <React.Fragment key={it.id}>
                {header && <p className="px-2 pb-1 pt-2 text-xs font-medium text-fg-subtle">{header}</p>}
                <div role="option" aria-selected={i === active} onMouseMove={() => setActive(i)} onClick={() => pick(it)}
                  className={cn("flex cursor-pointer items-center gap-2.5 rounded-md px-2 py-1.5", i === active && "bg-surface-2")}>
                  <span className="grid size-6 shrink-0 place-items-center rounded-sm bg-surface-2 text-fg-muted [&_svg]:size-3.5">{it.icon ?? (it.type ? typeIcon[it.type] : <AtSign />)}</span>
                  <span className="min-w-0 flex-1 truncate text-sm text-fg">{it.label}</span>
                  {it.description && <span className="max-w-[45%] shrink-0 truncate text-xs text-fg-subtle">{it.description}</span>}
                </div>
              </React.Fragment>
            );
          })}
        </div>
      )}
      {children({ onKeyDown, open })}
    </div>
  );
}

/** A context chip for a mentioned item — place it in the input's attachments slot. */
export function MentionChip({ item, onRemove, className }: { item: MentionItem; onRemove?: () => void; className?: string }) {
  return (
    <span className={cn("inline-flex h-7 max-w-[14rem] items-center gap-1.5 rounded-md border border-border bg-surface pl-2 pr-1 text-sm text-fg", className)}>
      <span className="shrink-0 text-fg-muted [&_svg]:size-3.5">{item.icon ?? (item.type ? typeIcon[item.type] : <AtSign />)}</span>
      <span className="truncate">{item.label}</span>
      {onRemove ? (
        <button type="button" onClick={onRemove} aria-label={`Remove ${item.label}`} className="grid size-5 shrink-0 place-items-center rounded-xs text-fg-subtle hover:bg-surface-2 hover:text-fg"><X className="size-3" /></button>
      ) : <span className="w-1" />}
    </span>
  );
}

components/ai/message.tsx.source:
import * as React from "react";
import { cn } from "../../lib/cn";

/**
 * Message
 * One turn in a conversation.
 * - user: right-aligned soft bubble (max 80% width)
 * - assistant: full width, no bubble, reads like a document
 * `header` sits above the body (Reasoning, Tool), `footer` below (Actions, Sources).
 */
export interface MessageProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "role"> {
  from: "user" | "assistant";
  avatar?: React.ReactNode;
  /** Name + time shown above the content, e.g. in multiplayer or support chats */
  meta?: React.ReactNode;
  header?: React.ReactNode;
  footer?: React.ReactNode;
}

export function Message({ from, avatar, meta, header, footer, className, children, ...p }: MessageProps) {
  if (from === "user") {
    return (
      <div className={cn("group/msg flex flex-col items-end gap-2", className)} data-from="user" style={{ animation: "pl-in .2s ease-out" }} {...p}>
        {meta && <div className="text-xs text-fg-subtle">{meta}</div>}
        <div className="flex max-w-[80%] items-end gap-3">
          <div className="min-w-0 whitespace-pre-wrap break-words rounded-xl rounded-br-xs bg-surface-2 px-4 py-2 text-md text-fg">{children}</div>
          {avatar}
        </div>
        {footer}
      </div>
    );
  }
  return (
    <div className={cn("group/msg flex gap-4", className)} data-from="assistant" style={{ animation: "pl-in .2s ease-out" }} {...p}>
      {avatar && <div className="shrink-0">{avatar}</div>}
      <div className="flex min-w-0 flex-1 flex-col gap-3">
        {meta && <div className="text-xs text-fg-subtle">{meta}</div>}
        {header}
        <MessageBody>{children}</MessageBody>
        {footer}
      </div>
    </div>
  );
}

/** Prose styles for rendered markdown inside an assistant message. */
export function MessageBody({ className, ...p }: React.HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      className={cn(
        "min-w-0 break-words text-md text-fg",
        "[&_p+p]:mt-4 [&_p+ul]:mt-3 [&_ul+p]:mt-4 [&_h3]:mb-2 [&_h3]:mt-6 [&_h3]:text-lg [&_h3]:font-semibold",
        "[&_ul]:list-disc [&_ul]:space-y-1 [&_ul]:pl-5 [&_ol]:list-decimal [&_ol]:space-y-1 [&_ol]:pl-5",
        "[&_strong]:font-semibold [&_a]:underline [&_a]:decoration-border-strong [&_a]:underline-offset-4 hover:[&_a]:decoration-fg",
        "[&_:not(pre)>code]:rounded-xs [&_:not(pre)>code]:bg-surface-2 [&_:not(pre)>code]:px-1 [&_:not(pre)>code]:py-0.5 [&_:not(pre)>code]:font-mono [&_:not(pre)>code]:text-sm",
        className
      )}
      {...p}
    />
  );
}

/** Default assistant avatar — neutral mark, swap for your logo. */
export function AssistantAvatar({ children, className }: { children?: React.ReactNode; className?: string }) {
  return (
    <span className={cn("grid size-8 place-items-center rounded-full border border-border bg-bg text-fg shadow-xs [&_svg]:size-4", className)}>
      {children ?? (
        <svg viewBox="0 0 16 16" fill="currentColor" aria-hidden><path d="M8 1l1.6 4.4L14 7l-4.4 1.6L8 13 6.4 8.6 2 7l4.4-1.6z" /></svg>
      )}
    </span>
  );
}

components/ai/model-selector.tsx.source:
"use client";

import * as React from "react";
import { Check, ChevronDown, Lock, Search } from "lucide-react";
import { cn } from "../../lib/cn";
import { useDismiss } from "../../lib/hooks";
import { Badge } from "../ui/badge";

/**
 * ModelSelector
 * Grouped by provider, searchable when there are more than 6 models,
 * capability badges, and locked models that route to your paywall.
 * Keyboard: ↑ ↓ move · Enter select · Esc close.
 */
export interface ModelOption {
  id: string;
  name: string;
  provider?: string;
  description?: string;
  badges?: string[];
  locked?: boolean;
  icon?: React.ReactNode;
}

export interface ModelSelectorProps {
  models: ModelOption[];
  value: string;
  onValueChange: (id: string) => void;
  onLockedSelect?: (id: string) => void;
  side?: "top" | "bottom";
  align?: "start" | "end";
  defaultOpen?: boolean;
  className?: string;
}

export function ModelSelector({ models, value, onValueChange, onLockedSelect, side = "top", align = "start", defaultOpen = false, className }: ModelSelectorProps) {
  const [open, setOpen] = React.useState(defaultOpen);
  const [q, setQ] = React.useState("");
  const [active, setActive] = React.useState(0);
  const root = React.useRef<HTMLDivElement>(null);
  const listId = React.useId();
  useDismiss(open, React.useCallback(() => setOpen(false), []), root);

  const current = models.find((m) => m.id === value) ?? models[0];
  const filtered = models.filter((m) => `${m.name} ${m.provider ?? ""}`.toLowerCase().includes(q.toLowerCase()));
  const groups = filtered.reduce<[string, ModelOption[]][]>((acc, m) => {
    const g = m.provider ?? "";
    const found = acc.find(([k]) => k === g);
    found ? found[1].push(m) : acc.push([g, [m]]);
    return acc;
  }, []);
  const flat = groups.flatMap(([, ms]) => ms);

  const pick = (m?: ModelOption) => {
    if (!m) return;
    m.locked ? onLockedSelect?.(m.id) : onValueChange(m.id);
    setOpen(false); setQ("");
  };

  return (
    <div
      ref={root}
      className={cn("relative", className)}
      onKeyDown={(e) => {
        if (!open) return;
        if (e.key === "ArrowDown") { e.preventDefault(); setActive((a) => (a + 1) % flat.length); }
        if (e.key === "ArrowUp") { e.preventDefault(); setActive((a) => (a - 1 + flat.length) % flat.length); }
        if (e.key === "Enter") { e.preventDefault(); pick(flat[active]); }
      }}
    >
      <button
        type="button"
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-controls={listId}
        onClick={() => { setOpen((o) => !o); setActive(Math.max(0, flat.indexOf(current))); }}
        className="inline-flex h-8 shrink-0 items-center gap-1.5 whitespace-nowrap rounded-sm px-2 text-sm font-medium text-fg-muted transition-colors hover:bg-surface-2 hover:text-fg focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-fg/20 [&_svg]:size-4"
      >
        {current?.icon}
        {current?.name}
        <ChevronDown className={cn("!size-3.5 transition-transform", open && "rotate-180")} />
      </button>

      {open && (
        <div
          className={cn("absolute z-50 w-72 overflow-hidden rounded-lg border border-border bg-bg shadow-lg", side === "top" ? "bottom-full mb-2" : "top-full mt-2", align === "end" ? "right-0" : "left-0")}
          style={{ animation: "pl-pop .15s var(--ease-out)" }}
        >
          {models.length > 6 && (
            <label className="flex h-10 items-center gap-2 border-b border-border px-3 text-fg-subtle">
              <Search className="size-4" />
              <input autoFocus value={q} onChange={(e) => { setQ(e.target.value); setActive(0); }} placeholder="Search models…" className="w-full bg-transparent text-sm text-fg placeholder:text-fg-subtle focus:outline-none" />
            </label>
          )}
          <ul id={listId} role="listbox" aria-label="Models" className="max-h-80 overflow-y-auto p-1">
            {groups.map(([g, ms]) => (
              <li key={g} role="presentation">
                {g && <p className="px-2 pb-1 pt-2 text-xs font-medium text-fg-subtle">{g}</p>}
                <ul role="group">
                  {ms.map((m) => {
                    const i = flat.indexOf(m);
                    return (
                      <li
                        key={m.id}
                        role="option"
                        aria-selected={m.id === value}
                        aria-disabled={m.locked || undefined}
                        onMouseEnter={() => setActive(i)}
                        onClick={() => pick(m)}
                        className={cn("flex cursor-pointer items-start gap-3 rounded-sm px-2 py-2", i === active && "bg-surface-2")}
                      >
                        {m.icon && <span className="mt-0.5 text-fg-muted [&_svg]:size-4">{m.icon}</span>}
                        <div className="min-w-0 flex-1">
                          <div className="flex flex-wrap items-center gap-1.5">
                            <span className={cn("text-sm font-medium", m.locked ? "text-fg-muted" : "text-fg")}>{m.name}</span>
                            {m.badges?.map((b) => <Badge key={b} tone="outline">{b}</Badge>)}
                          </div>
                          {m.description && <p className="text-xs text-fg-subtle">{m.description}</p>}
                        </div>
                        <span className="mt-0.5 shrink-0 text-fg-muted">
                          {m.locked ? <Lock className="size-3.5" /> : m.id === value ? <Check className="size-4 text-fg" /> : null}
                        </span>
                      </li>
                    );
                  })}
                </ul>
              </li>
            ))}
            {!flat.length && <li className="px-2 py-6 text-center text-sm text-fg-subtle">No models found</li>}
          </ul>
        </div>
      )}
    </div>
  );
}

components/ai/model-status.tsx.source:
import * as React from "react";
import { AlertTriangle, CheckCircle2, XCircle } from "lucide-react";
import { cn } from "../../lib/cn";

/**
 * ModelStatus
 * Honest service health for the models your product depends on.
 * - <StatusDot/> inline next to a model name (e.g. in the ModelSelector)
 * - <ModelStatusList/> for a status popover or page: current state + 30-day uptime bars
 * When a provider is degraded, say what users will notice ("slower responses"), not just "degraded".
 */
export type Health = "operational" | "degraded" | "outage" | "maintenance";

const meta: Record<Health, { label: string; dot: string; text: string; Icon: typeof CheckCircle2 }> = {
  operational: { label: "Operational", dot: "bg-success", text: "text-success", Icon: CheckCircle2 },
  degraded: { label: "Degraded", dot: "bg-warning", text: "text-warning", Icon: AlertTriangle },
  outage: { label: "Outage", dot: "bg-danger", text: "text-danger", Icon: XCircle },
  maintenance: { label: "Maintenance", dot: "bg-info", text: "text-info", Icon: AlertTriangle },
};

export function StatusDot({ health, showLabel, className }: { health: Health; showLabel?: boolean; className?: string }) {
  const m = meta[health];
  return (
    <span className={cn("inline-flex items-center gap-1.5 text-xs", className)} title={m.label}>
      <span className="relative flex size-2">
        {health !== "operational" && <span className={cn("absolute inset-0 rounded-full opacity-60", m.dot)} style={{ animation: "pl-pulse 1.6s infinite" }} />}
        <span className={cn("relative size-2 rounded-full", m.dot)} />
      </span>
      {showLabel ? <span className={m.text}>{m.label}</span> : <span className="sr-only">{m.label}</span>}
    </span>
  );
}

export interface ServiceStatus { name: string; health: Health; note?: string; /** 30 values, oldest first */ history?: Health[]; uptime?: number }

export function ModelStatusList({ services, updatedAt, className }: { services: ServiceStatus[]; updatedAt?: string; className?: string }) {
  const worst = services.some((s) => s.health === "outage") ? "outage" : services.some((s) => s.health === "degraded") ? "degraded" : services.some((s) => s.health === "maintenance") ? "maintenance" : "operational";
  const W = meta[worst];
  return (
    <div className={cn("overflow-hidden rounded-lg border border-border bg-bg text-sm", className)}>
      <div className="flex items-center gap-2 border-b border-border px-4 py-3">
        <W.Icon className={cn("size-4", W.text)} />
        <p className="flex-1 font-medium text-fg">{worst === "operational" ? "All systems operational" : worst === "outage" ? "Some models are unavailable" : worst === "degraded" ? "Some models are slower than usual" : "Scheduled maintenance"}</p>
        {updatedAt && <span className="text-xs text-fg-subtle">{updatedAt}</span>}
      </div>
      <ul className="divide-y divide-border">
        {services.map((s) => (
          <li key={s.name} className="space-y-2 px-4 py-3">
            <div className="flex items-center gap-2">
              <span className="flex-1 font-medium text-fg">{s.name}</span>
              {s.uptime != null && <span className="text-xs tabular-nums text-fg-subtle">{s.uptime.toFixed(2)}% uptime</span>}
              <StatusDot health={s.health} showLabel />
            </div>
            {s.note && <p className="text-xs text-fg-muted">{s.note}</p>}
            {s.history && (
              <div className="flex h-6 gap-[2px]" aria-label={`${s.name}: last ${s.history.length} days`}>
                {s.history.map((h, i) => <span key={i} title={meta[h].label} className={cn("flex-1 rounded-[2px]", h === "operational" ? "bg-success/70" : meta[h].dot)} />)}
              </div>
            )}
          </li>
        ))}
      </ul>
    </div>
  );
}

components/ai/onboarding-wizard.tsx.source:
"use client";

import * as React from "react";
import { Check } from "lucide-react";
import { cn } from "../../lib/cn";
import { Button } from "../ui/button";

/**
 * OnboardingWizard
 * A short multi-step setup (3–5 steps): use case → connect data → first prompt.
 * Stepper on top, one decision per step, Back always available, optional steps can be skipped.
 * `canContinue` per step gates the Next button until the step is valid.
 */
export interface WizardStep { id: string; title: string; description?: string; content: React.ReactNode; optional?: boolean; canContinue?: boolean }

export interface OnboardingWizardProps {
  steps: WizardStep[];
  step?: number;
  onStepChange?: (i: number) => void;
  onFinish: () => void;
  finishLabel?: string;
  className?: string;
}

export function OnboardingWizard({ steps, step, onStepChange, onFinish, finishLabel = "Get started", className }: OnboardingWizardProps) {
  const [inner, setInner] = React.useState(0);
  const i = step ?? inner;
  const go = (n: number) => { setInner(n); onStepChange?.(n); };
  const s = steps[i];
  const last = i === steps.length - 1;
  const headingRef = React.useRef<HTMLHeadingElement>(null);
  const first = React.useRef(true);
  React.useEffect(() => { if (first.current) { first.current = false; return; } headingRef.current?.focus(); }, [i]);

  return (
    <div className={cn("w-full max-w-xl overflow-hidden rounded-xl border border-border bg-bg shadow-sm", className)}>
      <ol className="flex items-center gap-2 border-b border-border px-6 py-4" aria-label="Progress">
        {steps.map((st, n) => {
          const done = n < i, cur = n === i;
          return (
            <li key={st.id} className={cn("flex items-center gap-2", n < steps.length - 1 && "flex-1")} aria-current={cur ? "step" : undefined} aria-label={`Step ${n + 1}: ${st.title}${done ? " (done)" : ""}`}>
              <span className={cn("grid size-6 shrink-0 place-items-center rounded-full text-xs font-semibold tabular-nums transition-colors", done ? "bg-accent text-accent-fg" : cur ? "border-2 border-accent text-fg" : "border border-border text-fg-subtle")}>
                {done ? <Check className="size-3.5" strokeWidth={3} /> : n + 1}
              </span>
              {cur && <span className="hidden shrink-0 whitespace-nowrap text-sm font-medium text-fg sm:block">{st.title}</span>}
              {n < steps.length - 1 && <span className={cn("h-px min-w-4 flex-1", done ? "bg-accent" : "bg-border")} aria-hidden />}
            </li>
          );
        })}
      </ol>
      <div className="p-6">
        <p className="text-xs font-medium text-fg-subtle">Step {i + 1} of {steps.length}{s.optional && " · Optional"}</p>
        <h2 ref={headingRef} tabIndex={-1} className="mt-1 text-2xl font-semibold text-fg focus:outline-none">{s.title}</h2>
        {s.description && <p className="mt-1 text-base text-fg-muted">{s.description}</p>}
        <div key={s.id} className="mt-6" style={{ animation: "pl-in .2s ease-out" }}>{s.content}</div>
      </div>
      <div className="flex items-center gap-2 border-t border-border bg-surface px-6 py-4">
        {i > 0 && <Button variant="ghost" onClick={() => go(i - 1)}>Back</Button>}
        <div className="ml-auto flex gap-2">
          {s.optional && !last && <Button variant="ghost" onClick={() => go(i + 1)}>Skip</Button>}
          <Button disabled={s.canContinue === false} onClick={() => (last ? onFinish() : go(i + 1))}>{last ? finishLabel : "Continue"}</Button>
        </div>
      </div>
    </div>
  );
}

components/ai/plan.tsx.source:
"use client";

import * as React from "react";
import { Check, ChevronDown, ListTodo } from "lucide-react";
import { cn } from "../../lib/cn";
import { Button } from "../ui/button";
import { Spinner } from "../ui/spinner";
import { Shimmer } from "./loader";

/**
 * Plan
 * The agent proposes a plan before acting. Users can review, edit, then run it.
 * While executing, each step shows progress so the plan doubles as a progress view.
 */
export type PlanStepStatus = "todo" | "doing" | "done";
export interface PlanStep { title: string; detail?: string; status?: PlanStepStatus }

export interface PlanProps {
  title: string;
  summary?: string;
  steps: PlanStep[];
  isStreaming?: boolean;
  /** Primary action e.g. "Run plan" — hidden once any step is in progress */
  onRun?: () => void;
  onEdit?: () => void;
  runLabel?: string;
  defaultOpen?: boolean;
  className?: string;
}

export function Plan({ title, summary, steps, isStreaming, onRun, onEdit, runLabel = "Run plan", defaultOpen = true, className }: PlanProps) {
  const [open, setOpen] = React.useState(defaultOpen);
  const done = steps.filter((s) => s.status === "done").length;
  const started = steps.some((s) => s.status && s.status !== "todo");
  const id = React.useId();

  return (
    <div className={cn("overflow-hidden rounded-lg border border-border bg-bg text-sm", className)}>
      <button type="button" aria-expanded={open} aria-controls={id} onClick={() => setOpen((o) => !o)} className="flex w-full items-start gap-3 p-4 text-left hover:bg-surface">
        <ListTodo className="mt-0.5 size-4 shrink-0 text-fg-muted" />
        <div className="min-w-0 flex-1">
          {isStreaming ? <Shimmer className="text-base">{title}</Shimmer> : <p className="text-base font-medium text-fg">{title}</p>}
          {summary && <p className="mt-1 text-fg-muted">{summary}</p>}
        </div>
        {started && <span className="mt-0.5 text-xs tabular-nums text-fg-subtle">{done}/{steps.length}</span>}
        <ChevronDown className={cn("mt-0.5 size-4 shrink-0 text-fg-subtle transition-transform", open && "rotate-180")} />
      </button>
      <div id={id} hidden={!open}>
        {started && (
          <div className="mx-4 h-1 overflow-hidden rounded-full bg-surface-2" role="progressbar" aria-valuenow={done} aria-valuemax={steps.length} aria-valuemin={0}>
            <div className="h-full rounded-full bg-fg transition-[width] duration-500" style={{ width: `${(done / steps.length) * 100}%` }} />
          </div>
        )}
        <ol className="space-y-3 p-4">
          {steps.map((s, i) => (
            <li key={i} className="flex gap-3" style={isStreaming ? { animation: `pl-in .25s ${i * 0.05}s both` } : undefined}>
              <span className={cn("mt-0.5 grid size-5 shrink-0 place-items-center rounded-full border text-2xs font-medium tabular-nums", s.status === "done" ? "border-fg bg-fg text-bg" : s.status === "doing" ? "border-fg text-fg" : "border-border text-fg-subtle")}>
                {s.status === "done" ? <Check className="size-3" strokeWidth={3} /> : s.status === "doing" ? <Spinner className="size-3" /> : i + 1}
              </span>
              <div className="min-w-0">
                <p className={cn(s.status === "done" ? "text-fg-muted line-through decoration-fg-subtle" : "text-fg")}>{s.title}</p>
                {s.detail && <p className="mt-0.5 text-xs text-fg-subtle">{s.detail}</p>}
              </div>
            </li>
          ))}
        </ol>
        {!started && !isStreaming && (onRun || onEdit) && (
          <div className="flex justify-end gap-2 border-t border-border bg-surface px-4 py-3">
            {onEdit && <Button size="sm" variant="outline" onClick={onEdit}>Edit plan</Button>}
            {onRun && <Button size="sm" onClick={onRun}>{runLabel}</Button>}
          </div>
        )}
      </div>
    </div>
  );
}

components/ai/prompt-input.tsx.source:
"use client";

import * as React from "react";
import { ArrowUp, Paperclip, Square, AlertCircle } from "lucide-react";
import { cn } from "../../lib/cn";
import { Button } from "../ui/button";
import { Spinner } from "../ui/spinner";
import { Tooltip } from "../ui/tooltip";

/**
 * PromptInput
 * The most important component in any AI product.
 * - Auto-grows up to `maxRows`, then scrolls
 * - Enter sends · Shift+Enter new line · IME-safe
 * - Submit button reflects status: ready → submitted (spinner) → streaming (stop) → error (retry)
 * - Drag & drop files onto the box (onFiles)
 * - Slots: attachments (above text), tools (bottom-left), footer hint
 */
export type PromptStatus = "ready" | "submitted" | "streaming" | "error";

export interface PromptInputProps {
  value: string;
  onValueChange: (v: string) => void;
  onSubmit: (value: string) => void;
  onStop?: () => void;
  onFiles?: (files: File[]) => void;
  status?: PromptStatus;
  placeholder?: string;
  disabled?: boolean;
  attachments?: React.ReactNode;
  tools?: React.ReactNode;
  hint?: React.ReactNode;
  maxRows?: number;
  /** Show a counter when approaching this many characters */
  maxLength?: number;
  autoFocus?: boolean;
  /** Runs before the built-in keys. Call e.preventDefault() to stop Enter from sending (used by SlashCommands / MentionPicker). */
  onKeyDown?: (e: React.KeyboardEvent<HTMLTextAreaElement>) => void;
  className?: string;
}

export function PromptInput({
  value, onValueChange, onSubmit, onStop, onFiles, status = "ready", placeholder = "Ask anything…",
  disabled, attachments, tools, hint, maxRows = 10, maxLength, autoFocus, onKeyDown, className,
}: PromptInputProps) {
  const ta = React.useRef<HTMLTextAreaElement>(null);
  const file = React.useRef<HTMLInputElement>(null);
  const [drag, setDrag] = React.useState(false);
  const busy = status === "submitted" || status === "streaming";
  const tooLong = maxLength != null && value.length > maxLength;
  const canSend = value.trim().length > 0 && !disabled && !busy && !tooLong;

  React.useLayoutEffect(() => {
    const el = ta.current;
    if (!el) return;
    el.style.height = "auto";
    el.style.height = Math.min(el.scrollHeight, 24 * maxRows) + "px";
  }, [value, maxRows]);

  const submit = () => { if (canSend) onSubmit(value); };

  return (
    <div className={cn("w-full", className)}>
      <form
        onSubmit={(e) => { e.preventDefault(); submit(); }}
        onDragOver={onFiles ? (e) => { e.preventDefault(); setDrag(true); } : undefined}
        onDragLeave={() => setDrag(false)}
        onDrop={onFiles ? (e) => { e.preventDefault(); setDrag(false); onFiles(Array.from(e.dataTransfer.files)); } : undefined}
        onClick={(e) => { if (e.target === e.currentTarget) ta.current?.focus(); }}
        className={cn(
          "relative flex cursor-text flex-col rounded-xl border bg-bg shadow-sm transition-[border-color,box-shadow] duration-150",
          "focus-within:border-border-strong focus-within:shadow-md",
          status === "error" ? "border-danger/40" : "border-border",
          drag && "border-dashed border-fg-subtle bg-surface",
          disabled && "pointer-events-none opacity-50"
        )}
      >
        {drag && <div className="pointer-events-none absolute inset-0 z-10 grid place-items-center rounded-xl text-sm font-medium text-fg-muted">Drop files to attach</div>}
        {attachments && <div className="flex flex-wrap gap-2 px-3 pt-3">{attachments}</div>}
        <textarea
          ref={ta}
          rows={1}
          value={value}
          autoFocus={autoFocus}
          disabled={disabled}
          placeholder={placeholder}
          aria-label="Message"
          aria-invalid={tooLong || undefined}
          onChange={(e) => onValueChange(e.target.value)}
          onPaste={onFiles ? (e) => { const f = Array.from(e.clipboardData.files); if (f.length) { e.preventDefault(); onFiles(f); } } : undefined}
          onKeyDown={(e) => {
            onKeyDown?.(e);
            if (e.defaultPrevented) return;
            if (e.key === "Enter" && !e.shiftKey && !e.nativeEvent.isComposing) { e.preventDefault(); submit(); }
          }}
          className="block w-full resize-none bg-transparent px-4 pb-2 pt-4 text-md text-fg placeholder:text-fg-subtle focus:outline-none"
        />
        <div className="flex items-center gap-1 p-2">
          {onFiles && (
            <>
              <input ref={file} type="file" multiple hidden onChange={(e) => { onFiles(Array.from(e.target.files ?? [])); e.target.value = ""; }} />
              <Tooltip label="Attach files">
                <Button variant="ghost" size="icon-sm" onClick={() => file.current?.click()} aria-label="Attach files"><Paperclip /></Button>
              </Tooltip>
            </>
          )}
          {tools}
          <div className="ml-auto flex items-center gap-3">
            {maxLength != null && value.length > maxLength * 0.8 && (
              <span className={cn("text-xs tabular-nums", tooLong ? "text-danger" : "text-fg-subtle")}>{value.length}/{maxLength}</span>
            )}
            <PromptSubmit status={status} canSend={canSend} onStop={onStop} />
          </div>
        </div>
      </form>
      {hint && <p className="mt-2 text-center text-xs text-fg-subtle">{hint}</p>}
    </div>
  );
}

function PromptSubmit({ status, canSend, onStop }: { status: PromptStatus; canSend: boolean; onStop?: () => void }) {
  if (status === "streaming")
    return (
      <Tooltip label="Stop">
        <Button size="icon-sm" onClick={onStop} aria-label="Stop generating" className="rounded-full"><Square className="!size-3 fill-current" /></Button>
      </Tooltip>
    );
  if (status === "submitted")
    return <Button size="icon-sm" disabled aria-label="Sending" className="rounded-full !opacity-100"><Spinner className="size-3.5" /></Button>;
  if (status === "error")
    return (
      <Tooltip label="Retry">
        <Button type="submit" size="icon-sm" variant="danger" aria-label="Retry" className="rounded-full"><AlertCircle /></Button>
      </Tooltip>
    );
  return <Button type="submit" size="icon-sm" disabled={!canSend} aria-label="Send message" className="rounded-full"><ArrowUp /></Button>;
}

/** Small ghost button for the tools slot, e.g. "Search", "Deep research". Toggleable. */
export function PromptTool({ active, icon, children, onClick, className }: { active?: boolean; icon?: React.ReactNode; children?: React.ReactNode; onClick?: () => void; className?: string }) {
  return (
    <button
      type="button"
      aria-pressed={active}
      onClick={onClick}
      className={cn(
        "inline-flex h-8 items-center gap-1.5 rounded-full border px-3 text-sm font-medium transition-colors [&_svg]:size-4",
        active ? "border-info/30 bg-info/10 text-info" : "border-border text-fg-muted hover:bg-surface-2 hover:text-fg",
        !children && "w-8 justify-center px-0",
        className
      )}
    >
      {icon}{children}
    </button>
  );
}

components/ai/prompt-template.tsx.source:
"use client";

import * as React from "react";
import { ArrowUp, Braces } from "lucide-react";
import { cn } from "../../lib/cn";
import { Button } from "../ui/button";

/**
 * PromptTemplate
 * Reusable prompts with {{variables}}. Variables become labelled fields automatically;
 * the preview highlights filled and missing values; "Use prompt" is enabled once all are filled.
 * Syntax: {{name}} or {{name:placeholder text}}.
 */
export interface PromptTemplateProps {
  title: string;
  description?: string;
  template: string;
  onUse: (prompt: string, values: Record<string, string>) => void;
  useLabel?: string;
  className?: string;
}

const VAR = /\{\{\s*([a-zA-Z0-9_ ]+?)\s*(?::\s*([^}]*))?\}\}/g;

export function parseTemplate(t: string) {
  const vars: { name: string; hint?: string }[] = [];
  for (const m of t.matchAll(VAR)) if (!vars.some((v) => v.name === m[1])) vars.push({ name: m[1], hint: m[2] });
  return vars;
}
export function fillTemplate(t: string, values: Record<string, string>) {
  return t.replace(VAR, (_, n) => values[n] ?? "");
}
const pretty = (n: string) => n.replace(/_/g, " ").replace(/^\w/, (c) => c.toUpperCase());

export function PromptTemplate({ title, description, template, onUse, useLabel = "Use prompt", className }: PromptTemplateProps) {
  const vars = React.useMemo(() => parseTemplate(template), [template]);
  const [values, setValues] = React.useState<Record<string, string>>({});
  const ready = vars.every((v) => values[v.name]?.trim());
  const parts = React.useMemo(() => {
    const out: React.ReactNode[] = [];
    let last = 0, k = 0;
    for (const m of template.matchAll(VAR)) {
      out.push(template.slice(last, m.index));
      const val = values[m[1]]?.trim();
      out.push(val ? <mark key={k++} className="rounded-xs bg-info/10 px-0.5 text-fg">{val}</mark> : <mark key={k++} className="rounded-xs border border-dashed border-border-strong bg-transparent px-1 text-fg-subtle">{pretty(m[1])}</mark>);
      last = m.index! + m[0].length;
    }
    out.push(template.slice(last));
    return out;
  }, [template, values]);

  return (
    <div className={cn("overflow-hidden rounded-lg border border-border bg-bg", className)}>
      <div className="flex items-start gap-3 p-4">
        <span className="grid size-8 shrink-0 place-items-center rounded-md bg-surface-2 text-fg-muted"><Braces className="size-4" /></span>
        <div className="min-w-0">
          <p className="text-base font-medium text-fg">{title}</p>
          {description && <p className="text-sm text-fg-muted">{description}</p>}
        </div>
      </div>
      <div className="grid gap-3 border-t border-border p-4 sm:grid-cols-2">
        {vars.map((v, i) => (
          <label key={v.name} className="space-y-1.5 text-sm">
            <span className="font-medium text-fg">{pretty(v.name)}</span>
            <input
              autoFocus={i === 0}
              value={values[v.name] ?? ""}
              onChange={(e) => setValues((s) => ({ ...s, [v.name]: e.target.value }))}
              placeholder={v.hint ?? ""}
              className="h-9 w-full rounded-md border border-border bg-bg px-3 text-base text-fg shadow-xs placeholder:text-fg-subtle focus:border-border-strong focus:outline-none focus:ring-4 focus:ring-fg/5"
            />
          </label>
        ))}
      </div>
      <div className="border-t border-border bg-surface p-4">
        <p className="mb-2 text-xs font-medium text-fg-subtle">Preview</p>
        <p className="whitespace-pre-wrap text-sm leading-6 text-fg-muted">{parts}</p>
        <div className="mt-4 flex items-center justify-between gap-3">
          <span className="text-xs text-fg-subtle">{vars.filter((v) => values[v.name]?.trim()).length} of {vars.length} filled</span>
          <Button size="sm" disabled={!ready} onClick={() => onUse(fillTemplate(template, values), values)}>{useLabel}<ArrowUp /></Button>
        </div>
      </div>
    </div>
  );
}

