"use client";

import * as React from "react";
import { ArrowUp, Check, ChevronDown, GripVertical, MessageSquare, X } from "lucide-react";
import { cn } from "../../lib/cn";

/**
 * Queue
 * Messages the user typed while the agent was busy, plus the agent's to-do list.
 * Users can send a queued message now, remove it, or let it run next.
 */
export interface QueuedMessage { id: string; text: string }
export interface Todo { id: string; text: string; done?: boolean }

export function Queue({ messages = [], todos = [], onRemove, onSendNow, onToggleTodo, className }: {
  messages?: QueuedMessage[];
  todos?: Todo[];
  onRemove?: (id: string) => void;
  onSendNow?: (id: string) => void;
  onToggleTodo?: (id: string) => void;
  className?: string;
}) {
  return (
    <div className={cn("overflow-hidden rounded-lg border border-border bg-bg text-sm", className)}>
      {messages.length > 0 && (
        <QueueSection title="Queued" count={messages.length}>
          {messages.map((m) => (
            <li key={m.id} className="group flex items-center gap-2 rounded-sm px-2 py-1.5 hover:bg-surface">
              <GripVertical className="size-3.5 shrink-0 text-fg-subtle" aria-hidden />
              <MessageSquare className="size-3.5 shrink-0 text-fg-muted" aria-hidden />
              <span className="min-w-0 flex-1 truncate text-fg">{m.text}</span>
              <span className="flex gap-0.5 opacity-0 transition-opacity focus-within:opacity-100 group-hover:opacity-100 [@media(hover:none)]:opacity-100">
                {onSendNow && <button type="button" onClick={() => onSendNow(m.id)} aria-label="Send now" className="grid size-6 place-items-center rounded-xs text-fg-muted hover:bg-surface-2 hover:text-fg"><ArrowUp className="size-3.5" /></button>}
                {onRemove && <button type="button" onClick={() => onRemove(m.id)} aria-label="Remove from queue" className="grid size-6 place-items-center rounded-xs text-fg-muted hover:bg-surface-2 hover:text-fg"><X className="size-3.5" /></button>}
              </span>
            </li>
          ))}
        </QueueSection>
      )}
      {todos.length > 0 && (
        <QueueSection title="To-dos" count={`${todos.filter((t) => t.done).length}/${todos.length}`} border={messages.length > 0}>
          {todos.map((t) => (
            <li key={t.id}>
              <label className="flex cursor-pointer items-center gap-2 rounded-sm px-2 py-1.5 hover:bg-surface">
                <input type="checkbox" checked={!!t.done} onChange={() => onToggleTodo?.(t.id)} className="peer sr-only" />
                <span className={cn("grid size-4 shrink-0 place-items-center rounded-full border transition-colors peer-focus-visible:ring-2 peer-focus-visible:ring-fg/20", t.done ? "border-fg bg-fg text-bg" : "border-border-strong")}>
                  {t.done && <Check className="size-2.5" strokeWidth={3} />}
                </span>
                <span className={cn("flex-1", t.done ? "text-fg-subtle line-through" : "text-fg")}>{t.text}</span>
              </label>
            </li>
          ))}
        </QueueSection>
      )}
    </div>
  );
}

function QueueSection({ title, count, border, children }: { title: string; count: React.ReactNode; border?: boolean; children: React.ReactNode }) {
  const [open, setOpen] = React.useState(true);
  return (
    <section className={cn(border && "border-t border-border")}>
      <button type="button" aria-expanded={open} onClick={() => setOpen((o) => !o)} className="flex h-10 w-full items-center gap-2 px-3 text-left text-xs font-medium text-fg-muted hover:text-fg">
        <ChevronDown className={cn("size-3.5 transition-transform", !open && "-rotate-90")} />
        {title}
        <span className="tabular-nums text-fg-subtle">{count}</span>
      </button>
      {open && <ul className="px-1 pb-2">{children}</ul>}
    </section>
  );
}

components/ai/reasoning.tsx.source:
"use client";

import * as React from "react";
import { Brain, ChevronDown } from "lucide-react";
import { cn } from "../../lib/cn";
import { Shimmer } from "./loader";

/**
 * Reasoning
 * Model "thinking" output.
 * - While streaming: opens automatically, label shimmers "Thinking…"
 * - When done: auto-collapses to "Thought for 8s" so the answer takes focus
 * - The user can reopen it at any time
 */
export interface ReasoningProps {
  children: React.ReactNode;
  isStreaming?: boolean;
  /** Seconds — shown once finished */
  duration?: number;
  defaultOpen?: boolean;
  /** Collapse automatically when streaming ends (default true) */
  autoCollapse?: boolean;
  className?: string;
}

export function Reasoning({ children, isStreaming, duration, defaultOpen, autoCollapse = true, className }: ReasoningProps) {
  const [open, setOpen] = React.useState(defaultOpen ?? !!isStreaming);
  const was = React.useRef(isStreaming);
  const id = React.useId();

  React.useEffect(() => {
    if (isStreaming) setOpen(true);
    else if (was.current && autoCollapse) { const t = setTimeout(() => setOpen(false), 600); return () => clearTimeout(t); }
    was.current = isStreaming;
  }, [isStreaming, autoCollapse]);

  const label = isStreaming ? "Thinking…" : duration != null ? `Thought for ${duration < 60 ? `${duration}s` : `${Math.round(duration / 60)}m`}` : "Reasoning";

  return (
    <div className={cn("text-sm", className)}>
      <button
        type="button"
        aria-expanded={open}
        aria-controls={id}
        onClick={() => setOpen((o) => !o)}
        className="inline-flex h-7 items-center gap-2 rounded-sm text-fg-muted transition-colors hover:text-fg focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-fg/20"
      >
        <Brain className="size-4" />
        {isStreaming ? <Shimmer>{label}</Shimmer> : <span className="font-medium">{label}</span>}
        <ChevronDown className={cn("size-3.5 transition-transform duration-200", open && "rotate-180")} />
      </button>
      <div id={id} hidden={!open} className="mt-2 border-l border-border pl-4 text-sm text-fg-muted [&_p+p]:mt-2" style={{ animation: "pl-in .2s ease-out" }}>
        {children}
      </div>
    </div>
  );
}

components/ai/relative-time.tsx.source:
"use client";

import * as React from "react";

/**
 * RelativeTime
 * "just now", "5m ago", "Yesterday", "Mar 4" — updates itself, shows the full date on hover,
 * and renders a semantic <time> element. `dayGroup()` returns the history-list label for a date.
 */
const rtf = typeof Intl !== "undefined" ? new Intl.RelativeTimeFormat(undefined, { numeric: "auto", style: "short" }) : null;

export function formatRelative(date: Date, now = new Date()): string {
  const s = Math.round((now.getTime() - date.getTime()) / 1000);
  if (s < 45) return "just now";
  const m = Math.round(s / 60);
  if (m < 60) return rtf ? rtf.format(-m, "minute") : `${m}m ago`;
  const h = Math.round(m / 60);
  if (h < 24) return rtf ? rtf.format(-h, "hour") : `${h}h ago`;
  const d = Math.round(h / 24);
  if (d < 7) return rtf ? rtf.format(-d, "day") : `${d}d ago`;
  return date.toLocaleDateString(undefined, { month: "short", day: "numeric", ...(date.getFullYear() !== now.getFullYear() && { year: "numeric" }) });
}

export function dayGroup(date: Date, now = new Date()): string {
  const day = (x: Date) => new Date(x.getFullYear(), x.getMonth(), x.getDate()).getTime();
  const diff = Math.round((day(now) - day(date)) / 86400000);
  if (diff <= 0) return "Today";
  if (diff === 1) return "Yesterday";
  if (diff < 7) return "Previous 7 days";
  if (diff < 30) return "Previous 30 days";
  return date.toLocaleDateString(undefined, { month: "long", year: "numeric" });
}

export function RelativeTime({ date, className }: { date: Date | string | number; className?: string }) {
  const d = React.useMemo(() => new Date(date), [date]);
  const [, tick] = React.useState(0);
  React.useEffect(() => {
    const age = Date.now() - d.getTime();
    const every = age < 3600_000 ? 30_000 : 600_000;
    const t = setInterval(() => tick((x) => x + 1), every);
    return () => clearInterval(t);
  }, [d]);
  return (
    <time dateTime={d.toISOString()} title={d.toLocaleString()} className={className}>
      {formatRelative(d)}
    </time>
  );
}

components/ai/research-progress.tsx.source:
"use client";

import * as React from "react";
import { Check, ChevronDown, Globe, Square, Telescope } from "lucide-react";
import { cn } from "../../lib/cn";
import { Button } from "../ui/button";
import { Spinner } from "../ui/spinner";

/**
 * ResearchProgress
 * The "deep research" view: long-running work made legible. Shows the plan's phases,
 * the sources being read right now, a live count and elapsed time, and a Stop button.
 * Collapses to a one-line summary when finished.
 */
export type PhaseStatus = "pending" | "active" | "done";
export interface ResearchPhase { id: string; label: string; status: PhaseStatus; detail?: string }
export interface ResearchSource { url: string; title?: string; status?: "reading" | "read" }

export interface ResearchProgressProps {
  query: string;
  phases: ResearchPhase[];
  sources: ResearchSource[];
  state: "running" | "done" | "stopped";
  /** Seconds elapsed — you own the clock */
  elapsed: number;
  onStop?: () => void;
  onOpenReport?: () => void;
  /** Sources shown before "+ N more" */
  visibleSources?: number;
  className?: string;
}

const domain = (u: string) => { try { return new URL(u).hostname.replace(/^www\./, ""); } catch { return u; } };
export const formatDuration = (s: number) => (s < 60 ? `${Math.floor(s)}s` : `${Math.floor(s / 60)}m ${String(Math.floor(s % 60)).padStart(2, "0")}s`);

export function ResearchProgress({ query, phases, sources, state, elapsed, onStop, onOpenReport, visibleSources = 5, className }: ResearchProgressProps) {
  const [open, setOpen] = React.useState(true);
  const [allSources, setAllSources] = React.useState(false);
  const running = state === "running";
  const read = sources.filter((s) => s.status !== "reading").length;
  React.useEffect(() => { if (!running) setOpen(false); }, [running]);
  const shown = allSources ? sources : sources.slice(-visibleSources).reverse();

  return (
    <section aria-label="Research progress" className={cn("w-full overflow-hidden rounded-xl border border-border bg-bg", className)}>
      <div className="flex items-center gap-3 p-4">
        <span className={cn("grid size-9 shrink-0 place-items-center rounded-lg border border-border", running ? "bg-surface text-fg" : "bg-success/10 text-success border-success/20")}>
          {running ? <Telescope className="size-4" /> : <Check className="size-4" />}
        </span>
        <div className="min-w-0 flex-1">
          <p className={cn("text-sm font-medium text-fg", running && "pl-shimmer-text")}>{running ? "Researching" : state === "stopped" ? "Research stopped" : "Research complete"}</p>
          <p className="truncate text-xs text-fg-muted" aria-live="polite">
            <span className="tabular-nums">{read}</span> sources · <span className="tabular-nums">{formatDuration(elapsed)}</span>
          </p>
        </div>
        {running && onStop && <Button size="sm" variant="outline" onClick={onStop}><Square className="!size-3 fill-current" />Stop</Button>}
        {!running && onOpenReport && <Button size="sm" onClick={onOpenReport}>Open report</Button>}
        <button type="button" onClick={() => setOpen((o) => !o)} aria-expanded={open} aria-label={open ? "Hide details" : "Show details"} className="grid size-8 shrink-0 place-items-center rounded-sm text-fg-subtle hover:bg-surface-2 hover:text-fg">
          <ChevronDown className={cn("size-4 transition-transform", open && "rotate-180")} />
        </button>
      </div>

      {open && (
        <div className="grid border-t border-border sm:grid-cols-[minmax(0,1fr)_minmax(0,1.1fr)]">
          <div className="p-4">
            <p className="mb-3 line-clamp-2 text-xs text-fg-subtle">“{query}”</p>
            <ol className="space-y-0">
              {phases.map((p, i) => (
                <li key={p.id} className="relative flex gap-3 pb-4 last:pb-0">
                  {i < phases.length - 1 && <span aria-hidden className={cn("absolute left-[9px] top-6 h-[calc(100%-20px)] w-px", p.status === "done" ? "bg-fg/30" : "bg-border")} />}
                  <span className={cn("relative z-[1] mt-0.5 grid size-[19px] shrink-0 place-items-center rounded-full border",
                    p.status === "done" ? "border-fg bg-fg text-bg" : p.status === "active" ? "border-fg bg-bg" : "border-border bg-bg")}>
                    {p.status === "done" ? <Check className="size-3" strokeWidth={3} /> : p.status === "active" ? <Spinner className="size-3" /> : null}
                  </span>
                  <div className="min-w-0">
                    <p className={cn("text-sm", p.status === "pending" ? "text-fg-subtle" : "text-fg", p.status === "active" && "font-medium")}>{p.label}</p>
                    {p.detail && p.status !== "pending" && <p className="mt-0.5 text-xs text-fg-muted">{p.detail}</p>}
                  </div>
                </li>
              ))}
            </ol>
          </div>
          <div className="border-t border-border bg-surface/60 p-4 sm:border-l sm:border-t-0">
            <p className="mb-2 text-xs font-medium text-fg-subtle">Sources</p>
            {sources.length === 0 ? <p className="py-3 text-sm text-fg-subtle">Searching…</p> : (
              <ul className={cn("space-y-1", allSources && "max-h-64 overflow-y-auto")}>
                {shown.map((s) => (
                  <li key={s.url} style={{ animation: "pl-in .25s ease-out" }}>
                    <a href={s.url} target="_blank" rel="noreferrer" className="flex items-center gap-2 rounded-md px-1.5 py-1 hover:bg-surface-2">
                      <span className="grid size-5 shrink-0 place-items-center rounded-xs border border-border bg-bg text-2xs font-semibold uppercase text-fg-muted">{domain(s.url)[0]}</span>
                      <span className={cn("min-w-0 flex-1 truncate text-sm", s.status === "reading" ? "pl-shimmer-text" : "text-fg")}>{s.title ?? domain(s.url)}</span>
                      {s.title && <span className="hidden shrink-0 text-xs text-fg-subtle sm:inline">{domain(s.url)}</span>}
                    </a>
                  </li>
                ))}
              </ul>
            )}
            {sources.length > visibleSources && (
              <button type="button" onClick={() => setAllSources((a) => !a)} className="mt-2 inline-flex items-center gap-1.5 px-1.5 text-xs font-medium text-fg-muted hover:text-fg">
                <Globe className="size-3.5" />{allSources ? "Show recent" : `+ ${sources.length - visibleSources} more`}
              </button>
            )}
          </div>
        </div>
      )}
    </section>
  );
}

components/ai/response-compare.tsx.source:
"use client";

import * as React from "react";
import { Check, Equal } from "lucide-react";
import { cn } from "../../lib/cn";
import { Badge } from "../ui/badge";

/**
 * ResponseCompare
 * Two answers side by side (stacked on small screens) and one question: which is better?
 * Used for A/B tests, model evaluation, and "we're testing a new version" moments.
 * Model names stay hidden until the user votes (`revealOnVote`) to avoid brand bias.
 */
export type Preference = "a" | "b" | "tie" | null;

export interface ResponseCompareProps {
  a: { content: React.ReactNode; model?: string };
  b: { content: React.ReactNode; model?: string };
  value?: Preference;
  onValueChange?: (v: Exclude<Preference, null>) => void;
  revealOnVote?: boolean;
  question?: string;
  className?: string;
}

export function ResponseCompare({ a, b, value = null, onValueChange, revealOnVote = true, question = "Which response is better?", className }: ResponseCompareProps) {
  const voted = value !== null;
  const panel = (key: "a" | "b", r: { content: React.ReactNode; model?: string }) => {
    const win = value === key, lose = voted && value !== key && value !== "tie";
    return (
      <div className={cn("flex min-w-0 flex-col rounded-lg border bg-bg transition-[border-color,opacity]", win ? "border-fg shadow-sm" : "border-border", lose && "opacity-60")}>
        <div className="flex h-10 items-center gap-2 border-b border-border px-4 text-xs font-medium text-fg-muted">
          Response {key.toUpperCase()}
          {voted && revealOnVote && r.model && <span className="text-fg">· {r.model}</span>}
          {win && <Badge tone="success" className="ml-auto"><Check />Preferred</Badge>}
        </div>
        <div className="flex-1 p-4 text-md text-fg">{r.content}</div>
        {!voted && (
          <button type="button" onClick={() => onValueChange?.(key)} className="m-3 mt-0 h-9 rounded-md border border-border text-sm font-medium text-fg transition-colors hover:border-fg hover:bg-surface focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-fg/20">
            {key.toUpperCase()} is better
          </button>
        )}
      </div>
    );
  };
  return (
    <div className={cn("space-y-3", className)} role="group" aria-label={question}>
      <div className="flex items-center justify-between gap-3">
        <p className="text-sm font-medium text-fg">{voted ? "Thanks — your choice helps improve answers." : question}</p>
        {!voted && <button type="button" onClick={() => onValueChange?.("tie")} className="inline-flex h-8 items-center gap-1.5 rounded-sm px-2 text-sm text-fg-muted hover:bg-surface-2 hover:text-fg"><Equal className="size-4" />About the same</button>}
      </div>
      <div className="grid gap-3 md:grid-cols-2">{panel("a", a)}{panel("b", b)}</div>
    </div>
  );
}

components/ai/share-dialog.tsx.source:
"use client";

import * as React from "react";
import { Check, Copy, Globe, Link2, Lock, Info } from "lucide-react";
import { cn } from "../../lib/cn";
import { useCopy } from "../../lib/hooks";
import { Dialog, DialogHeader, DialogTitle, DialogDescription, DialogBody, DialogFooter } from "../ui/dialog";
import { Button } from "../ui/button";

/**
 * ShareDialog
 * Share a conversation or result with clear access levels and an honest note about
 * what the recipient will — and won't — see. The link only appears once sharing is on.
 */
export type ShareAccess = "private" | "link" | "public";

export interface ShareDialogProps {
  open: boolean;
  onClose: () => void;
  access: ShareAccess;
  onAccessChange: (a: ShareAccess) => void;
  url: string;
  title?: string;
  /** What's included / excluded, e.g. "Messages you send after sharing stay private." */
  note?: React.ReactNode;
  /** Hide the "Public" option (e.g. for team workspaces) */
  allowPublic?: boolean;
  onCopy?: () => void;
}

const options: { id: ShareAccess; icon: React.ReactNode; label: string; hint: string }[] = [
  { id: "private", icon: <Lock />, label: "Private", hint: "Only you can see this" },
  { id: "link", icon: <Link2 />, label: "Anyone with the link", hint: "Can view, can't edit or continue" },
  { id: "public", icon: <Globe />, label: "Public", hint: "Listed and discoverable by search engines" },
];

export function ShareDialog({ open, onClose, access, onAccessChange, url, title = "Share chat", note, allowPublic = true, onCopy }: ShareDialogProps) {
  const { copied, copy } = useCopy();
  const id = React.useId();
  const list = allowPublic ? options : options.filter((o) => o.id !== "public");
  const shared = access !== "private";
  const move = (dir: 1 | -1) => { const i = list.findIndex((o) => o.id === access); onAccessChange(list[(i + dir + list.length) % list.length].id); };

  return (
    <Dialog open={open} onClose={onClose} labelledBy={id} className="max-w-md">
      <DialogHeader>
        <DialogTitle id={id}>{title}</DialogTitle>
        <DialogDescription>Choose who can view this conversation.</DialogDescription>
      </DialogHeader>
      <DialogBody className="space-y-4">
        <div role="radiogroup" aria-label="Access" className="overflow-hidden rounded-lg border border-border"
          onKeyDown={(e) => { if (e.key === "ArrowDown" || e.key === "ArrowRight") { e.preventDefault(); move(1); } if (e.key === "ArrowUp" || e.key === "ArrowLeft") { e.preventDefault(); move(-1); } }}>
          {list.map((o) => {
            const on = access === o.id;
            return (
              <button key={o.id} type="button" role="radio" aria-checked={on} tabIndex={on ? 0 : -1} onClick={() => onAccessChange(o.id)}
                className={cn("flex w-full items-center gap-3 border-b border-border px-3 py-3 text-left transition-colors last:border-b-0", on ? "bg-surface" : "hover:bg-surface/60")}>
                <span className={cn("grid size-8 shrink-0 place-items-center rounded-md border [&_svg]:size-4", on ? "border-fg bg-fg text-bg" : "border-border text-fg-muted")}>{o.icon}</span>
                <span className="min-w-0 flex-1">
                  <span className="block text-sm font-medium text-fg">{o.label}</span>
                  <span className="block text-xs text-fg-muted">{o.hint}</span>
                </span>
                <span className={cn("grid size-4 shrink-0 place-items-center rounded-full border", on ? "border-fg" : "border-border-strong")}>{on && <span className="size-2 rounded-full bg-fg" />}</span>
              </button>
            );
          })}
        </div>

        <div className={cn("transition-opacity", shared ? "opacity-100" : "pointer-events-none opacity-40")} aria-hidden={!shared}>
          <label htmlFor={id + "-url"} className="mb-1.5 block text-sm font-medium text-fg">Link</label>
          <div className="flex gap-2">
            <input id={id + "-url"} readOnly value={shared ? url : "Turn on sharing to get a link"} onFocus={(e) => e.currentTarget.select()} tabIndex={shared ? 0 : -1}
              className="h-9 min-w-0 flex-1 rounded-md border border-border bg-surface px-3 font-mono text-sm text-fg-muted focus:outline-none focus:ring-2 focus:ring-fg/20" />
            <Button variant="outline" disabled={!shared} onClick={() => { copy(url); onCopy?.(); }} className="shrink-0">
              {copied ? <Check /> : <Copy />}{copied ? "Copied" : "Copy"}
            </Button>
          </div>
        </div>

        <p className="flex gap-2 rounded-md bg-surface px-3 py-2.5 text-xs text-fg-muted">
          <Info className="mt-px size-3.5 shrink-0" />
          <span>{note ?? "Your name and any messages you send after sharing stay private. Uploaded files aren't included."}</span>
        </p>
      </DialogBody>
      <DialogFooter>
        <Button onClick={onClose}>Done</Button>
      </DialogFooter>
    </Dialog>
  );
}

components/ai/skeleton.tsx.source:
import * as React from "react";
import { cn } from "../../lib/cn";

/**
 * Skeleton
 * Shimmer placeholders that match the real layout's shape, so nothing jumps when data arrives.
 * Use for loading a saved conversation, history list, or any card — not for waiting on the model
 * (use Loader for that).
 */
export function Skeleton({ className, ...p }: React.HTMLAttributes<HTMLDivElement>) {
  return (
    <div aria-hidden className={cn("relative overflow-hidden rounded-sm bg-surface-2", className)} {...p}>
      <div className="absolute inset-0 -translate-x-full bg-gradient-to-r from-transparent via-fg/[0.05] to-transparent" style={{ animation: "pl-shimmer-x 1.6s infinite" }} />
    </div>
  );
}

export function MessageSkeleton({ from = "assistant", lines = 3, className }: { from?: "user" | "assistant"; lines?: number; className?: string }) {
  if (from === "user") return <div className={cn("flex justify-end", className)}><Skeleton className="h-10 w-2/5 rounded-xl" /></div>;
  const w = ["w-full", "w-11/12", "w-4/5", "w-3/4"];
  return (
    <div className={cn("flex gap-4", className)}>
      <Skeleton className="size-8 shrink-0 rounded-full" />
      <div className="flex-1 space-y-3 pt-1.5">
        {Array.from({ length: lines }).map((_, i) => <Skeleton key={i} className={cn("h-3", i === lines - 1 ? "w-2/5" : w[i % w.length])} />)}
      </div>
    </div>
  );
}

export function ConversationSkeleton({ className }: { className?: string }) {
  return (
    <div role="status" aria-label="Loading conversation" className={cn("flex flex-col gap-8", className)}>
      <MessageSkeleton from="user" />
      <MessageSkeleton lines={4} />
      <MessageSkeleton from="user" />
      <MessageSkeleton lines={2} />
    </div>
  );
}

components/ai/slash-commands.tsx.source:
"use client";

import * as React from "react";
import { cn } from "../../lib/cn";

/**
 * SlashCommands
 * Type "/" at the start of the prompt to open a filterable command list above the input.
 * Wraps any text input through a render prop: pass the provided `onKeyDown` to it.
 * - ↑ ↓ to move, Enter / Tab to run, Esc to dismiss
 * - Ranked matching: label starts-with first, then contains, then description
 * - Grouped, with icons, descriptions and optional shortcut hints
 */
export interface SlashCommand {
  id: string;
  label: string;
  description?: string;
  icon?: React.ReactNode;
  group?: string;
  /** Extra words that should match, e.g. ["img", "picture"] */
  keywords?: string[];
}

export interface SlashCommandsProps {
  value: string;
  onValueChange: (v: string) => void;
  commands: SlashCommand[];
  /** Called with the chosen command. The "/query" text is cleared first. */
  onRun: (command: SlashCommand) => void;
  children: (input: { onKeyDown: (e: React.KeyboardEvent) => void; open: boolean }) => React.ReactNode;
  emptyText?: string;
  className?: string;
}

export function rankCommands(commands: SlashCommand[], query: string) {
  const q = query.toLowerCase();
  if (!q) return commands;
  const score = (c: SlashCommand) => {
    const l = c.label.toLowerCase();
    if (l.startsWith(q) || c.id.startsWith(q)) return 0;
    if (l.includes(q) || c.keywords?.some((k) => k.startsWith(q))) return 1;
    if (c.description?.toLowerCase().includes(q)) return 2;
    return -1;
  };
  return commands.map((c) => [c, score(c)] as const).filter(([, s]) => s >= 0).sort((a, b) => a[1] - b[1]).map(([c]) => c);
}

export function SlashCommands({ value, onValueChange, commands, onRun, children, emptyText = "No commands found", className }: SlashCommandsProps) {
  const match = /^\/(\S*)$/.exec(value);
  const [dismissed, setDismissed] = React.useState<string | null>(null);
  const open = !!match && dismissed !== value;
  const query = match?.[1] ?? "";
  const results = React.useMemo(() => (open ? rankCommands(commands, query) : []), [open, commands, query]);
  const [active, setActive] = React.useState(0);
  const listRef = React.useRef<HTMLDivElement>(null);
  const id = React.useId();

  React.useEffect(() => setActive(0), [query]);
  React.useEffect(() => { if (!match) setDismissed(null); }, [match]);
  React.useEffect(() => {
    listRef.current?.querySelector<HTMLElement>(`[data-index="${active}"]`)?.scrollIntoView({ block: "nearest" });
  }, [active]);

  const run = (c: SlashCommand) => { onValueChange(""); onRun(c); };

  const onKeyDown = (e: React.KeyboardEvent) => {
    if (!open) return;
    if (e.key === "ArrowDown") { e.preventDefault(); setActive((a) => (results.length ? (a + 1) % results.length : 0)); }
    else if (e.key === "ArrowUp") { e.preventDefault(); setActive((a) => (results.length ? (a - 1 + results.length) % results.length : 0)); }
    else if ((e.key === "Enter" || e.key === "Tab") && !(e.nativeEvent as KeyboardEvent).isComposing) {
      if (results[active]) { e.preventDefault(); run(results[active]); }
      else if (e.key === "Enter") e.preventDefault();
    } else if (e.key === "Escape") { e.preventDefault(); setDismissed(value); }
  };

  // Group while keeping ranked order inside each group
  const groups: [string, { c: SlashCommand; i: number }[]][] = [];
  results.forEach((c, i) => {
    const g = c.group ?? "";
    const found = groups.find(([name]) => name === g);
    found ? found[1].push({ c, i }) : groups.push([g, [{ c, i }]]);
  });

  return (
    <div className={cn("relative", className)}>
      {open && (
        <div
          ref={listRef}
          id={id}
          role="listbox"
          aria-label="Commands"
          className="absolute inset-x-0 bottom-full z-30 mb-2 max-h-72 overflow-y-auto rounded-lg border border-border bg-bg p-1 shadow-lg"
          style={{ animation: "pl-in .12s ease-out" }}
          onMouseDown={(e) => e.preventDefault()}
        >
          {results.length === 0 && <p className="px-3 py-6 text-center text-sm text-fg-subtle">{emptyText}</p>}
          {groups.map(([g, items]) => (
            <div key={g || "_"} role="group" aria-label={g || undefined}>
              {g && <p className="px-2 pb-1 pt-2 text-xs font-medium text-fg-subtle">{g}</p>}
              {items.map(({ c, i }) => (
                <div
                  key={c.id}
                  role="option"
                  aria-selected={i === active}
                  data-index={i}
                  onMouseMove={() => setActive(i)}
                  onClick={() => run(c)}
                  className={cn("flex cursor-pointer items-center gap-3 rounded-md px-2 py-2", i === active && "bg-surface-2")}
                >
                  {c.icon && <span className="grid size-8 shrink-0 place-items-center rounded-md border border-border bg-bg text-fg-muted [&_svg]:size-4">{c.icon}</span>}
                  <span className="min-w-0 flex-1">
                    <span className="block truncate text-sm font-medium text-fg"><Highlight text={c.label} query={query} /></span>
                    {c.description && <span className="block truncate text-xs text-fg-muted">{c.description}</span>}
                  </span>
                  <span className="shrink-0 font-mono text-xs text-fg-subtle">/{c.id}</span>
                </div>
              ))}
            </div>
          ))}
          <p className="mt-1 hidden border-t border-border px-2 pb-1 pt-2 text-2xs text-fg-subtle sm:block">↑↓ to navigate · Enter to run · Esc to close</p>
        </div>
      )}
      {children({ onKeyDown, open })}
    </div>
  );
}

function Highlight({ text, query }: { text: string; query: string }) {
  const i = query ? text.toLowerCase().indexOf(query.toLowerCase()) : -1;
  if (i < 0) return <>{text}</>;
  return <>{text.slice(0, i)}<mark className="rounded-xs bg-transparent text-fg underline decoration-fg-subtle underline-offset-2">{text.slice(i, i + query.length)}</mark>{text.slice(i + query.length)}</>;
}

