"use client";

import * as React from "react";
import { ChevronDown, Globe } from "lucide-react";
import { cn } from "../../lib/cn";

/**
 * Sources
 * Collapsed by default as "Used 4 sources" with stacked favicons; expands to a list.
 * Keep it below the answer — sources support the answer, they are not the answer.
 */
export interface SourceItem { title: string; url: string; description?: string; favicon?: string }

export const hostOf = (url: string) => { try { return new URL(url).hostname.replace(/^www\./, ""); } catch { return url; } };

export function Favicon({ src, url, className }: { src?: string; url: string; className?: string }) {
  const [err, setErr] = React.useState(false);
  const s = src ?? `https://www.google.com/s2/favicons?domain=${hostOf(url)}&sz=32`;
  return err ? (
    <span className={cn("grid size-4 place-items-center rounded-full bg-surface-2 text-fg-subtle", className)}><Globe className="size-2.5" /></span>
  ) : (
    <img src={s} alt="" onError={() => setErr(true)} className={cn("size-4 rounded-full bg-bg ring-2 ring-bg", className)} />
  );
}

export function Sources({ sources, defaultOpen = false, className }: { sources: SourceItem[]; defaultOpen?: boolean; className?: string }) {
  const [open, setOpen] = React.useState(defaultOpen);
  const id = React.useId();
  return (
    <div className={cn("text-sm", className)}>
      <button
        type="button"
        aria-expanded={open}
        aria-controls={id}
        onClick={() => setOpen((o) => !o)}
        className="inline-flex h-8 items-center gap-2 rounded-full border border-border bg-bg pl-2 pr-3 font-medium text-fg-muted transition-colors hover:bg-surface-2 hover:text-fg"
      >
        <span className="flex -space-x-1">
          {sources.slice(0, 3).map((s) => <Favicon key={s.url} url={s.url} src={s.favicon} />)}
        </span>
        Used {sources.length} source{sources.length === 1 ? "" : "s"}
        <ChevronDown className={cn("size-3.5 transition-transform", open && "rotate-180")} />
      </button>
      <ol id={id} hidden={!open} className="mt-3 grid gap-2 sm:grid-cols-2" style={{ animation: "pl-in .2s ease-out" }}>
        {sources.map((s, i) => (
          <li key={s.url + i}>
            <a href={s.url} target="_blank" rel="noreferrer" className="flex h-full flex-col gap-1 rounded-md border border-border bg-bg p-3 transition-colors hover:border-border-strong hover:bg-surface">
              <span className="flex items-center gap-2 text-xs text-fg-subtle">
                <Favicon url={s.url} src={s.favicon} className="ring-0" />
                <span className="truncate">{hostOf(s.url)}</span>
                <span className="ml-auto tabular-nums">{i + 1}</span>
              </span>
              <span className="line-clamp-2 text-sm font-medium text-fg">{s.title}</span>
              {s.description && <span className="line-clamp-2 text-xs text-fg-muted">{s.description}</span>}
            </a>
          </li>
        ))}
      </ol>
    </div>
  );
}

components/ai/status-banner.tsx.source:
"use client";

import * as React from "react";
import { AlertTriangle, Clock, CreditCard, Info, ShieldOff, WifiOff, X } from "lucide-react";
import { cn } from "../../lib/cn";
import { Button } from "../ui/button";

/**
 * StatusBanner
 * Every failure an AI product can hit, each with a next step.
 * Copy rule: what happened → why (if useful) → what to do. Never "Something went wrong."
 * `countdown` (seconds) ticks down and enables the action at 0 — ideal for rate limits.
 */
export type StatusKind = "error" | "rate-limit" | "credits" | "offline" | "content-policy" | "info";

const presets: Record<StatusKind, { icon: React.ReactNode; tone: string; title: string; body: string; action: string }> = {
  error: { icon: <AlertTriangle />, tone: "danger", title: "The response didn't finish", body: "The connection dropped mid-answer. Your message is saved.", action: "Try again" },
  "rate-limit": { icon: <Clock />, tone: "warning", title: "Slow down a little", body: "You've sent a lot of messages in a short time.", action: "Retry" },
  credits: { icon: <CreditCard />, tone: "neutral", title: "You're out of credits", body: "Upgrade to keep going, or wait for your monthly reset.", action: "Upgrade" },
  offline: { icon: <WifiOff />, tone: "neutral", title: "You're offline", body: "We'll send your message when you reconnect.", action: "Retry now" },
  "content-policy": { icon: <ShieldOff />, tone: "neutral", title: "This request can't be completed", body: "Try rephrasing, or ask about something else.", action: "Edit message" },
  info: { icon: <Info />, tone: "info", title: "Heads up", body: "", action: "Got it" },
};
const tones: Record<string, string> = {
  danger: "border-danger/25 bg-danger/[0.04] [&_[data-icon]]:text-danger",
  warning: "border-warning/30 bg-warning/[0.05] [&_[data-icon]]:text-warning",
  info: "border-info/25 bg-info/[0.04] [&_[data-icon]]:text-info",
  neutral: "border-border bg-surface [&_[data-icon]]:text-fg-muted",
};

export interface StatusBannerProps {
  kind: StatusKind;
  title?: string;
  description?: React.ReactNode;
  actionLabel?: string;
  onAction?: () => void;
  onDismiss?: () => void;
  countdown?: number;
  className?: string;
}

export function StatusBanner({ kind, title, description, actionLabel, onAction, onDismiss, countdown, className }: StatusBannerProps) {
  const p = presets[kind];
  const [left, setLeft] = React.useState(countdown ?? 0);
  React.useEffect(() => { setLeft(countdown ?? 0); }, [countdown]);
  React.useEffect(() => {
    if (left <= 0) return;
    const t = setTimeout(() => setLeft((l) => l - 1), 1000);
    return () => clearTimeout(t);
  }, [left]);

  return (
    <div role={kind === "error" ? "alert" : "status"} className={cn("flex items-start gap-3 rounded-lg border p-4 text-sm", tones[p.tone], className)} style={{ animation: "pl-in .2s ease-out" }}>
      <span data-icon className="mt-0.5 shrink-0 [&_svg]:size-4">{p.icon}</span>
      <div className="min-w-0 flex-1">
        <p className="font-medium text-fg">{title ?? p.title}</p>
        {(description ?? p.body) && <p className="mt-0.5 text-fg-muted">{description ?? p.body}</p>}
        {left > 0 && <p className="mt-1 text-xs tabular-nums text-fg-subtle">You can try again in {left}s</p>}
      </div>
      {onAction && (
        <Button size="sm" variant={kind === "credits" ? "primary" : "outline"} onClick={onAction} disabled={left > 0} className="shrink-0">
          {actionLabel ?? p.action}
        </Button>
      )}
      {onDismiss && <button type="button" onClick={onDismiss} aria-label="Dismiss" className="-mr-1 grid size-8 shrink-0 place-items-center rounded-sm text-fg-subtle hover:bg-surface-2 hover:text-fg"><X className="size-4" /></button>}
    </div>
  );
}

components/ai/streaming-text.tsx.source:
"use client";

import * as React from "react";
import { cn } from "../../lib/cn";

/**
 * StreamingText
 * Renders a model's reply as it arrives. Tokens land in bursts; this smooths them into an
 * even reveal that speeds up when it falls behind, so text never stutters or lags far behind.
 * - Lightweight markdown: headings, paragraphs, lists, **bold**, *italic*, `code`, fenced code
 * - Blinking caret while streaming, removed when done
 * - Respects prefers-reduced-motion (shows text immediately)
 * - aria-busy while streaming so screen readers read the finished answer once
 */
export interface StreamingTextProps {
  /** The full text received so far — just keep appending to it */
  text: string;
  isStreaming?: boolean;
  /** Characters per second when caught up (default 90) */
  speed?: number;
  /** Render markdown (default true) */
  markdown?: boolean;
  showCaret?: boolean;
  onRevealed?: () => void;
  className?: string;
}

export function useSmoothText(text: string, speed = 90) {
  const [n, setN] = React.useState(text.length);
  const target = React.useRef(text.length);
  const shown = React.useRef(n);
  target.current = text.length;

  React.useEffect(() => {
    if (text.length < shown.current) { shown.current = text.length; setN(text.length); }
  }, [text]);

  React.useEffect(() => {
    const reduce = typeof matchMedia !== "undefined" && matchMedia("(prefers-reduced-motion: reduce)").matches;
    let raf = 0, last = performance.now();
    const tick = (t: number) => {
      const dt = (t - last) / 1000; last = t;
      const backlog = target.current - shown.current;
      if (backlog > 0) {
        // Base speed, accelerating with backlog so we never trail by more than ~1s
        const rate = reduce ? Infinity : Math.max(speed, backlog * 2.5);
        shown.current = Math.min(target.current, shown.current + Math.max(1, Math.round(rate * dt)));
        setN(shown.current);
      }
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [speed]);

  return text.slice(0, n);
}

export function StreamingText({ text, isStreaming = false, speed = 90, markdown = true, showCaret = true, onRevealed, className }: StreamingTextProps) {
  const visible = useSmoothText(text, speed);
  const revealing = visible.length < text.length;
  const caret = showCaret && (isStreaming || revealing);
  const done = !isStreaming && !revealing;
  const fired = React.useRef(false);
  React.useEffect(() => {
    if (done && !fired.current && text) { fired.current = true; onRevealed?.(); }
    if (!done) fired.current = false;
  }, [done, text, onRevealed]);

  return (
    <div aria-busy={!done} aria-live="polite" className={cn("text-md text-fg [overflow-wrap:anywhere]", className)}>
      {markdown ? <Markdown source={visible} caret={caret} /> : <p className="whitespace-pre-wrap">{visible}{caret && <Caret />}</p>}
    </div>
  );
}

function Caret() {
  return <span aria-hidden className="ml-0.5 inline-block h-[1.1em] w-[0.5em] translate-y-[0.15em] rounded-[1px] bg-fg" style={{ animation: "pl-blink 1s steps(1) infinite" }} />;
}

/* ---------- tiny markdown ---------- */
function inline(s: string, key: string): React.ReactNode[] {
  const out: React.ReactNode[] = [];
  const re = /(`[^`]+`|\*\*[^*]+\*\*|\*[^*\s][^*]*\*)/g;
  let last = 0, m: RegExpExecArray | null, i = 0;
  while ((m = re.exec(s))) {
    if (m.index > last) out.push(s.slice(last, m.index));
    const t = m[0];
    if (t.startsWith("`")) out.push(<code key={key + i++} className="rounded-xs bg-surface-2 px-1 py-0.5 font-mono text-[0.9em]">{t.slice(1, -1)}</code>);
    else if (t.startsWith("**")) out.push(<strong key={key + i++} className="font-semibold">{t.slice(2, -2)}</strong>);
    else out.push(<em key={key + i++}>{t.slice(1, -1)}</em>);
    last = m.index + t.length;
  }
  if (last < s.length) out.push(s.slice(last));
  return out;
}

export function Markdown({ source, caret }: { source: string; caret?: boolean }) {
  const lines = source.split("\n");
  const blocks: React.ReactNode[] = [];
  let i = 0, k = 0;
  const lastIndex = () => blocks.length;
  let caretAt = -1;
  while (i < lines.length) {
    const line = lines[i];
    if (line.startsWith("```")) {
      const lang = line.slice(3).trim();
      const body: string[] = [];
      i++;
      while (i < lines.length && !lines[i].startsWith("```")) body.push(lines[i++]);
      i++;
      blocks.push(<pre key={k++} className="overflow-x-auto rounded-lg border border-border bg-surface p-3 font-mono text-sm leading-6"><code data-lang={lang || undefined}>{body.join("\n")}</code></pre>);
      continue;
    }
    const h = /^(#{1,3})\s+(.*)$/.exec(line);
    if (h) { const T = (["h3", "h4", "h5"] as const)[h[1].length - 1]; blocks.push(<T key={k++} className="font-semibold text-fg">{inline(h[2], "h" + k)}</T>); i++; continue; }
    if (/^\s*[-*]\s+/.test(line) || /^\s*\d+\.\s+/.test(line)) {
      const ordered = /^\s*\d+\./.test(line);
      const items: string[] = [];
      while (i < lines.length && (ordered ? /^\s*\d+\.\s+/ : /^\s*[-*]\s+/).test(lines[i])) items.push(lines[i++].replace(/^\s*(?:[-*]|\d+\.)\s+/, ""));
      const L = ordered ? "ol" : "ul";
      blocks.push(<L key={k++} className={cn("space-y-1 pl-5", ordered ? "list-decimal" : "list-disc")}>{items.map((t, j) => <li key={j}>{inline(t, `l${k}-${j}`)}</li>)}</L>);
      continue;
    }
    if (!line.trim()) { i++; continue; }
    const para: string[] = [];
    while (i < lines.length && lines[i].trim() && !/^(#{1,3}\s|```|\s*[-*]\s|\s*\d+\.\s)/.test(lines[i])) para.push(lines[i++]);
    blocks.push(<p key={k++}>{inline(para.join(" "), "p" + k)}</p>);
  }
  caretAt = lastIndex() - 1;
  return (
    <div className="space-y-3">
      {blocks.map((b, j) => {
        if (j !== caretAt || !caret || !React.isValidElement(b)) return b;
        const el = b as React.ReactElement<{ children?: React.ReactNode }>;
        if (el.type === "p" || typeof el.type === "string" && /^h\d$/.test(el.type)) return React.cloneElement(el, {}, el.props.children, <Caret key="caret" />);
        return <React.Fragment key={j}>{el}<Caret /></React.Fragment>;
      })}
      {blocks.length === 0 && caret && <p><Caret /></p>}
    </div>
  );
}

components/ai/suggestion.tsx.source:
"use client";

import * as React from "react";
import { cn } from "../../lib/cn";

/**
 * Suggestion
 * Starter prompts and follow-ups. Horizontal scroll on small screens so they never wrap into a wall.
 * Use 3–4 max. Write them as things the user would actually type.
 */
export function Suggestions({ className, children, ...p }: React.HTMLAttributes<HTMLDivElement>) {
  return (
    <div className={cn("-mx-1 flex min-w-0 max-w-full gap-2 overflow-x-auto px-1 pb-1 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden", className)} role="group" aria-label="Suggestions" {...p}>
      {children}
    </div>
  );
}

export interface SuggestionProps extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "onClick"> {
  suggestion: string;
  onPick: (suggestion: string) => void;
  icon?: React.ReactNode;
}

export function Suggestion({ suggestion, onPick, icon, className, children, ...p }: SuggestionProps) {
  return (
    <button
      type="button"
      onClick={() => onPick(suggestion)}
      className={cn(
        "inline-flex h-8 shrink-0 items-center gap-2 rounded-full border border-border bg-bg px-3 text-sm text-fg-muted transition-colors",
        "hover:border-border-strong hover:bg-surface hover:text-fg focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-fg/20 [&_svg]:size-4",
        className
      )}
      {...p}
    >
      {icon}
      {children ?? suggestion}
    </button>
  );
}

/** Card-style grid for empty states — two columns, title + description. */
export function SuggestionCard({ title, description, icon, onPick, className }: { title: string; description?: string; icon?: React.ReactNode; onPick: (s: string) => void; className?: string }) {
  return (
    <button
      type="button"
      onClick={() => onPick(description ? `${title} ${description}` : title)}
      className={cn(
        "flex items-start gap-3 rounded-lg border border-border bg-bg p-4 text-left transition-colors hover:border-border-strong hover:bg-surface",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-fg/20",
        className
      )}
    >
      {icon && <span className="mt-0.5 text-fg-muted [&_svg]:size-4">{icon}</span>}
      <span className="min-w-0">
        <span className="block text-base font-medium text-fg">{title}</span>
        {description && <span className="mt-0.5 block text-sm text-fg-muted">{description}</span>}
      </span>
    </button>
  );
}

components/ai/task.tsx.source:
"use client";

import * as React from "react";
import { ChevronDown, FileText, Search } from "lucide-react";
import { cn } from "../../lib/cn";
import { Spinner } from "../ui/spinner";
import { Shimmer } from "./loader";

/**
 * Task
 * A collapsible unit of agent work ("Searching the codebase") with the concrete
 * things it touched listed underneath — files, queries, links.
 */
export interface TaskItem { text: React.ReactNode; file?: string }

export function Task({ title, items, status = "done", icon, defaultOpen = true, className }: {
  title: string;
  items: TaskItem[];
  status?: "running" | "done";
  icon?: React.ReactNode;
  defaultOpen?: boolean;
  className?: string;
}) {
  const [open, setOpen] = React.useState(defaultOpen);
  const id = React.useId();
  return (
    <div className={cn("text-sm", className)}>
      <button type="button" aria-expanded={open} aria-controls={id} onClick={() => setOpen((o) => !o)} className="group inline-flex h-7 items-center gap-2 text-fg-muted transition-colors hover:text-fg">
        <span className="[&_svg]:size-4">{status === "running" ? <Spinner className="size-3.5" /> : icon ?? <Search />}</span>
        {status === "running" ? <Shimmer>{title}</Shimmer> : <span className="font-medium">{title}</span>}
        <ChevronDown className={cn("size-3.5 transition-transform duration-200", open && "rotate-180")} />
      </button>
      <ul id={id} hidden={!open} className="ml-2 mt-2 space-y-2 border-l border-border pl-4" style={{ animation: "pl-in .2s ease-out" }}>
        {items.map((it, i) => (
          <li key={i} className="flex flex-wrap items-center gap-2 text-fg-muted">
            {it.text}
            {it.file && <TaskFile name={it.file} />}
          </li>
        ))}
      </ul>
    </div>
  );
}

export function TaskFile({ name }: { name: string }) {
  return (
    <span className="inline-flex h-6 items-center gap-1.5 rounded-sm border border-border bg-surface px-2 font-mono text-xs text-fg">
      <FileText className="size-3 text-fg-subtle" />{name}
    </span>
  );
}

