"use client";

import * as React from "react";
import { createPortal } from "react-dom";
import { AlertCircle, CheckCircle2, Info, X } from "lucide-react";
import { cn } from "../../lib/cn";

/**
 * Toast
 * Wrap your app once: <Toaster>{app}</Toaster>, then `const toast = useToast(); toast({ title: "Copied" })`.
 * Auto-dismisses (4s), max 3 visible, pauses while hovered, announced to screen readers.
 */
export interface ToastOptions { title: string; description?: string; tone?: "default" | "success" | "error"; action?: { label: string; onClick: () => void }; duration?: number }
interface Item extends ToastOptions { id: number }

const Ctx = React.createContext<(t: ToastOptions) => void>(() => {});
export const useToast = () => React.useContext(Ctx);

export function ToastView({ title, description, tone = "default", action, onClose, className }: ToastOptions & { onClose?: () => void; className?: string }) {
  const Icon = tone === "success" ? CheckCircle2 : tone === "error" ? AlertCircle : Info;
  return (
    <div role={tone === "error" ? "alert" : "status"} className={cn("pointer-events-auto flex w-full items-start gap-3 rounded-lg border border-border bg-bg p-4 shadow-lg", className)} style={{ animation: "pl-in .2s var(--ease-out)" }}>
      <Icon className={cn("mt-0.5 size-4 shrink-0", tone === "success" ? "text-success" : tone === "error" ? "text-danger" : "text-fg-muted")} />
      <div className="min-w-0 flex-1">
        <p className="text-sm font-medium text-fg">{title}</p>
        {description && <p className="mt-0.5 text-sm text-fg-muted">{description}</p>}
      </div>
      {action && <button type="button" onClick={action.onClick} className="h-6 shrink-0 rounded-xs border border-border px-2 text-xs font-medium text-fg hover:bg-surface-2">{action.label}</button>}
      {onClose && <button type="button" onClick={onClose} aria-label="Dismiss" className="shrink-0 text-fg-subtle hover:text-fg"><X className="size-4" /></button>}
    </div>
  );
}

export function Toaster({ children }: { children: React.ReactNode }) {
  const [items, setItems] = React.useState<Item[]>([]);
  const timers = React.useRef(new Map<number, number>());
  const remove = React.useCallback((id: number) => { setItems((l) => l.filter((t) => t.id !== id)); window.clearTimeout(timers.current.get(id)); }, []);
  const arm = (id: number, ms: number) => timers.current.set(id, window.setTimeout(() => remove(id), ms));
  const push = React.useCallback((t: ToastOptions) => {
    const id = Date.now() + Math.random();
    setItems((l) => [...l.slice(-2), { ...t, id }]);
    arm(id, t.duration ?? 4000);
  }, [remove]);

  return (
    <Ctx.Provider value={push}>
      {children}
      {typeof document !== "undefined" && createPortal(
        <div aria-live="polite" className="pointer-events-none fixed bottom-4 right-4 z-[200] flex w-[calc(100%-32px)] max-w-sm flex-col gap-2">
          {items.map((t) => (
            <div key={t.id} onMouseEnter={() => window.clearTimeout(timers.current.get(t.id))} onMouseLeave={() => arm(t.id, 2000)}>
              <ToastView {...t} onClose={() => remove(t.id)} />
            </div>
          ))}
        </div>,
        document.body
      )}
    </Ctx.Provider>
  );
}

components/ai/tool.tsx.source:
"use client";

import * as React from "react";
import { Check, ChevronDown, CircleDashed, Clock, ShieldQuestion, Wrench, X } from "lucide-react";
import { cn } from "../../lib/cn";
import { Badge } from "../ui/badge";
import { Spinner } from "../ui/spinner";
import { CodeBlock } from "./code-block";

/**
 * Tool
 * One tool/function call. Collapsed header shows name + status; expanding reveals
 * parameters and the result (or error). Matches the AI SDK tool-invocation states.
 */
export type ToolState = "pending" | "running" | "awaiting-approval" | "completed" | "error" | "denied";

const stateMeta: Record<ToolState, { label: string; tone: React.ComponentProps<typeof Badge>["tone"]; icon: React.ReactNode }> = {
  pending: { label: "Pending", tone: "neutral", icon: <CircleDashed /> },
  running: { label: "Running", tone: "info", icon: <Spinner className="size-3" /> },
  "awaiting-approval": { label: "Needs approval", tone: "warning", icon: <ShieldQuestion /> },
  completed: { label: "Completed", tone: "success", icon: <Check /> },
  error: { label: "Error", tone: "danger", icon: <X /> },
  denied: { label: "Denied", tone: "neutral", icon: <X /> },
};

export interface ToolProps {
  name: string;
  /** Human title, e.g. "Searched the web" — falls back to name */
  title?: string;
  state: ToolState;
  input?: unknown;
  output?: unknown;
  errorText?: string;
  duration?: string;
  icon?: React.ReactNode;
  defaultOpen?: boolean;
  /** Custom output renderer — e.g. a weather card instead of JSON */
  children?: React.ReactNode;
  className?: string;
}

const json = (v: unknown) => (typeof v === "string" ? v : JSON.stringify(v, null, 2));

export function Tool({ name, title, state, input, output, errorText, duration, icon, defaultOpen, children, className }: ToolProps) {
  const [open, setOpen] = React.useState(defaultOpen ?? (state === "error" || state === "awaiting-approval"));
  const id = React.useId();
  const m = stateMeta[state];
  const hasBody = input !== undefined || output !== undefined || errorText || children;

  return (
    <div className={cn("overflow-hidden rounded-lg border border-border bg-bg text-sm", className)}>
      <button
        type="button"
        aria-expanded={hasBody ? open : undefined}
        aria-controls={id}
        disabled={!hasBody}
        onClick={() => setOpen((o) => !o)}
        className="flex h-11 w-full items-center gap-3 px-3 text-left transition-colors enabled:hover:bg-surface disabled:cursor-default"
      >
        <span className="grid size-6 shrink-0 place-items-center rounded-sm bg-surface-2 text-fg-muted [&_svg]:size-3.5">{icon ?? <Wrench />}</span>
        <span className="min-w-[3rem] flex-1 truncate font-medium text-fg">{title ?? name}</span>
        {title && <code className="hidden min-w-0 shrink-[2] truncate font-mono text-xs text-fg-subtle lg:inline">{name}</code>}
        {duration && <span className="inline-flex shrink-0 items-center gap-1 text-xs tabular-nums text-fg-subtle"><Clock className="size-3" />{duration}</span>}
        <Badge tone={m.tone} className="shrink-0">{m.icon}{m.label}</Badge>
        {hasBody && <ChevronDown className={cn("size-4 shrink-0 text-fg-subtle transition-transform duration-200", open && "rotate-180")} />}
      </button>
      {hasBody && (
        <div id={id} hidden={!open} className="space-y-3 border-t border-border bg-surface p-3">
          {input !== undefined && <ToolSection label="Parameters"><CodeBlock code={json(input)} language="json" className="bg-bg" /></ToolSection>}
          {errorText && <ToolSection label="Error"><div className="rounded-md border border-danger/20 bg-danger/5 p-3 font-mono text-xs text-danger">{errorText}</div></ToolSection>}
          {children ? <ToolSection label="Result">{children}</ToolSection> : output !== undefined && <ToolSection label="Result"><CodeBlock code={json(output)} language="json" className="bg-bg" maxHeight={240} /></ToolSection>}
        </div>
      )}
    </div>
  );
}

function ToolSection({ label, children }: { label: string; children: React.ReactNode }) {
  return (
    <div>
      <p className="mb-2 text-xs font-medium uppercase tracking-wide text-fg-subtle">{label}</p>
      {children}
    </div>
  );
}

components/ai/upgrade-dialog.tsx.source:
"use client";

import * as React from "react";
import { Check } from "lucide-react";
import { cn } from "../../lib/cn";
import { Badge } from "../ui/badge";
import { Button } from "../ui/button";
import { Dialog } from "../ui/dialog";

/**
 * UpgradeDialog
 * Paywall for credit exhaustion or locked models. Supports a monthly/yearly toggle.
 * Lead with the reason they hit the wall, then the plan that removes it.
 */
export interface PricingPlan {
  id: string;
  name: string;
  price: { monthly: string; yearly?: string };
  description?: string;
  features: string[];
  recommended?: boolean;
  current?: boolean;
  cta?: string;
}

export interface UpgradeDialogProps {
  open: boolean;
  onClose: () => void;
  onSelect: (planId: string, billing: "monthly" | "yearly") => void;
  title?: string;
  description?: string;
  plans: PricingPlan[];
  yearlyNote?: string;
}

export function UpgradeDialog({ open, onClose, onSelect, title = "Upgrade to keep going", description, plans, yearlyNote = "Save 20%" }: UpgradeDialogProps) {
  const [billing, setBilling] = React.useState<"monthly" | "yearly">("monthly");
  const hasYearly = plans.some((p) => p.price.yearly);
  return (
    <Dialog open={open} onClose={onClose} labelledBy="pl-upgrade-title" className="max-w-2xl">
      <div className="p-6">
        <h2 id="pl-upgrade-title" className="pr-8 text-xl font-semibold text-fg">{title}</h2>
        {description && <p className="mt-1 text-base text-fg-muted">{description}</p>}
        {hasYearly && (
          <div className="mt-6 inline-flex h-9 rounded-md bg-surface-2 p-1 text-sm font-medium" role="radiogroup" aria-label="Billing period">
            {(["monthly", "yearly"] as const).map((b) => (
              <button key={b} type="button" role="radio" aria-checked={billing === b} onClick={() => setBilling(b)} className={cn("inline-flex items-center gap-2 rounded-sm px-3 capitalize transition-colors", billing === b ? "bg-bg text-fg shadow-xs" : "text-fg-muted hover:text-fg")}>
                {b}{b === "yearly" && <span className="text-2xs text-success">{yearlyNote}</span>}
              </button>
            ))}
          </div>
        )}
        <div className={cn("mt-6 grid gap-4", plans.length > 1 && "sm:grid-cols-2")}>
          {plans.map((p) => (
            <div key={p.id} className={cn("flex flex-col rounded-lg border p-5", p.recommended ? "border-fg shadow-sm" : "border-border")}>
              <div className="flex items-center justify-between gap-2">
                <p className="text-base font-medium text-fg">{p.name}</p>
                {p.recommended && <Badge tone="accent">Recommended</Badge>}
                {p.current && <Badge tone="outline">Current</Badge>}
              </div>
              {p.description && <p className="mt-1 text-sm text-fg-muted">{p.description}</p>}
              <p className="mt-4 flex items-baseline gap-1">
                <span className="text-4xl font-semibold text-fg">{billing === "yearly" && p.price.yearly ? p.price.yearly : p.price.monthly}</span>
                <span className="text-sm text-fg-muted">/ month</span>
              </p>
              <ul className="mt-4 flex-1 space-y-2">
                {p.features.map((f) => <li key={f} className="flex gap-2 text-sm text-fg-muted"><Check className="mt-0.5 size-4 shrink-0 text-fg" />{f}</li>)}
              </ul>
              <Button className="mt-6 w-full" variant={p.recommended ? "primary" : "outline"} disabled={p.current} onClick={() => onSelect(p.id, billing)}>
                {p.current ? "Current plan" : p.cta ?? `Get ${p.name}`}
              </Button>
            </div>
          ))}
        </div>
        <p className="mt-4 text-center text-xs text-fg-subtle">Cancel anytime. Prices in USD.</p>
      </div>
    </Dialog>
  );
}

components/ai/usage-chart.tsx.source:
"use client";

import * as React from "react";
import { cn } from "../../lib/cn";
import { Tabs } from "../ui/tabs";

/**
 * UsageChart
 * Daily tokens, messages or cost for billing and admin pages.
 * One series, one hue (the accent), bars anchored to a zero baseline with 2px gaps and 4px rounded tops;
 * days over the limit turn amber,
 * a dashed daily-limit line, hover tooltip per bar, headline total, and an accessible table.
 */
export interface UsagePoint { date: Date; value: number }

export interface UsageChartProps {
  data: UsagePoint[];
  label?: string;
  unit?: string;
  format?: (v: number) => string;
  /** Daily limit — drawn as a dashed reference line */
  limit?: number;
  ranges?: { value: string; label: string; days: number }[];
  height?: number;
  className?: string;
}

const compact = (v: number) => (v >= 1e6 ? `${(v / 1e6).toFixed(1)}M` : v >= 1e3 ? `${(v / 1e3).toFixed(v >= 1e4 ? 0 : 1)}K` : String(Math.round(v)));
const niceMax = (v: number) => { const p = Math.pow(10, Math.floor(Math.log10(v || 1))); const n = v / p; return (n <= 1 ? 1 : n <= 2 ? 2 : n <= 5 ? 5 : 10) * p; };

export function UsageChart({ data, label = "Tokens", unit = "", format = compact, limit, ranges = [{ value: "7", label: "7 days", days: 7 }, { value: "30", label: "30 days", days: 30 }], height = 200, className }: UsageChartProps) {
  const [range, setRange] = React.useState(ranges[ranges.length - 1]?.value ?? "30");
  const [hover, setHover] = React.useState<number | null>(null);
  const days = ranges.find((r) => r.value === range)?.days ?? data.length;
  const pts = data.slice(-days);
  const total = pts.reduce((s, p) => s + p.value, 0);
  const max = niceMax(Math.max(...pts.map((p) => p.value), limit ?? 0));
  const ticks = [0, max / 2, max];
  const d = (x: Date) => x.toLocaleDateString(undefined, { month: "short", day: "numeric" });

  return (
    <div className={cn("rounded-lg border border-border bg-bg p-4", className)}>
      <div className="flex flex-wrap items-start justify-between gap-3">
        <div>
          <p className="text-sm text-fg-muted">{label} · last {days} days</p>
          <p className="mt-1 text-3xl font-semibold tabular-nums text-fg">{format(total)}{unit && <span className="ml-1 text-base font-normal text-fg-muted">{unit}</span>}</p>
          {limit != null && (
            <p className="mt-2 flex items-center gap-3 text-xs text-fg-muted">
              <span className="inline-flex items-center gap-1.5"><span className="w-4 border-t border-dashed border-fg-muted" />Daily limit {format(limit)}</span>
              {pts.some((p) => p.value > limit) && <span className="inline-flex items-center gap-1.5"><span className="size-2 rounded-[2px] bg-warning" />Over limit</span>}
            </p>
          )}
        </div>
        {ranges.length > 1 && <Tabs variant="segmented" size="sm" value={range} onValueChange={setRange} items={ranges.map((r) => ({ value: r.value, label: r.label }))} />}
      </div>

      <div className="relative mt-6 flex gap-2" style={{ height }}>
        <div className="flex w-9 shrink-0 flex-col-reverse justify-between pb-6 text-right text-2xs tabular-nums text-fg-subtle" aria-hidden>
          {ticks.map((t) => <span key={t} className="-mb-2 leading-4">{format(t)}</span>)}
        </div>
        <div className="relative min-w-0 flex-1 pb-6">
          <div className="absolute inset-x-0 top-0 bottom-6">
            {ticks.map((t) => <div key={t} className="absolute inset-x-0 border-t border-border" style={{ bottom: `${(t / max) * 100}%` }} aria-hidden />)}
            {limit != null && (
              <div className="absolute inset-x-0 border-t border-dashed border-fg-muted" style={{ bottom: `${(limit / max) * 100}%` }} aria-hidden />
            )}
            <div className="absolute inset-0 flex items-end gap-[2px]" role="img" aria-label={`${label} per day, total ${format(total)}`}>
              {pts.map((p, i) => {
                const over = limit != null && p.value > limit;
                return (
                  <div key={i} className="flex h-full min-w-0 flex-1 items-end" onMouseEnter={() => setHover(i)} onMouseLeave={() => setHover(null)}>
                    <div
                      className={cn("w-full rounded-t-[4px] transition-opacity", over ? "bg-warning" : "bg-accent", hover != null && hover !== i && "opacity-40")}
                      style={{ height: `${Math.max((p.value / max) * 100, p.value ? 1 : 0)}%` }}
                    />
                  </div>
                );
              })}
            </div>
            {hover != null && pts[hover] && (
              <div className="pointer-events-none absolute z-10 -translate-x-1/2 -translate-y-full whitespace-nowrap rounded-md border border-border bg-bg px-2.5 py-1.5 text-xs shadow-md" style={{ left: `${((hover + 0.5) / pts.length) * 100}%`, bottom: `${(pts[hover].value / max) * 100}%`, marginBottom: 8 }}>
                <p className="text-fg-muted">{d(pts[hover].date)}</p>
                <p className="font-medium tabular-nums text-fg">{format(pts[hover].value)} {unit}</p>
              </div>
            )}
          </div>
          <div className="absolute inset-x-0 bottom-0 flex justify-between text-2xs text-fg-subtle" aria-hidden>
            <span>{pts[0] && d(pts[0].date)}</span><span>{pts[pts.length - 1] && d(pts[pts.length - 1].date)}</span>
          </div>
        </div>
      </div>

      <table className="sr-only">
        <caption>{label} per day</caption>
        <thead><tr><th>Date</th><th>{label}</th></tr></thead>
        <tbody>{pts.map((p, i) => <tr key={i}><td>{d(p.date)}</td><td>{format(p.value)}</td></tr>)}</tbody>
      </table>
    </div>
  );
}

components/ai/usage-meter.tsx.source:
"use client";

import * as React from "react";
import { cn } from "../../lib/cn";

/**
 * UsageMeter
 * Credits, messages or tokens remaining. Neutral until 80%, amber at 80%, red at 95%.
 * Always say when it resets — a limit without a reset time feels like a wall.
 */
export interface UsageMeterProps {
  used: number;
  limit: number;
  label?: string;
  unit?: string;
  resetText?: string;
  onUpgrade?: () => void;
  variant?: "card" | "inline";
  className?: string;
}

export function UsageMeter({ used, limit, label = "Credits", unit, resetText, onUpgrade, variant = "card", className }: UsageMeterProps) {
  const pct = Math.min(100, (used / limit) * 100);
  const bar = pct >= 95 ? "bg-danger" : pct >= 80 ? "bg-warning" : "bg-fg";
  const n = (x: number) => x.toLocaleString();
  return (
    <div className={cn("space-y-2", variant === "card" && "rounded-lg border border-border bg-bg p-4", className)}>
      <div className="flex items-baseline justify-between gap-3 text-sm">
        <span className="font-medium text-fg">{label}</span>
        <span className="text-xs tabular-nums text-fg-muted">{n(used)} / {n(limit)}{unit && ` ${unit}`}</span>
      </div>
      <div className="h-1.5 overflow-hidden rounded-full bg-surface-2" role="progressbar" aria-label={label} aria-valuenow={used} aria-valuemin={0} aria-valuemax={limit}>
        <div className={cn("h-full rounded-full transition-[width] duration-500 ease-out", bar)} style={{ width: `${pct}%` }} />
      </div>
      {(resetText || onUpgrade) && (
        <div className="flex items-center justify-between text-xs">
          <span className="text-fg-subtle">{resetText}</span>
          {onUpgrade && <button type="button" onClick={onUpgrade} className="font-medium text-fg underline-offset-4 hover:underline">Upgrade</button>}
        </div>
      )}
    </div>
  );
}

components/ai/voice-input.tsx.source:
"use client";

import * as React from "react";
import { Check, Mic, X } from "lucide-react";
import { cn } from "../../lib/cn";
import { Button } from "../ui/button";
import { Tooltip } from "../ui/tooltip";

/**
 * VoiceInput
 * Dictation for the prompt box. Idle mic → recording bar with live waveform + timer
 * → Cancel (discard) or Done (insert transcript). Pass `level` (0–1) from your audio analyser;
 * without it the bars animate on their own.
 */
export type VoiceState = "idle" | "recording" | "processing";

export interface VoiceInputProps {
  state: VoiceState;
  onStart: () => void;
  onCancel: () => void;
  onDone: () => void;
  /** Live mic level 0–1 */
  level?: number;
  className?: string;
}

export function VoiceInput({ state, onStart, onCancel, onDone, level, className }: VoiceInputProps) {
  const [secs, setSecs] = React.useState(0);
  React.useEffect(() => {
    if (state !== "recording") { setSecs(0); return; }
    const t = setInterval(() => setSecs((s) => s + 1), 1000);
    return () => clearInterval(t);
  }, [state]);

  if (state === "idle")
    return (
      <Tooltip label="Dictate">
        <Button variant="ghost" size="icon-sm" onClick={onStart} aria-label="Start dictation" className={className}><Mic /></Button>
      </Tooltip>
    );

  const bars = 24;
  return (
    <div className={cn("flex h-10 items-center gap-2 rounded-full border border-border bg-bg pl-1 pr-1 shadow-sm", className)} role="group" aria-label="Recording">
      <Tooltip label="Cancel"><Button variant="ghost" size="icon-sm" onClick={onCancel} aria-label="Cancel recording" className="rounded-full"><X /></Button></Tooltip>
      <span className="size-2 shrink-0 rounded-full bg-danger" style={{ animation: "pl-pulse 1.2s infinite" }} aria-hidden />
      <div className="flex h-6 flex-1 items-center gap-[3px]" aria-hidden>
        {Array.from({ length: bars }).map((_, i) => (
          <span
            key={i}
            className={cn("w-[3px] rounded-full", state === "processing" ? "h-1 bg-fg-subtle" : "h-full bg-fg")}
            style={state === "recording" ? (level != null ? { transform: `scaleY(${Math.max(0.15, level * (0.5 + 0.5 * Math.sin(i * 1.3)))})` } : { animation: `pl-wave ${0.8 + (i % 5) * 0.12}s ${i * 0.04}s infinite ease-in-out` }) : undefined}
          />
        ))}
      </div>
      <span className="w-10 text-right text-xs tabular-nums text-fg-muted" aria-live="off">
        {state === "processing" ? "…" : `${Math.floor(secs / 60)}:${String(secs % 60).padStart(2, "0")}`}
      </span>
      <Tooltip label="Done"><Button size="icon-sm" onClick={onDone} disabled={state === "processing"} aria-label="Finish and transcribe" className="rounded-full"><Check /></Button></Tooltip>
    </div>
  );
}

components/ai/voice-mode.tsx.source:
"use client";

import * as React from "react";
import { Captions, Mic, MicOff, X } from "lucide-react";
import { cn } from "../../lib/cn";

/**
 * VoiceMode
 * A live voice conversation: an orb that shows who's talking, the current state in words,
 * optional live captions, and the two controls that matter — mute and end.
 * You own the audio; pass the state and an input/output level (0–1) and the orb follows.
 */
export type VoiceModeState = "connecting" | "listening" | "thinking" | "speaking";

export interface VoiceModeProps {
  state: VoiceModeState;
  /** Current audio level 0–1 (mic while listening, output while speaking) */
  level?: number;
  muted?: boolean;
  onMutedChange?: (muted: boolean) => void;
  onEnd: () => void;
  /** Live caption of what's being said */
  caption?: string;
  captions?: boolean;
  onCaptionsChange?: (on: boolean) => void;
  className?: string;
}

const label: Record<VoiceModeState, string> = { connecting: "Connecting…", listening: "Listening", thinking: "Thinking", speaking: "Speaking" };

export function VoiceOrb({ state, level = 0, muted, size = 160, className }: { state: VoiceModeState; level?: number; muted?: boolean; size?: number; className?: string }) {
  const l = muted && state === "listening" ? 0 : Math.max(0, Math.min(1, level));
  const scale = state === "speaking" ? 1 + l * 0.18 : state === "listening" ? 1 + l * 0.1 : 1;
  return (
    <div className={cn("relative grid place-items-center", className)} style={{ width: size, height: size }} aria-hidden>
      {state === "listening" && !muted && (
        <span className="absolute inset-0 rounded-full border border-fg/20" style={{ transform: `scale(${1.08 + l * 0.25})`, opacity: 0.3 + l * 0.6, transition: "transform 90ms linear, opacity 90ms linear" }} />
      )}
      <span
        className={cn("absolute inset-[6%] rounded-full", state === "thinking" && "animate-[pl-spin_2.4s_linear_infinite]", state === "connecting" && "animate-[pl-pulse_1.4s_ease-in-out_infinite]")}
        style={{
          background: state === "thinking"
            ? "conic-gradient(from 0deg, rgb(var(--fg)), rgb(var(--fg) / .25), rgb(var(--fg) / .7), rgb(var(--fg)))"
            : "radial-gradient(circle at 35% 30%, rgb(var(--fg) / .55), rgb(var(--fg)) 60%)",
          transform: `scale(${scale})`,
          transition: "transform 90ms linear",
          boxShadow: "0 20px 60px -20px rgb(var(--fg) / .45)",
          opacity: muted && state === "listening" ? 0.35 : 1,
        }}
      />
      {state === "thinking" && <span className="absolute inset-[14%] rounded-full bg-bg/90 blur-[2px]" />}
    </div>
  );
}

export function VoiceMode({ state, level = 0, muted = false, onMutedChange, onEnd, caption, captions = true, onCaptionsChange, className }: VoiceModeProps) {
  return (
    <div className={cn("flex w-full flex-col items-center justify-between gap-8 rounded-2xl border border-border bg-bg px-6 py-8", className)}>
      <p className="text-sm font-medium text-fg-muted" aria-live="polite">
        {muted && state === "listening" ? "You're muted" : label[state]}
      </p>
      <VoiceOrb state={state} level={level} muted={muted} />
      <p className={cn("min-h-[3rem] max-w-sm text-balance text-center text-md text-fg transition-opacity", captions && caption ? "opacity-100" : "opacity-0")}>
        {captions ? caption : ""}
      </p>
      <div className="flex items-center gap-3">
        {onCaptionsChange && (
          <button type="button" onClick={() => onCaptionsChange(!captions)} aria-pressed={captions} aria-label="Captions"
            className={cn("grid size-12 place-items-center rounded-full border transition-colors [&_svg]:size-5", captions ? "border-border bg-surface-2 text-fg" : "border-border text-fg-muted hover:bg-surface")}>
            <Captions />
          </button>
        )}
        <button type="button" onClick={() => onMutedChange?.(!muted)} aria-pressed={muted} aria-label={muted ? "Unmute" : "Mute"}
          className={cn("grid size-14 place-items-center rounded-full border transition-colors [&_svg]:size-5", muted ? "border-transparent bg-fg text-bg" : "border-border bg-bg text-fg hover:bg-surface")}>
          {muted ? <MicOff /> : <Mic />}
        </button>
        <button type="button" onClick={onEnd} aria-label="End voice chat" className="grid size-14 place-items-center rounded-full bg-danger text-white transition-opacity hover:opacity-90 [&_svg]:size-5">
          <X />
        </button>
      </div>
    </div>
  );
}

