"use client";

import * as React from "react";
import { ArrowLeft, ArrowRight, ExternalLink, Monitor, RotateCw, Smartphone, Tablet, Terminal } from "lucide-react";
import { cn } from "../../lib/cn";
import { Tooltip } from "../ui/tooltip";

/**
 * WebPreview
 * Browser frame for AI-generated sites and apps (v0 / Lovable style).
 * URL bar, reload, device widths, open in new tab, and an optional console drawer for logs.
 */
export interface ConsoleLog { level: "log" | "warn" | "error"; message: string; time?: string }

export interface WebPreviewProps {
  url: string;
  /** Render an iframe to `url` (default) or pass your own content */
  children?: React.ReactNode;
  logs?: ConsoleLog[];
  onUrlChange?: (url: string) => void;
  height?: number;
  className?: string;
}

const widths = { desktop: "100%", tablet: "768px", mobile: "390px" } as const;

export function WebPreview({ url, children, logs, onUrlChange, height = 480, className }: WebPreviewProps) {
  const [draft, setDraft] = React.useState(url);
  const [device, setDevice] = React.useState<keyof typeof widths>("desktop");
  const [key, setKey] = React.useState(0);
  const [consoleOpen, setConsoleOpen] = React.useState(false);
  React.useEffect(() => setDraft(url), [url]);
  const btn = "grid size-7 place-items-center rounded-sm text-fg-muted transition-colors hover:bg-surface-2 hover:text-fg disabled:opacity-40";
  const errors = logs?.filter((l) => l.level === "error").length ?? 0;

  return (
    <div className={cn("flex flex-col overflow-hidden rounded-xl border border-border bg-bg shadow-sm", className)}>
      <div className="flex h-11 items-center gap-1 border-b border-border px-2">
        <button type="button" className={btn} aria-label="Back" onClick={() => history.back()}><ArrowLeft className="size-4" /></button>
        <button type="button" className={btn} aria-label="Forward" onClick={() => history.forward()}><ArrowRight className="size-4" /></button>
        <button type="button" className={btn} aria-label="Reload" onClick={() => setKey((k) => k + 1)}><RotateCw className="size-3.5" /></button>
        <form className="mx-1 min-w-0 flex-1" onSubmit={(e) => { e.preventDefault(); onUrlChange?.(draft); }}>
          <input value={draft} onChange={(e) => setDraft(e.target.value)} aria-label="URL" spellCheck={false} className="h-7 w-full rounded-sm bg-surface-2 px-3 font-mono text-xs text-fg-muted focus:bg-bg focus:text-fg focus:outline-none focus:ring-1 focus:ring-border-strong" />
        </form>
        <div className="hidden items-center sm:flex" role="group" aria-label="Device width">
          {([["desktop", Monitor], ["tablet", Tablet], ["mobile", Smartphone]] as const).map(([d, Icon]) => (
            <Tooltip key={d} label={d[0].toUpperCase() + d.slice(1)} side="bottom">
              <button type="button" aria-pressed={device === d} aria-label={d} onClick={() => setDevice(d)} className={cn(btn, device === d && "bg-surface-2 text-fg")}><Icon className="size-3.5" /></button>
            </Tooltip>
          ))}
        </div>
        <Tooltip label="Open in new tab" side="bottom"><a href={url} target="_blank" rel="noreferrer" className={btn} aria-label="Open in new tab"><ExternalLink className="size-3.5" /></a></Tooltip>
      </div>
      <div className="relative flex justify-center bg-surface" style={{ height }}>
        <div className="h-full transition-[width] duration-300" style={{ width: widths[device], maxWidth: "100%" }}>
          {children ? <div key={key} className="h-full overflow-auto bg-bg">{children}</div> : <iframe key={key} src={url} title="Preview" className="size-full border-0 bg-white" sandbox="allow-scripts allow-same-origin allow-forms" />}
        </div>
      </div>
      {logs && (
        <div className="border-t border-border">
          <button type="button" aria-expanded={consoleOpen} onClick={() => setConsoleOpen((o) => !o)} className="flex h-9 w-full items-center gap-2 px-3 text-xs font-medium text-fg-muted hover:text-fg">
            <Terminal className="size-3.5" />Console
            {errors > 0 && <span className="rounded-full bg-danger/10 px-1.5 text-2xs text-danger">{errors} error{errors > 1 && "s"}</span>}
          </button>
          {consoleOpen && (
            <ul className="max-h-40 overflow-auto border-t border-border font-mono text-xs">
              {logs.map((l, i) => (
                <li key={i} className={cn("flex gap-3 border-b border-border px-3 py-1.5 last:border-0", l.level === "error" && "bg-danger/5 text-danger", l.level === "warn" && "bg-warning/5 text-warning", l.level === "log" && "text-fg-muted")}>
                  {l.time && <span className="shrink-0 text-fg-subtle">{l.time}</span>}
                  <span className="min-w-0 break-all">{l.message}</span>
                </li>
              ))}
            </ul>
          )}
        </div>
      )}
    </div>
  );
}

components/ui/accordion.tsx.source:
"use client";

import * as React from "react";
import { ChevronDown } from "lucide-react";
import { cn } from "../../lib/cn";

/**
 * Accordion
 * Stacked sections that expand in place — FAQs, settings groups, long docs.
 * type="single" keeps one open at a time; "multiple" lets several open. Height animates smoothly.
 * Keyboard: ↑ ↓ move between headers, Home/End jump, Enter/Space toggle.
 */
export interface AccordionItem { value: string; title: React.ReactNode; content: React.ReactNode; icon?: React.ReactNode; disabled?: boolean }

export interface AccordionProps {
  items: AccordionItem[];
  type?: "single" | "multiple";
  defaultValue?: string[];
  value?: string[];
  onValueChange?: (v: string[]) => void;
  variant?: "default" | "card";
  className?: string;
}

export function Accordion({ items, type = "single", defaultValue = [], value, onValueChange, variant = "default", className }: AccordionProps) {
  const [inner, setInner] = React.useState<string[]>(defaultValue);
  const open = value ?? inner;
  const id = React.useId();
  const refs = React.useRef<(HTMLButtonElement | null)[]>([]);
  const toggle = (v: string) => {
    const next = open.includes(v) ? open.filter((x) => x !== v) : type === "single" ? [v] : [...open, v];
    setInner(next); onValueChange?.(next);
  };
  return (
    <div
      className={cn(variant === "card" ? "space-y-2" : "divide-y divide-border border-y border-border", className)}
      onKeyDown={(e) => {
        const i = refs.current.findIndex((r) => r === document.activeElement);
        if (i < 0) return;
        const go = (n: number) => { e.preventDefault(); refs.current[(n + items.length) % items.length]?.focus(); };
        if (e.key === "ArrowDown") go(i + 1);
        if (e.key === "ArrowUp") go(i - 1);
        if (e.key === "Home") go(0);
        if (e.key === "End") go(items.length - 1);
      }}
    >
      {items.map((it, i) => {
        const isOpen = open.includes(it.value);
        return (
          <div key={it.value} className={cn(variant === "card" && "rounded-lg border border-border bg-bg px-4")}>
            <h3>
              <button
                ref={(el) => { refs.current[i] = el; }}
                type="button"
                id={`${id}-h-${i}`}
                aria-expanded={isOpen}
                aria-controls={`${id}-p-${i}`}
                disabled={it.disabled}
                onClick={() => toggle(it.value)}
                className="flex w-full items-center gap-3 py-4 text-left text-base font-medium text-fg transition-colors hover:text-fg/80 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-fg/20 disabled:opacity-40 [&_svg]:size-4"
              >
                {it.icon && <span className="text-fg-muted">{it.icon}</span>}
                <span className="flex-1">{it.title}</span>
                <ChevronDown className={cn("shrink-0 text-fg-subtle transition-transform duration-200", isOpen && "rotate-180")} />
              </button>
            </h3>
            <div id={`${id}-p-${i}`} role="region" aria-labelledby={`${id}-h-${i}`} className={cn("grid transition-[grid-template-rows] duration-200 ease-out", isOpen ? "grid-rows-[1fr]" : "grid-rows-[0fr]")}>
              <div className={cn("overflow-hidden transition-[visibility] duration-200", !isOpen && "invisible")} aria-hidden={!isOpen || undefined}>
                <div className="pb-4 text-base text-fg-muted">{it.content}</div>
              </div>
            </div>
          </div>
        );
      })}
    </div>
  );
}

components/ui/alert-dialog.tsx.source:
"use client";

import * as React from "react";
import { AlertTriangle } from "lucide-react";
import { cn } from "../../lib/cn";
import { Dialog } from "./dialog";
import { Button } from "./button";

/**
 * AlertDialog
 * Interrupts for irreversible actions only (delete workspace, revoke key). Can't be dismissed by
 * clicking outside. Cancel is focused first so Enter never destroys anything by accident.
 * For reversible actions, act immediately and offer Undo in a toast instead.
 * `confirmText` requires typing a word (e.g. the project name) for the most dangerous actions.
 */
export interface AlertDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title: string;
  description?: React.ReactNode;
  confirmLabel?: string;
  cancelLabel?: string;
  onConfirm: () => void | Promise<void>;
  destructive?: boolean;
  confirmText?: string;
}

export function AlertDialog({ open, onOpenChange, title, description, confirmLabel = "Continue", cancelLabel = "Cancel", onConfirm, destructive = true, confirmText }: AlertDialogProps) {
  const [typed, setTyped] = React.useState("");
  const [busy, setBusy] = React.useState(false);
  React.useEffect(() => { if (open) { setTyped(""); setBusy(false); } }, [open]);
  const blocked = !!confirmText && typed !== confirmText;
  const confirm = async () => { setBusy(true); try { await onConfirm(); onOpenChange(false); } finally { setBusy(false); } };
  return (
    <Dialog open={open} onClose={() => !busy && onOpenChange(false)} labelledBy="pl-alert-title" className="max-w-md" showClose={false} dismissOnBackdrop={false}>
      <div role="alertdialog" aria-labelledby="pl-alert-title" className="p-6">
        <div className="flex gap-4">
          {destructive && <span className="grid size-10 shrink-0 place-items-center rounded-full bg-danger/10 text-danger"><AlertTriangle className="size-5" /></span>}
          <div className="min-w-0">
            <h2 id="pl-alert-title" className="text-xl font-semibold text-fg">{title}</h2>
            {description && <div className="mt-1 text-base text-fg-muted">{description}</div>}
          </div>
        </div>
        {confirmText && (
          <label className={cn("mt-6 block text-sm text-fg-muted", destructive && "sm:pl-14")}>
            Type <span className="font-mono font-medium text-fg">{confirmText}</span> to confirm
            <input value={typed} onChange={(e) => setTyped(e.target.value)} autoComplete="off" spellCheck={false} className="mt-2 h-9 w-full rounded-md border border-border bg-bg px-3 font-mono text-base text-fg shadow-xs focus:border-border-strong focus:outline-none focus:ring-4 focus:ring-fg/5" />
          </label>
        )}
        <div className="mt-6 flex flex-col-reverse gap-2 sm:flex-row sm:justify-end">
          <Button variant="outline" data-autofocus onClick={() => onOpenChange(false)} disabled={busy}>{cancelLabel}</Button>
          <Button variant={destructive ? "danger" : "primary"} onClick={confirm} disabled={blocked} loading={busy}>{confirmLabel}</Button>
        </div>
      </div>
    </Dialog>
  );
}

components/ui/alert.tsx.source:
"use client";

import * as React from "react";
import { AlertTriangle, CheckCircle2, Info, XCircle, X } from "lucide-react";
import { cn } from "../../lib/cn";

/**
 * Alert
 * Inline, persistent message inside a page or form. For AI-specific failures
 * (rate limits, credits, offline) use StatusBanner, which ships the copy and actions.
 */
export type AlertTone = "info" | "success" | "warning" | "danger" | "neutral";

export interface AlertProps {
  tone?: AlertTone;
  title?: React.ReactNode;
  children?: React.ReactNode;
  icon?: React.ReactNode | false;
  action?: React.ReactNode;
  onDismiss?: () => void;
  className?: string;
}

const tones: Record<AlertTone, { cls: string; Icon: typeof Info }> = {
  info: { cls: "border-info/25 bg-info/[0.04] [&_[data-ic]]:text-info", Icon: Info },
  success: { cls: "border-success/25 bg-success/[0.04] [&_[data-ic]]:text-success", Icon: CheckCircle2 },
  warning: { cls: "border-warning/30 bg-warning/[0.05] [&_[data-ic]]:text-warning", Icon: AlertTriangle },
  danger: { cls: "border-danger/25 bg-danger/[0.04] [&_[data-ic]]:text-danger", Icon: XCircle },
  neutral: { cls: "border-border bg-surface [&_[data-ic]]:text-fg-muted", Icon: Info },
};

export function Alert({ tone = "neutral", title, children, icon, action, onDismiss, className }: AlertProps) {
  const t = tones[tone];
  return (
    <div role={tone === "danger" ? "alert" : "status"} className={cn("flex items-start gap-3 rounded-lg border p-4 text-sm", t.cls, className)}>
      {icon !== false && <span data-ic className="mt-0.5 shrink-0 [&_svg]:size-4">{icon ?? <t.Icon />}</span>}
      <div className="min-w-0 flex-1">
        {title && <p className="font-medium text-fg">{title}</p>}
        {children && <div className={cn("text-fg-muted", title && "mt-0.5")}>{children}</div>}
      </div>
      {action && <div className="shrink-0">{action}</div>}
      {onDismiss && <button type="button" onClick={onDismiss} aria-label="Dismiss" className="-m-1 grid size-7 shrink-0 place-items-center rounded-sm text-fg-subtle hover:bg-surface-2 hover:text-fg"><X className="size-4" /></button>}
    </div>
  );
}

components/ui/avatar.tsx.source:
"use client";

import * as React from "react";
import { cn } from "../../lib/cn";

/**
 * Avatar & AvatarStack
 * Image with initials fallback (also used when the image fails). Optional presence dot.
 * AvatarStack overlaps avatars and collapses the rest into "+N".
 */
export interface AvatarProps {
  src?: string;
  /** Initials or an icon */
  fallback: React.ReactNode;
  alt?: string;
  size?: "xs" | "sm" | "md" | "lg";
  status?: "online" | "busy" | "offline";
  shape?: "circle" | "square";
  className?: string;
}

const sizes = { xs: "size-6 text-2xs", sm: "size-7 text-xs", md: "size-8 text-xs", lg: "size-10 text-sm" };

export function Avatar({ src, fallback, alt = "", size = "md", status, shape = "circle", className }: AvatarProps) {
  const [err, setErr] = React.useState(false);
  return (
    <span className={cn("relative inline-flex shrink-0", className)}>
      <span className={cn("inline-grid place-items-center overflow-hidden bg-surface-2 font-medium text-fg-muted ring-1 ring-border", sizes[size], shape === "circle" ? "rounded-full" : "rounded-md")}>
        {src && !err ? <img src={src} alt={alt} onError={() => setErr(true)} className="size-full object-cover" /> : fallback}
      </span>
      {status && (
        <span aria-label={status} className={cn("absolute bottom-0 right-0 size-2.5 rounded-full ring-2 ring-bg", status === "online" ? "bg-success" : status === "busy" ? "bg-warning" : "bg-fg-subtle")} />
      )}
    </span>
  );
}

export function AvatarStack({ avatars, max = 4, size = "md", className }: { avatars: Omit<AvatarProps, "size">[]; max?: number; size?: AvatarProps["size"]; className?: string }) {
  const shown = avatars.slice(0, max);
  const rest = avatars.length - shown.length;
  return (
    <div className={cn("flex items-center -space-x-2", className)}>
      {shown.map((a, i) => <Avatar key={i} {...a} size={size} className="rounded-full ring-2 ring-bg" />)}
      {rest > 0 && <span className={cn("relative inline-grid place-items-center rounded-full bg-surface-2 font-medium text-fg-muted ring-2 ring-bg", sizes[size ?? "md"])}>+{rest}</span>}
    </div>
  );
}

