"use client";

import * as React from "react";
import { Check, Minus } from "lucide-react";
import { cn } from "../../lib/cn";

/**
 * Checkbox
 * Native input underneath (forms, keyboard and screen readers just work) with a custom box.
 * Supports `indeterminate` for "select all" rows. Pass `label` / `description` for a full row.
 */
export interface CheckboxProps extends Omit<React.InputHTMLAttributes<HTMLInputElement>, "type" | "onChange"> {
  checked?: boolean;
  defaultChecked?: boolean;
  onCheckedChange?: (checked: boolean) => void;
  indeterminate?: boolean;
  label?: React.ReactNode;
  description?: React.ReactNode;
}

export const Checkbox = React.forwardRef<HTMLInputElement, CheckboxProps>(({ checked, defaultChecked, onCheckedChange, indeterminate, label, description, className, disabled, id, ...p }, ref) => {
  const inner = React.useRef<HTMLInputElement>(null);
  React.useImperativeHandle(ref, () => inner.current!);
  React.useEffect(() => { if (inner.current) inner.current.indeterminate = !!indeterminate; }, [indeterminate]);
  const auto = React.useId();
  const cid = id ?? auto;
  const box = (
    <span className="relative inline-grid size-4 shrink-0 place-items-center">
      <input
        ref={inner}
        id={cid}
        type="checkbox"
        checked={checked}
        defaultChecked={defaultChecked}
        disabled={disabled}
        onChange={(e) => onCheckedChange?.(e.target.checked)}
        className="peer absolute inset-0 cursor-pointer appearance-none rounded-xs border border-border-strong bg-bg shadow-xs transition-colors checked:border-accent checked:bg-accent indeterminate:border-accent indeterminate:bg-accent focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-fg/20 focus-visible:ring-offset-2 focus-visible:ring-offset-bg disabled:cursor-not-allowed disabled:opacity-50 aria-[invalid=true]:border-danger"
        {...p}
      />
      <Check className="pointer-events-none relative size-3 text-accent-fg opacity-0 peer-checked:opacity-100 peer-indeterminate:opacity-0" strokeWidth={3} />
      <Minus className="pointer-events-none absolute size-3 text-accent-fg opacity-0 peer-indeterminate:opacity-100" strokeWidth={3} />
    </span>
  );
  if (!label) return <span className={className}>{box}</span>;
  return (
    <label htmlFor={cid} className={cn("flex cursor-pointer items-start gap-3", disabled && "cursor-not-allowed opacity-60", className)}>
      <span className="mt-0.5">{box}</span>
      <span className="space-y-0.5">
        <span className="block text-sm font-medium text-fg">{label}</span>
        {description && <span className="block text-xs text-fg-muted">{description}</span>}
      </span>
    </label>
  );
});
Checkbox.displayName = "Checkbox";

components/ui/collapsible.tsx.source:
"use client";

import * as React from "react";
import { ChevronDown } from "lucide-react";
import { cn } from "../../lib/cn";

/**
 * Collapsible
 * Show / hide one region with an animated height. The building block behind Reasoning, Tool and Sources.
 * Pass `trigger` for the default chevron button, or render your own via `renderTrigger`.
 */
export interface CollapsibleProps {
  trigger?: React.ReactNode;
  renderTrigger?: (props: { open: boolean; toggle: () => void; "aria-expanded": boolean; "aria-controls": string }) => React.ReactNode;
  children: React.ReactNode;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  className?: string;
}

export function Collapsible({ trigger, renderTrigger, children, open, defaultOpen, onOpenChange, className }: CollapsibleProps) {
  const [inner, setInner] = React.useState(!!defaultOpen);
  const isOpen = open ?? inner;
  const id = React.useId();
  const toggle = () => { setInner(!isOpen); onOpenChange?.(!isOpen); };
  return (
    <div className={className}>
      {renderTrigger ? renderTrigger({ open: isOpen, toggle, "aria-expanded": isOpen, "aria-controls": id }) : (
        <button type="button" aria-expanded={isOpen} aria-controls={id} onClick={toggle} className="inline-flex h-8 items-center gap-2 rounded-sm text-sm font-medium text-fg-muted transition-colors hover:text-fg focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-fg/20">
          {trigger}<ChevronDown className={cn("size-4 transition-transform duration-200", isOpen && "rotate-180")} />
        </button>
      )}
      <div id={id} className={cn("grid transition-[grid-template-rows] duration-200 ease-out", isOpen ? "grid-rows-[1fr]" : "grid-rows-[0fr]")}>
        <div className={cn("overflow-hidden transition-[visibility] duration-200", !isOpen && "invisible")} aria-hidden={!isOpen || undefined}>{children}</div>
      </div>
    </div>
  );
}

components/ui/combobox.tsx.source:
"use client";

import * as React from "react";
import { Check, ChevronsUpDown, Plus, X } from "lucide-react";
import { cn } from "../../lib/cn";
import { useFloating, useOutside, Portal, floatingPanel } from "../../lib/floating";

/**
 * Combobox
 * Searchable select for long lists (models, users, tags). Single or multiple selection.
 * Multi mode shows selections as removable chips; `onCreate` lets users add a new option.
 * The input stays focused the whole time — arrows move, Enter picks, Backspace removes the last chip.
 */
export interface ComboboxOption { value: string; label: string; description?: string; icon?: React.ReactNode }

export interface ComboboxProps {
  options: ComboboxOption[];
  multiple?: boolean;
  value?: string | string[];
  onValueChange?: (value: any) => void;
  placeholder?: string;
  emptyText?: string;
  onCreate?: (label: string) => void;
  disabled?: boolean;
  className?: string;
  "aria-label"?: string;
}

export function Combobox({ options, multiple, value, onValueChange, placeholder = "Search…", emptyText = "No results", onCreate, disabled, className, ...aria }: ComboboxProps) {
  const [inner, setInner] = React.useState<string | string[]>(multiple ? [] : "");
  const cur = value ?? inner;
  const selected = multiple ? (cur as string[]) : cur ? [cur as string] : [];
  const [q, setQ] = React.useState("");
  const [open, setOpen] = React.useState(false);
  const [active, setActive] = React.useState(0);
  const input = React.useRef<HTMLInputElement>(null);
  const fl = useFloating({ open, side: "bottom", align: "start", offset: 4, matchWidth: true });
  const listId = React.useId();
  useOutside(open, () => setOpen(false), [fl.anchor, fl.floating]);

  const filtered = options.filter((o) => o.label.toLowerCase().includes(q.toLowerCase()));
  const canCreate = onCreate && q.trim() && !options.some((o) => o.label.toLowerCase() === q.trim().toLowerCase());
  const total = filtered.length + (canCreate ? 1 : 0);
  const set = (v: string | string[]) => { setInner(v); onValueChange?.(v); };
  const toggle = (v: string) => {
    if (multiple) set(selected.includes(v) ? selected.filter((x) => x !== v) : [...selected, v]);
    else { set(v); setOpen(false); }
    setQ("");
  };
  const choose = (i: number) => {
    if (i < filtered.length) toggle(filtered[i].value);
    else if (canCreate) { onCreate!(q.trim()); setQ(""); }
  };
  const label = (v: string) => options.find((o) => o.value === v)?.label ?? v;

  return (
    <>
      <div
        ref={(el) => { fl.anchor.current = el; }}
        onClick={() => { input.current?.focus(); setOpen(true); }}
        className={cn(
          "flex min-h-9 w-full cursor-text flex-wrap items-center gap-1 rounded-md border border-border bg-bg py-1 pl-2 pr-1 shadow-xs transition-[border-color,box-shadow] focus-within:border-border-strong focus-within:ring-4 focus-within:ring-fg/5",
          disabled && "pointer-events-none opacity-50",
          className
        )}
      >
        {multiple && selected.map((v) => (
          <span key={v} className="inline-flex h-6 items-center gap-1 rounded-sm bg-surface-2 pl-2 pr-1 text-sm text-fg">
            {label(v)}
            <button type="button" aria-label={`Remove ${label(v)}`} onClick={(e) => { e.stopPropagation(); toggle(v); }} className="grid size-4 place-items-center rounded-xs text-fg-subtle hover:bg-border hover:text-fg"><X className="size-3" /></button>
          </span>
        ))}
        <input
          ref={input}
          role="combobox"
          aria-expanded={open}
          aria-controls={listId}
          aria-autocomplete="list"
          aria-activedescendant={open && total ? `${listId}-${active}` : undefined}
          value={q}
          disabled={disabled}
          placeholder={selected.length && !multiple ? label(selected[0]) : multiple && selected.length ? "" : placeholder}
          onChange={(e) => { setQ(e.target.value); setActive(0); setOpen(true); }}
          onFocus={() => setOpen(true)}
          onKeyDown={(e) => {
            if (e.key === "ArrowDown") { e.preventDefault(); setOpen(true); setActive((a) => Math.min(a + 1, total - 1)); }
            else if (e.key === "ArrowUp") { e.preventDefault(); setActive((a) => Math.max(a - 1, 0)); }
            else if (e.key === "Enter") { e.preventDefault(); if (open) choose(active); }
            else if (e.key === "Escape") setOpen(false);
            else if (e.key === "Backspace" && !q && multiple && selected.length) toggle(selected[selected.length - 1]);
          }}
          className={cn("h-7 min-w-16 flex-1 bg-transparent px-1 text-base text-fg focus:outline-none", !multiple && selected.length ? "placeholder:text-fg" : "placeholder:text-fg-subtle")}
          {...aria}
        />
        <ChevronsUpDown className="mr-1 size-4 shrink-0 text-fg-subtle" aria-hidden />
      </div>
      {open && (
        <Portal>
          <ul id={listId} role="listbox" aria-multiselectable={multiple || undefined} ref={(el) => { fl.floating.current = el; }} style={{ ...fl.style, animation: "pl-pop .12s var(--ease-out)" }} className={cn(floatingPanel, "max-h-72 overflow-y-auto p-1")} onMouseDown={(e) => e.preventDefault()}>
            {filtered.map((o, i) => (
              <li key={o.value} id={`${listId}-${i}`} role="option" aria-selected={selected.includes(o.value)} onMouseEnter={() => setActive(i)} onClick={() => choose(i)}
                className={cn("flex cursor-default items-center gap-2 rounded-sm px-2 py-1.5 text-sm [&_svg]:size-4", i === active && "bg-surface-2")}>
                {multiple ? (
                  <span className={cn("grid size-4 shrink-0 place-items-center rounded-xs border", selected.includes(o.value) ? "border-accent bg-accent text-accent-fg" : "border-border-strong")}>{selected.includes(o.value) && <Check className="!size-3" strokeWidth={3} />}</span>
                ) : o.icon && <span className="text-fg-muted">{o.icon}</span>}
                <span className="min-w-0 flex-1"><span className="block truncate text-fg">{o.label}</span>{o.description && <span className="block truncate text-xs text-fg-subtle">{o.description}</span>}</span>
                {!multiple && selected.includes(o.value) && <Check className="text-fg" />}
              </li>
            ))}
            {canCreate && (
              <li id={`${listId}-${filtered.length}`} role="option" aria-selected={false} onMouseEnter={() => setActive(filtered.length)} onClick={() => choose(filtered.length)}
                className={cn("flex cursor-default items-center gap-2 rounded-sm px-2 py-1.5 text-sm text-fg-muted", active === filtered.length && "bg-surface-2 text-fg")}>
                <Plus className="size-4" />Create "{q.trim()}"
              </li>
            )}
            {!total && <li className="px-2 py-6 text-center text-sm text-fg-subtle">{emptyText}</li>}
          </ul>
        </Portal>
      )}
    </>
  );
}

components/ui/data-table.tsx.source:
"use client";

import * as React from "react";
import { ArrowDown, ArrowUp, ChevronLeft, ChevronRight, ChevronsUpDown, Columns3, ListFilter, MoreHorizontal, Search, X } from "lucide-react";
import { cn } from "../../lib/cn";
import { Checkbox } from "./checkbox";
import { DropdownMenu, type MenuItem } from "./menu";
import { Button } from "./button";

/**
 * DataTable
 * A self-contained table card: search, faceted filters, sorting, row selection with bulk actions,
 * row action menus, column visibility, rows-per-page and pagination, sticky header,
 * loading skeletons and empty states — no table library required.
 *
 * Define columns once; each can provide a custom `cell`, a `value` for sorting/search/filtering,
 * alignment, width, and whether users can hide it.
 */
export interface Column<T> {
  id: string;
  header: string;
  cell: (row: T) => React.ReactNode;
  /** Value used for sorting, search and filters (defaults to row[id]) */
  value?: (row: T) => string | number;
  sortable?: boolean;
  align?: "left" | "right" | "center";
  width?: number | string;
  /** Can be toggled from the Columns menu */
  hideable?: boolean;
  /** Start hidden */
  defaultHidden?: boolean;
}

export interface Facet { id: string; label: string; options: { value: string; label: string }[] }

export interface DataTableProps<T> {
  data: T[];
  columns: Column<T>[];
  rowId: (row: T) => string;
  searchable?: boolean;
  searchPlaceholder?: string;
  /** Faceted filters, e.g. Status → Completed / Running / Failed. `id` must match a column id. */
  filters?: Facet[];
  selectable?: boolean;
  /** Toolbar actions shown while rows are selected */
  bulkActions?: (selected: T[], clear: () => void) => React.ReactNode;
  /** Per-row "…" menu */
  rowActions?: (row: T) => MenuItem[];
  pageSize?: number;
  pageSizeOptions?: number[];
  loading?: boolean;
  empty?: React.ReactNode;
  onRowClick?: (row: T) => void;
  /** Extra toolbar content, right side */
  toolbar?: React.ReactNode;
  maxHeight?: number;
  density?: "compact" | "default";
  className?: string;
}

export function DataTable<T>({
  data, columns, rowId, searchable = true, searchPlaceholder = "Search…", filters = [], selectable, bulkActions, rowActions,
  pageSize: initialPageSize = 10, pageSizeOptions = [5, 10, 20, 50], loading, empty, onRowClick, toolbar, maxHeight, density = "default", className,
}: DataTableProps<T>) {
  const [q, setQ] = React.useState("");
  const [sort, setSort] = React.useState<{ id: string; dir: "asc" | "desc" } | null>(null);
  const [page, setPage] = React.useState(1);
  const [pageSize, setPageSize] = React.useState(initialPageSize);
  const [sel, setSel] = React.useState<Set<string>>(new Set());
  const [hidden, setHidden] = React.useState<Set<string>>(() => new Set(columns.filter((c) => c.defaultHidden).map((c) => c.id)));
  const [facets, setFacets] = React.useState<Record<string, string[]>>({});

  const val = React.useCallback((c: Column<T>, r: T) => (c.value ? c.value(r) : ((r as any)[c.id] as string | number)), []);
  const cols = columns.filter((c) => !hidden.has(c.id));
  const activeFacets = Object.values(facets).reduce((n, v) => n + v.length, 0);

  const rows = React.useMemo(() => {
    let out = data;
    for (const [id, vals] of Object.entries(facets)) {
      if (!vals.length) continue;
      const c = columns.find((x) => x.id === id);
      if (c) out = out.filter((r) => vals.includes(String(val(c, r))));
    }
    if (q.trim()) {
      const s = q.trim().toLowerCase();
      out = out.filter((r) => columns.some((c) => String(val(c, r) ?? "").toLowerCase().includes(s)));
    }
    if (sort) {
      const c = columns.find((x) => x.id === sort.id);
      if (c) out = [...out].sort((a, b) => {
        const x = val(c, a), y = val(c, b);
        const d = typeof x === "number" && typeof y === "number" ? x - y : String(x).localeCompare(String(y), undefined, { numeric: true });
        return sort.dir === "asc" ? d : -d;
      });
    }
    return out;
  }, [data, q, sort, columns, facets, val]);

  const pages = Math.max(1, Math.ceil(rows.length / pageSize));
  const cur = Math.min(page, pages);
  const view = rows.slice((cur - 1) * pageSize, cur * pageSize);
  const allOnPage = view.length > 0 && view.every((r) => sel.has(rowId(r)));
  const someOnPage = view.some((r) => sel.has(rowId(r)));
  const selectedRows = data.filter((r) => sel.has(rowId(r)));
  const clearSel = () => setSel(new Set());
  const toggleSort = (id: string) => setSort((s) => (s?.id !== id ? { id, dir: "asc" } : s.dir === "asc" ? { id, dir: "desc" } : null));
  const reset = () => { setQ(""); setFacets({}); setPage(1); };
  const rowH = density === "compact" ? "h-10" : "h-12";
  const colCount = cols.length + (selectable ? 1 : 0) + (rowActions ? 1 : 0);
  const alignCls = (a?: string) => (a === "right" ? "text-right" : a === "center" ? "text-center" : "text-left");

  return (
    <div className={cn("flex min-w-0 flex-col overflow-hidden rounded-xl border border-border bg-bg shadow-xs", className)}>
      {/* Toolbar — swaps to bulk actions while rows are selected, same height so nothing jumps */}
      <div className="flex min-h-14 flex-wrap items-center gap-2 border-b border-border px-3 py-2.5">
        {selectable && sel.size > 0 ? (
          <div className="flex flex-1 flex-wrap items-center gap-2" style={{ animation: "pl-in .15s ease-out" }}>
            <span className="inline-flex h-8 items-center gap-2 rounded-md bg-surface-2 pl-3 pr-1 text-sm font-medium tabular-nums text-fg">
              {sel.size} selected
              <button type="button" onClick={clearSel} aria-label="Clear selection" className="grid size-6 place-items-center rounded-sm text-fg-muted hover:bg-border hover:text-fg"><X className="size-3.5" /></button>
            </span>
            {bulkActions?.(selectedRows, clearSel)}
          </div>
        ) : (
          <>
            {searchable && (
              <label className="flex h-8 w-full min-w-40 items-center gap-2 rounded-md border border-border bg-bg px-2.5 text-fg-subtle shadow-xs transition-[border-color,box-shadow] focus-within:border-border-strong focus-within:ring-4 focus-within:ring-fg/5 sm:w-64">
                <Search className="size-4 shrink-0" />
                <input value={q} onChange={(e) => { setQ(e.target.value); setPage(1); }} placeholder={searchPlaceholder} aria-label="Search table" className="min-w-0 flex-1 bg-transparent text-sm text-fg placeholder:text-fg-subtle focus:outline-none" />
                {q && <button type="button" onClick={() => setQ("")} aria-label="Clear search" className="grid size-5 place-items-center rounded-xs text-fg-subtle hover:text-fg"><X className="size-3.5" /></button>}
              </label>
            )}
            {filters.map((f) => {
              const picked = facets[f.id] ?? [];
              return (
                <DropdownMenu
                  key={f.id}
                  trigger={
                    <Button variant="outline" size="sm" className={cn("border-dashed", picked.length && "border-solid")}>
                      <ListFilter />{f.label}
                      {picked.length > 0 && <span className="ml-0.5 rounded-xs bg-surface-2 px-1.5 text-xs tabular-nums text-fg">{picked.length}</span>}
                    </Button>
                  }
                  items={[
                    ...f.options.map((o) => ({
                      type: "checkbox" as const,
                      label: o.label,
                      hint: String(data.filter((r) => { const c = columns.find((x) => x.id === f.id); return c && String(val(c, r)) === o.value; }).length),
                      checked: picked.includes(o.value),
                      onCheckedChange: (v: boolean) => { setFacets((s) => ({ ...s, [f.id]: v ? [...picked, o.value] : picked.filter((x) => x !== o.value) })); setPage(1); },
                    })),
                    ...(picked.length ? [{ type: "separator" as const }, { label: "Clear filter", onSelect: () => setFacets((s) => ({ ...s, [f.id]: [] })) }] : []),
                  ]}
                />
              );
            })}
            {(activeFacets > 0 || q) && <Button variant="ghost" size="sm" onClick={reset}>Reset<X /></Button>}
          </>
        )}
        <div className="ml-auto flex items-center gap-2">
          {toolbar}
          {columns.some((c) => c.hideable) && (
            <DropdownMenu
              align="end"
              trigger={<Button variant="outline" size="sm"><Columns3 /><span className="hidden sm:inline">Columns</span></Button>}
              items={[{ type: "label", label: "Show columns" }, ...columns.filter((c) => c.hideable).map((c) => ({ type: "checkbox" as const, label: c.header, checked: !hidden.has(c.id), onCheckedChange: (v: boolean) => setHidden((h) => { const n = new Set(h); v ? n.delete(c.id) : n.add(c.id); return n; }) }))]}
            />
          )}
        </div>
      </div>

      {/* Table */}
      <div className="min-w-0 overflow-auto" style={{ maxHeight }}>
        <table className="w-full border-separate border-spacing-0 text-left text-sm" aria-busy={loading || undefined} aria-rowcount={rows.length}>
          <thead className="sticky top-0 z-10">
            <tr className="bg-surface text-xs font-medium text-fg-muted">
              {selectable && (
                <th scope="col" className="h-10 w-12 border-b border-border bg-surface pl-4 pr-2">
                  <span className="flex items-center"><Checkbox aria-label="Select all on this page" checked={allOnPage} indeterminate={!allOnPage && someOnPage} onCheckedChange={(v) => setSel((s) => { const n = new Set(s); view.forEach((r) => (v ? n.add(rowId(r)) : n.delete(rowId(r)))); return n; })} /></span>
                </th>
              )}
              {cols.map((c) => {
                const active = sort?.id === c.id;
                const icon = active ? (sort!.dir === "asc" ? <ArrowUp className="size-3.5" /> : <ArrowDown className="size-3.5" />) : <ChevronsUpDown className="size-3.5 opacity-40" />;
                return (
                  <th key={c.id} scope="col" style={{ width: c.width }} aria-sort={active ? (sort!.dir === "asc" ? "ascending" : "descending") : undefined}
                    className={cn("h-10 whitespace-nowrap border-b border-border bg-surface px-4 font-medium", alignCls(c.align))}>
                    {c.sortable ? (
                      <button type="button" onClick={() => toggleSort(c.id)}
                        className={cn("-mx-1.5 inline-flex h-7 items-center gap-1 rounded-sm px-1.5 transition-colors hover:bg-surface-2 hover:text-fg focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-fg/20", active && "text-fg", c.align === "right" && "flex-row-reverse")}>
                        {c.header}{icon}
                      </button>
                    ) : c.header}
                  </th>
                );
              })}
              {rowActions && <th scope="col" className="h-10 w-12 border-b border-border bg-surface pr-2"><span className="sr-only">Actions</span></th>}
            </tr>
          </thead>
          <tbody>
            {loading
              ? Array.from({ length: Math.min(pageSize, 5) }).map((_, i) => (
                  <tr key={i}>
                    {selectable && <td className={cn(rowH, "border-b border-border pl-4 pr-2")}><span className="block size-4 rounded-xs bg-surface-2" /></td>}
                    {cols.map((c, j) => (
                      <td key={c.id} className={cn(rowH, "border-b border-border px-4")}>
                        <span className={cn("block h-3 animate-pulse rounded-xs bg-surface-2", c.align === "right" && "ml-auto", j === 0 ? "w-4/5" : "w-3/5")} />
                      </td>
                    ))}
                    {rowActions && <td className={cn(rowH, "border-b border-border")} />}
                  </tr>
                ))
              : view.map((r) => {
                  const id = rowId(r), on = sel.has(id);
                  return (
                    <tr key={id} data-selected={on || undefined} onClick={onRowClick ? () => onRowClick(r) : undefined}
                      className={cn("group/row transition-colors hover:bg-surface/70 data-[selected]:bg-surface-2/70", onRowClick && "cursor-pointer")}>
                      {selectable && (
                        <td className={cn(rowH, "border-b border-border pl-4 pr-2")} onClick={(e) => e.stopPropagation()}>
                          <span className="flex items-center"><Checkbox aria-label="Select row" checked={on} onCheckedChange={(v) => setSel((s) => { const n = new Set(s); v ? n.add(id) : n.delete(id); return n; })} /></span>
                        </td>
                      )}
                      {cols.map((c, j) => (
                        <td key={c.id} className={cn(rowH, "whitespace-nowrap border-b border-border px-4 text-fg", alignCls(c.align), c.align === "right" && "tabular-nums", j === 0 && "font-medium")}>
                          {c.cell(r)}
                        </td>
                      ))}
                      {rowActions && (
                        <td className={cn(rowH, "border-b border-border pr-2 text-right")} onClick={(e) => e.stopPropagation()}>
                          <DropdownMenu align="end" items={rowActions(r)} trigger={<Button variant="ghost" size="icon-sm" aria-label="Row actions" className="text-fg-subtle"><MoreHorizontal /></Button>} />
                        </td>
                      )}
                    </tr>
                  );
                })}
            {!loading && !view.length && (
              <tr>
                <td colSpan={colCount} className="h-40 border-b border-border text-center">
                  <div className="mx-auto max-w-xs space-y-2">
                    <p className="text-sm font-medium text-fg">{q || activeFacets ? "No matching results" : "Nothing here yet"}</p>
                    <div className="text-sm text-fg-muted">{empty ?? (q || activeFacets ? <>Try a different search or <button type="button" onClick={reset} className="font-medium text-fg underline underline-offset-4">reset filters</button>.</> : "Data will appear here once it's available.")}</div>
                  </div>
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Footer */}
      <div className="-mt-px flex flex-wrap items-center justify-between gap-3 border-t border-border px-4 py-2.5 text-sm">
        <p className="tabular-nums text-fg-muted">
          {selectable && sel.size > 0 ? `${sel.size} of ${rows.length} selected` : rows.length ? `${(cur - 1) * pageSize + 1}–${Math.min(cur * pageSize, rows.length)} of ${rows.length}` : "0 results"}
        </p>
        <div className="flex items-center gap-4">
          <label className="hidden items-center gap-2 text-fg-muted sm:flex">
            Rows
            <select value={pageSize} onChange={(e) => { setPageSize(Number(e.target.value)); setPage(1); }} aria-label="Rows per page"
              className="h-8 cursor-pointer rounded-md border border-border bg-bg pl-2 pr-7 text-sm text-fg shadow-xs focus:border-border-strong focus:outline-none">
              {pageSizeOptions.map((n) => <option key={n} value={n}>{n}</option>)}
            </select>
          </label>
          <div className="flex items-center gap-1">
            <span className="mr-2 tabular-nums text-fg-muted">Page {cur} of {pages}</span>
            <Button variant="outline" size="icon-sm" aria-label="Previous page" disabled={cur <= 1} onClick={() => setPage(cur - 1)}><ChevronLeft /></Button>
            <Button variant="outline" size="icon-sm" aria-label="Next page" disabled={cur >= pages} onClick={() => setPage(cur + 1)}><ChevronRight /></Button>
          </div>
        </div>
      </div>
    </div>
  );
}

components/ui/date-picker.tsx.source:
"use client";

import * as React from "react";
import { CalendarDays, ChevronLeft, ChevronRight, X } from "lucide-react";
import { cn } from "../../lib/cn";
import { Popover } from "./popover";

/**
 * Calendar · DatePicker · DateRangePicker
 * A keyboard-first calendar grid and the pickers built on it. Locale-aware month and
 * weekday names, min/max and disabled days, single or range selection, and presets.
 * Keys: arrows move a day/week · PageUp/PageDown change month · Home/End week start/end · Enter selects.
 */
export interface DateRange { from?: Date; to?: Date }

const startOfDay = (d: Date) => new Date(d.getFullYear(), d.getMonth(), d.getDate());
const addDays = (d: Date, n: number) => new Date(d.getFullYear(), d.getMonth(), d.getDate() + n);
const addMonths = (d: Date, n: number) => { const x = new Date(d.getFullYear(), d.getMonth() + n, 1); const last = new Date(x.getFullYear(), x.getMonth() + 1, 0).getDate(); return new Date(x.getFullYear(), x.getMonth(), Math.min(d.getDate(), last)); };
export const sameDay = (a?: Date, b?: Date) => !!a && !!b && a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate();
const fmtDay = (d: Date) => d.toLocaleDateString(undefined, { month: "short", day: "numeric", year: "numeric" });

export interface CalendarProps {
  mode?: "single" | "range";
  selected?: Date | DateRange;
  onSelect?: (value: Date | DateRange) => void;
  min?: Date;
  max?: Date;
  isDisabled?: (d: Date) => boolean;
  /** 0 = Sunday, 1 = Monday (default) */
  weekStartsOn?: 0 | 1;
  defaultMonth?: Date;
  /** Focus the selected (or today's) day on mount — used inside pickers */
  autoFocus?: boolean;
  className?: string;
}

export function Calendar({ mode = "single", selected, onSelect, min, max, isDisabled, weekStartsOn = 1, defaultMonth, autoFocus, className }: CalendarProps) {
  const today = startOfDay(new Date());
  const initial = (selected instanceof Date ? selected : (selected as DateRange | undefined)?.from) ?? defaultMonth ?? today;
  const [focus, setFocus] = React.useState(startOfDay(initial));
  const [hover, setHover] = React.useState<Date | null>(null);
  const grid = React.useRef<HTMLDivElement>(null);
  const moved = React.useRef(false);
  const month = new Date(focus.getFullYear(), focus.getMonth(), 1);
  const offset = (month.getDay() - weekStartsOn + 7) % 7;
  const days = Array.from({ length: 42 }, (_, i) => addDays(month, i - offset));
  const weeks = days[35].getMonth() !== month.getMonth() ? 5 : 6;
  const weekdays = Array.from({ length: 7 }, (_, i) => addDays(new Date(2024, 0, 7 + weekStartsOn), i).toLocaleDateString(undefined, { weekday: "short" }).slice(0, 2));
  const off = (d: Date) => (min && d < startOfDay(min)) || (max && d > startOfDay(max)) || !!isDisabled?.(d);
  const range = mode === "range" ? ((selected as DateRange) ?? {}) : null;

  React.useEffect(() => {
    if (autoFocus) requestAnimationFrame(() => grid.current?.querySelector<HTMLElement>('[data-focus="true"]')?.focus());
  }, []); // eslint-disable-line react-hooks/exhaustive-deps
  React.useEffect(() => {
    if (!moved.current) return;
    grid.current?.querySelector<HTMLElement>('[data-focus="true"]')?.focus();
  }, [focus]);

  const choose = (d: Date) => {
    if (off(d)) return;
    if (mode === "single") return onSelect?.(d);
    const r = range!;
    if (!r.from || r.to) onSelect?.({ from: d, to: undefined });
    else onSelect?.(d < r.from ? { from: d, to: r.from } : { from: r.from, to: d });
  };

  const onKey = (e: React.KeyboardEvent) => {
    const map: Record<string, () => Date> = {
      ArrowLeft: () => addDays(focus, -1), ArrowRight: () => addDays(focus, 1), ArrowUp: () => addDays(focus, -7), ArrowDown: () => addDays(focus, 7),
      PageUp: () => addMonths(focus, e.shiftKey ? -12 : -1), PageDown: () => addMonths(focus, e.shiftKey ? 12 : 1),
      Home: () => addDays(focus, -((focus.getDay() - weekStartsOn + 7) % 7)), End: () => addDays(focus, 6 - ((focus.getDay() - weekStartsOn + 7) % 7)),
    };
    if (map[e.key]) { e.preventDefault(); moved.current = true; setFocus(map[e.key]()); }
    else if (e.key === "Enter" || e.key === " ") { e.preventDefault(); choose(focus); }
  };

  const inRange = (d: Date) => {
    if (!range?.from) return false;
    const end = range.to ?? hover;
    if (!end) return false;
    const [a, b] = range.from <= end ? [range.from, end] : [end, range.from];
    return d > a && d < b;
  };

  return (
    <div className={cn("w-[17.5rem] select-none p-3", className)}>
      <div className="mb-2 flex items-center justify-between">
        <button type="button" onClick={() => setFocus(addMonths(focus, -1))} aria-label="Previous month" className="grid size-8 place-items-center rounded-md text-fg-muted hover:bg-surface-2 hover:text-fg"><ChevronLeft className="size-4" /></button>
        <p className="text-sm font-medium text-fg" aria-live="polite">{month.toLocaleDateString(undefined, { month: "long", year: "numeric" })}</p>
        <button type="button" onClick={() => setFocus(addMonths(focus, 1))} aria-label="Next month" className="grid size-8 place-items-center rounded-md text-fg-muted hover:bg-surface-2 hover:text-fg"><ChevronRight className="size-4" /></button>
      </div>
      <div role="grid" ref={grid} onKeyDown={onKey} onMouseLeave={() => setHover(null)}>
        <div role="row" className="grid grid-cols-7">
          {weekdays.map((w) => <span key={w} role="columnheader" className="grid h-8 place-items-center text-xs text-fg-subtle">{w}</span>)}
        </div>
        {Array.from({ length: weeks }, (_, r) => (
          <div role="row" key={r} className="grid grid-cols-7">
            {days.slice(r * 7, r * 7 + 7).map((d) => {
              const outside = d.getMonth() !== month.getMonth();
              const isSel = mode === "single" ? sameDay(d, selected as Date) : sameDay(d, range?.from) || sameDay(d, range?.to);
              const mid = inRange(d);
              const disabled = off(d);
              const isFocus = sameDay(d, focus);
              return (
                <div role="gridcell" key={d.toISOString()} aria-selected={isSel || undefined} className={cn("relative p-px", mid && "bg-surface-2", (sameDay(d, range?.from) && (range?.to || hover)) && "rounded-l-md bg-surface-2", sameDay(d, range?.to) && "rounded-r-md bg-surface-2")}>
                  <button type="button" tabIndex={isFocus ? 0 : -1} data-focus={isFocus} disabled={disabled} onClick={() => { setFocus(d); choose(d); }} onMouseEnter={() => setHover(d)}
                    aria-label={d.toLocaleDateString(undefined, { weekday: "long", month: "long", day: "numeric", year: "numeric" })}
                    aria-current={sameDay(d, today) ? "date" : undefined}
                    className={cn("relative grid h-9 w-full place-items-center rounded-md text-sm tabular-nums transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-fg/30",
                      isSel ? "bg-fg font-medium text-bg" : outside ? "text-fg-subtle/70 hover:bg-surface-2" : "text-fg hover:bg-surface-2",
                      disabled && "cursor-not-allowed text-fg-subtle/40 line-through hover:bg-transparent")}>
                    {d.getDate()}
                    {sameDay(d, today) && !isSel && <span className="absolute bottom-1 size-1 rounded-full bg-fg" />}
                  </button>
                </div>
              );
            })}
          </div>
        ))}
      </div>
    </div>
  );
}

const triggerCls = "inline-flex h-9 w-full min-w-0 items-center gap-2 rounded-md border border-border bg-bg px-3 text-left text-sm shadow-xs transition-colors hover:border-border-strong focus-visible:outline-none focus-visible:ring-4 focus-visible:ring-fg/5 focus-visible:border-border-strong";

export interface DatePickerProps { value?: Date; onValueChange: (d: Date | undefined) => void; placeholder?: string; min?: Date; max?: Date; isDisabled?: (d: Date) => boolean; clearable?: boolean; className?: string }

export function DatePicker({ value, onValueChange, placeholder = "Pick a date", min, max, isDisabled, clearable = true, className }: DatePickerProps) {
  return (
    <div className={cn("relative w-full max-w-[16rem]", className)}>
      <Popover label="Choose date" className="w-auto p-0" trigger={<button type="button" className={triggerCls}><CalendarDays className="size-4 shrink-0 text-fg-subtle" /><span className={cn("flex-1 truncate", !value && "text-fg-subtle")}>{value ? fmtDay(value) : placeholder}</span></button>}>
        {(close) => <Calendar autoFocus selected={value} min={min} max={max} isDisabled={isDisabled} onSelect={(d) => { onValueChange(d as Date); close(); }} />}
      </Popover>
      {clearable && value && <button type="button" onClick={() => onValueChange(undefined)} aria-label="Clear date" className="absolute right-1.5 top-1/2 grid size-6 -translate-y-1/2 place-items-center rounded-sm text-fg-subtle hover:bg-surface-2 hover:text-fg"><X className="size-3.5" /></button>}
    </div>
  );
}

export interface DatePreset { label: string; range: () => DateRange }
export const defaultPresets: DatePreset[] = [
  { label: "Today", range: () => ({ from: startOfDay(new Date()), to: startOfDay(new Date()) }) },
  { label: "Last 7 days", range: () => ({ from: addDays(startOfDay(new Date()), -6), to: startOfDay(new Date()) }) },
  { label: "Last 30 days", range: () => ({ from: addDays(startOfDay(new Date()), -29), to: startOfDay(new Date()) }) },
  { label: "This month", range: () => { const t = new Date(); return { from: new Date(t.getFullYear(), t.getMonth(), 1), to: startOfDay(t) }; } },
];

export interface DateRangePickerProps { value: DateRange; onValueChange: (r: DateRange) => void; presets?: DatePreset[]; placeholder?: string; min?: Date; max?: Date; className?: string }

export function DateRangePicker({ value, onValueChange, presets = defaultPresets, placeholder = "Pick a date range", min, max, className }: DateRangePickerProps) {
  const label = value.from ? (value.to ? (sameDay(value.from, value.to) ? fmtDay(value.from) : `${fmtDay(value.from)} – ${fmtDay(value.to)}`) : `${fmtDay(value.from)} – …`) : null;
  return (
    <div className={cn("w-full max-w-[20rem]", className)}>
    <Popover label="Choose date range" className="w-auto max-w-[calc(100vw-16px)] p-0" trigger={<button type="button" className={triggerCls}><CalendarDays className="size-4 shrink-0 text-fg-subtle" /><span className={cn("flex-1 truncate", !label && "text-fg-subtle")}>{label ?? placeholder}</span></button>}>
      {(close) => (
        <div className="flex flex-col sm:flex-row">
          {presets.length > 0 && (
            <div className="flex gap-1 overflow-x-auto border-b border-border p-2 sm:w-36 sm:flex-col sm:border-b-0 sm:border-r">
              {presets.map((p) => <button key={p.label} type="button" onClick={() => { onValueChange(p.range()); close(); }} className="h-8 shrink-0 rounded-md px-2 text-left text-sm text-fg-muted hover:bg-surface-2 hover:text-fg">{p.label}</button>)}
            </div>
          )}
          <Calendar autoFocus mode="range" selected={value} min={min} max={max} onSelect={(r) => { onValueChange(r as DateRange); if ((r as DateRange).to) close(); }} />
        </div>
      )}
    </Popover>
    </div>
  );
}

components/ui/dialog.tsx.source:
"use client";

import * as React from "react";
import { createPortal } from "react-dom";
import { X } from "lucide-react";
import { cn } from "../../lib/cn";

/**
 * Accessible modal primitive: portal, focus trap, Esc + backdrop close, focus restore.
 * Compose with DialogHeader / DialogTitle / DialogDescription / DialogBody / DialogFooter.
 */
export interface DialogProps {
  open: boolean;
  onClose: () => void;
  children: React.ReactNode;
  labelledBy?: string;
  label?: string;
  className?: string;
  /** "center" for dialogs, "top" for command palettes */
  position?: "center" | "top";
  showClose?: boolean;
  /** Close when the backdrop is clicked (default true) */
  dismissOnBackdrop?: boolean;
}

export function Dialog({ open, onClose, children, labelledBy, label, className, position = "center", showClose = true, dismissOnBackdrop = true }: DialogProps) {
  const ref = React.useRef<HTMLDivElement>(null);
  const closeRef = React.useRef(onClose);
  closeRef.current = onClose;

  React.useEffect(() => {
    if (!open) return;
    const prev = document.activeElement as HTMLElement | null;
    const focusables = () =>
      Array.from(ref.current?.querySelectorAll<HTMLElement>('button:not([disabled]), [href], input, textarea, select, [tabindex]:not([tabindex="-1"])') ?? []);
    (ref.current?.querySelector<HTMLElement>("[data-autofocus]") ?? focusables()[0])?.focus();
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") { e.stopPropagation(); closeRef.current(); }
      if (e.key === "Tab") {
        const f = focusables();
        if (!f.length) return;
        const first = f[0], last = f[f.length - 1];
        if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
        else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
      }
    };
    document.addEventListener("keydown", onKey);
    const overflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => { document.removeEventListener("keydown", onKey); document.body.style.overflow = overflow; prev?.focus?.(); };
  }, [open]);

  if (!open) return null;
  return createPortal(
    <div className={cn("fixed inset-0 z-[100] flex justify-center p-4", position === "center" ? "items-center" : "items-start pt-[12vh]")}>
      <div className="absolute inset-0 bg-black/40 backdrop-blur-[2px] dark:bg-black/60" onClick={dismissOnBackdrop ? onClose : undefined} aria-hidden style={{ animation: "pl-in .15s ease-out" }} />
      <div
        ref={ref}
        role="dialog"
        aria-modal="true"
        aria-labelledby={labelledBy}
        aria-label={label}
        className={cn("relative w-full max-w-lg rounded-xl border border-border bg-bg shadow-lg", className)}
        style={{ animation: "pl-pop .18s var(--ease-out)" }}
      >
        {showClose && (
          <button type="button" onClick={onClose} aria-label="Close" className="absolute right-3 top-3 grid size-8 place-items-center rounded-sm text-fg-subtle transition-colors hover:bg-surface-2 hover:text-fg">
            <X className="size-4" />
          </button>
        )}
        {children}
      </div>
    </div>,
    document.body
  );
}

/* ---------- Layout helpers ---------- */
export function DialogHeader({ className, ...p }: React.HTMLAttributes<HTMLDivElement>) {
  return <div className={cn("space-y-1 p-6 pb-0 pr-12", className)} {...p} />;
}
export function DialogTitle({ className, ...p }: React.HTMLAttributes<HTMLHeadingElement>) {
  return <h2 className={cn("text-xl font-semibold text-fg", className)} {...p} />;
}
export function DialogDescription({ className, ...p }: React.HTMLAttributes<HTMLParagraphElement>) {
  return <p className={cn("text-base text-fg-muted", className)} {...p} />;
}
export function DialogBody({ className, ...p }: React.HTMLAttributes<HTMLDivElement>) {
  return <div className={cn("p-6", className)} {...p} />;
}
export function DialogFooter({ className, ...p }: React.HTMLAttributes<HTMLDivElement>) {
  return <div className={cn("flex flex-col-reverse gap-2 border-t border-border bg-surface px-6 py-4 sm:flex-row sm:justify-end rounded-b-xl", className)} {...p} />;
}

components/ui/field.tsx.source:
"use client";

import * as React from "react";
import { cn } from "../../lib/cn";

/**
 * Field
 * Label + control + description + error, wired together for screen readers.
 * <Field label="Email" description="We'll never share it" error={err}>{(p) => <Input {...p} />}</Field>
 * The render prop receives id, aria-describedby and aria-invalid for the control.
 */
export interface FieldControlProps { id: string; "aria-describedby"?: string; "aria-invalid"?: boolean }

export interface FieldProps {
  label?: React.ReactNode;
  description?: React.ReactNode;
  error?: React.ReactNode;
  required?: boolean;
  optional?: boolean;
  /** Label beside the control instead of above (checkbox/switch rows) */
  orientation?: "vertical" | "horizontal";
  children: (props: FieldControlProps) => React.ReactNode;
  className?: string;
}

export function Field({ label, description, error, required, optional, orientation = "vertical", children, className }: FieldProps) {
  const id = React.useId();
  const descId = description ? `${id}-d` : undefined;
  const errId = error ? `${id}-e` : undefined;
  const control = children({ id, "aria-describedby": [errId, descId].filter(Boolean).join(" ") || undefined, "aria-invalid": error ? true : undefined });
  const text = (
    <>
      {label && <Label htmlFor={id} required={required} optional={optional}>{label}</Label>}
      {description && <p id={descId} className="text-xs text-fg-subtle">{description}</p>}
    </>
  );
  if (orientation === "horizontal")
    return (
      <div className={cn("flex items-start justify-between gap-4", className)}>
        <div className="space-y-0.5">{text}{error && <FieldError id={errId}>{error}</FieldError>}</div>
        <div className="pt-0.5">{control}</div>
      </div>
    );
  return (
    <div className={cn("flex flex-col gap-2", className)}>
      {label && <Label htmlFor={id} required={required} optional={optional}>{label}</Label>}
      {control}
      {error ? <FieldError id={errId}>{error}</FieldError> : description && <p id={descId} className="text-xs text-fg-subtle">{description}</p>}
    </div>
  );
}

export function Label({ className, required, optional, children, ...p }: React.LabelHTMLAttributes<HTMLLabelElement> & { required?: boolean; optional?: boolean }) {
  return (
    <label className={cn("text-sm font-medium text-fg", className)} {...p}>
      {children}
      {required && <span className="ml-0.5 text-danger" aria-hidden>*</span>}
      {optional && <span className="ml-1 font-normal text-fg-subtle">(optional)</span>}
    </label>
  );
}

export function FieldError({ className, ...p }: React.HTMLAttributes<HTMLParagraphElement>) {
  return <p role="alert" className={cn("text-xs text-danger", className)} {...p} />;
}

components/ui/hover-card.tsx.source:
"use client";

import * as React from "react";
import { cn } from "../../lib/cn";
import { useFloating, Portal, floatingPanel, type Side, type Align } from "../../lib/floating";

/**
 * HoverCard
 * Preview on hover or focus — user profiles, link previews, source previews.
 * Opens after a short delay so moving the mouse across the page doesn't flash cards,
 * and stays open while the pointer is over the card itself.
 */
export interface HoverCardProps {
  trigger: React.ReactElement;
  children: React.ReactNode;
  side?: Side;
  align?: Align;
  openDelay?: number;
  closeDelay?: number;
  className?: string;
}

export function HoverCard({ trigger, children, side = "bottom", align = "start", openDelay = 400, closeDelay = 150, className }: HoverCardProps) {
  const [open, setOpen] = React.useState(false);
  const t = React.useRef<number | undefined>(undefined);
  const fl = useFloating({ open, side, align });
  const show = () => { window.clearTimeout(t.current); t.current = window.setTimeout(() => setOpen(true), openDelay); };
  const hide = () => { window.clearTimeout(t.current); t.current = window.setTimeout(() => setOpen(false), closeDelay); };
  React.useEffect(() => () => window.clearTimeout(t.current), []);

  const el = React.cloneElement(trigger, {
    ref: (n: HTMLElement) => { fl.anchor.current = n; },
    onMouseEnter: show, onMouseLeave: hide, onFocus: show, onBlur: hide,
  } as any);

  return (
    <>
      {el}
      {open && (
        <Portal>
          <div ref={(n) => { fl.floating.current = n; }} onMouseEnter={show} onMouseLeave={hide} style={{ ...fl.style, animation: "pl-pop .14s var(--ease-out)" }} className={cn(floatingPanel, "w-72 p-4", className)}>
            {children}
          </div>
        </Portal>
      )}
    </>
  );
}

