import * as React from "react";
import { cn } from "../../lib/cn";

/**
 * Kbd
 * Keyboard keys and shortcuts. Use <KbdGroup keys={["⌘","K"]}/> for combos.
 */
export function Kbd({ className, ...p }: React.HTMLAttributes<HTMLElement>) {
  return <kbd className={cn("inline-flex h-5 min-w-5 items-center justify-center rounded-xs border border-border bg-surface px-1 font-sans text-2xs font-medium text-fg-muted shadow-[inset_0_-1px_0_rgb(var(--border))]", className)} {...p} />;
}

export function KbdGroup({ keys, className }: { keys: string[]; className?: string }) {
  return <span className={cn("inline-flex items-center gap-0.5", className)}>{keys.map((k) => <Kbd key={k}>{k}</Kbd>)}</span>;
}

components/ui/menu.tsx.source:
"use client";

import * as React from "react";
import { Check, ChevronRight } from "lucide-react";
import { cn } from "../../lib/cn";
import { useFloating, useOutside, Portal, floatingPanel, type Side, type Align } from "../../lib/floating";
import { KbdGroup } from "./kbd";

/**
 * Shared menu engine for DropdownMenu and ContextMenu.
 * Data-driven items: action, checkbox, radio, label, separator, and one level of submenu.
 * Keyboard: ↑ ↓ Home End move · Enter/Space select · → opens submenu · ← / Esc closes · type to jump.
 */
export type MenuItem =
  | { type?: "item"; label: string; icon?: React.ReactNode; shortcut?: string[]; onSelect?: () => void; disabled?: boolean; danger?: boolean; description?: string }
  | { type: "checkbox"; label: string; checked: boolean; onCheckedChange: (v: boolean) => void; disabled?: boolean; hint?: string }
  | { type: "radio"; label: string; value: string; group: string; checked: boolean; onSelect: () => void }
  | { type: "label"; label: string }
  | { type: "separator" }
  | { type: "sub"; label: string; icon?: React.ReactNode; items: MenuItem[] };

const focusable = (it: MenuItem) => it.type !== "label" && it.type !== "separator" && !("disabled" in it && it.disabled);

export function MenuList({ items, onClose, className, style, floatingRef, level = 0 }: { items: MenuItem[]; onClose: () => void; className?: string; style?: React.CSSProperties; floatingRef?: (el: HTMLDivElement | null) => void; level?: number }) {
  const [active, setActive] = React.useState(-1);
  const [sub, setSub] = React.useState<number | null>(null);
  const listRef = React.useRef<HTMLDivElement | null>(null);
  const buf = React.useRef({ s: "", t: 0 });
  const idxs = items.map((it, i) => (focusable(it) ? i : -1)).filter((i) => i >= 0);

  React.useEffect(() => { listRef.current?.focus(); }, []);
  React.useEffect(() => { if (active >= 0) (listRef.current?.querySelector(`[data-i="${active}"]`) as HTMLElement | null)?.focus(); }, [active]);

  const move = (d: 1 | -1) => {
    const pos = idxs.indexOf(active);
    setActive(idxs[(pos + d + idxs.length) % idxs.length] ?? idxs[0]);
  };
  const select = (i: number) => {
    const it = items[i];
    if (!it || !focusable(it)) return;
    if (it.type === "sub") { setSub(i); return; }
    if (it.type === "checkbox") { it.onCheckedChange(!it.checked); return; }
    if (it.type === "radio") { it.onSelect(); return; }
    if (it.type === undefined || it.type === "item") it.onSelect?.();
    onClose();
  };

  return (
    <div
      ref={(el) => { listRef.current = el; floatingRef?.(el); }}
      role="menu"
      tabIndex={-1}
      style={{ ...style, animation: "pl-pop .12s var(--ease-out)" }}
      className={cn(floatingPanel, "min-w-48 p-1 focus:outline-none", className)}
      onKeyDown={(e) => {
        if (e.key === "ArrowDown") { e.preventDefault(); move(1); }
        else if (e.key === "ArrowUp") { e.preventDefault(); move(-1); }
        else if (e.key === "Home") { e.preventDefault(); setActive(idxs[0]); }
        else if (e.key === "End") { e.preventDefault(); setActive(idxs[idxs.length - 1]); }
        else if (e.key === "Enter" || e.key === " ") { e.preventDefault(); select(active); }
        else if (e.key === "ArrowRight" && items[active]?.type === "sub") { e.preventDefault(); setSub(active); }
        else if (e.key === "ArrowLeft" && level > 0) { e.preventDefault(); e.stopPropagation(); onClose(); }
        else if (e.key === "Tab") { e.preventDefault(); onClose(); }
        else if (e.key.length === 1 && /\S/.test(e.key)) {
          const now = Date.now();
          buf.current = { s: (now - buf.current.t < 500 ? buf.current.s : "") + e.key.toLowerCase(), t: now };
          const hit = idxs.find((i) => "label" in items[i] && (items[i] as { label: string }).label.toLowerCase().startsWith(buf.current.s));
          if (hit != null) setActive(hit);
        }
        if (e.key === "Escape") { e.stopPropagation(); onClose(); }
      }}
    >
      {items.map((it, i) => {
        if (it.type === "separator") return <div key={i} role="separator" className="-mx-1 my-1 h-px bg-border" />;
        if (it.type === "label") return <div key={i} className="px-2 pb-1 pt-2 text-xs font-medium text-fg-subtle">{it.label}</div>;
        const disabled = "disabled" in it && it.disabled;
        const role = it.type === "checkbox" ? "menuitemcheckbox" : it.type === "radio" ? "menuitemradio" : "menuitem";
        const checked = it.type === "checkbox" || it.type === "radio" ? it.checked : undefined;
        return (
          <div key={i} className="relative">
            <div
              data-i={i}
              role={role}
              aria-checked={checked}
              aria-disabled={disabled || undefined}
              aria-haspopup={it.type === "sub" ? "menu" : undefined}
              aria-expanded={it.type === "sub" ? sub === i : undefined}
              tabIndex={-1}
              onMouseEnter={() => { setActive(i); if (it.type === "sub") setSub(i); else setSub(null); }}
              onClick={() => select(i)}
              className={cn(
                "flex h-8 cursor-default select-none items-center gap-2 rounded-sm px-2 text-sm outline-none [&_svg]:size-4 [&_svg]:shrink-0",
                active === i ? "bg-surface-2 text-fg" : "text-fg",
                "danger" in it && it.danger && "text-danger",
                disabled && "pointer-events-none opacity-40",
                "description" in it && it.description && "h-auto py-1.5"
              )}
            >
              {(it.type === "checkbox" || it.type === "radio") ? (
                <span className="grid size-4 place-items-center">{it.checked && (it.type === "radio" ? <span className="size-1.5 rounded-full bg-current" /> : <Check className="!size-3.5" />)}</span>
              ) : "icon" in it && it.icon ? <span className={cn("text-fg-muted", "danger" in it && it.danger && "text-danger")}>{it.icon}</span> : null}
              <span className="flex-1">
                {it.label}
                {"description" in it && it.description && <span className="block text-xs text-fg-subtle">{it.description}</span>}
              </span>
              {"shortcut" in it && it.shortcut && <KbdGroup keys={it.shortcut} className="ml-4" />}
              {"hint" in it && it.hint && <span className="ml-4 text-xs tabular-nums text-fg-subtle">{it.hint}</span>}
              {it.type === "sub" && <ChevronRight className="text-fg-subtle" />}
            </div>
            {it.type === "sub" && sub === i && (
              <MenuList items={it.items} level={level + 1} onClose={() => { setSub(null); setActive(i); }} className="absolute left-full top-0 ml-1" />
            )}
          </div>
        );
      })}
    </div>
  );
}

/**
 * DropdownMenu
 * Actions triggered from a button — row actions, account menus, "more" menus.
 */
export interface DropdownMenuProps {
  trigger: React.ReactElement;
  items: MenuItem[];
  side?: Side;
  align?: Align;
  className?: string;
}

export function DropdownMenu({ trigger, items, side = "bottom", align = "start", className }: DropdownMenuProps) {
  const [open, setOpen] = React.useState(false);
  const fl = useFloating({ open, side, align, offset: 6 });
  const close = React.useCallback(() => { setOpen(false); (fl.anchor.current as HTMLElement | null)?.focus(); }, [fl.anchor]);
  useOutside(open, () => setOpen(false), [fl.anchor, fl.floating]);
  const t = React.cloneElement(trigger, {
    ref: (el: HTMLElement) => { fl.anchor.current = el; },
    onClick: () => setOpen((o) => !o),
    onKeyDown: (e: React.KeyboardEvent) => { if (e.key === "ArrowDown") { e.preventDefault(); setOpen(true); } },
    "aria-haspopup": "menu",
    "aria-expanded": open,
  } as any);
  return (
    <>
      {t}
      {open && <Portal><MenuList items={items} onClose={close} style={fl.style} floatingRef={(el) => { fl.floating.current = el; }} className={className} /></Portal>}
    </>
  );
}

/**
 * ContextMenu
 * Right-click (or long-press on touch) menu for an area — messages, files, canvas items.
 * Always mirror these actions somewhere visible; context menus are invisible to most users.
 */
export function ContextMenu({ items, children, className }: { items: MenuItem[]; children: React.ReactNode; className?: string }) {
  const [pos, setPos] = React.useState<{ x: number; y: number } | null>(null);
  const menu = React.useRef<HTMLElement | null>(null);
  const press = React.useRef<number | undefined>(undefined);
  useOutside(!!pos, () => setPos(null), [menu]);
  const openAt = (x: number, y: number) => setPos({ x: Math.min(x, window.innerWidth - 220), y: Math.min(y, window.innerHeight - 40 - items.length * 32) });
  return (
    <div
      className={className}
      onContextMenu={(e) => { e.preventDefault(); openAt(e.clientX, e.clientY); }}
      onTouchStart={(e) => { const t = e.touches[0]; press.current = window.setTimeout(() => openAt(t.clientX, t.clientY), 550); }}
      onTouchEnd={() => window.clearTimeout(press.current)}
      onTouchMove={() => window.clearTimeout(press.current)}
    >
      {children}
      {pos && <Portal><MenuList items={items} onClose={() => setPos(null)} style={{ position: "fixed", top: pos.y, left: pos.x }} floatingRef={(el) => { menu.current = el; }} /></Portal>}
    </div>
  );
}

components/ui/number-input.tsx.source:
"use client";

import * as React from "react";
import { Minus, Plus } from "lucide-react";
import { cn } from "../../lib/cn";

/**
 * NumberInput
 * A numeric field with steppers. Typing is free; the value is parsed, clamped and rounded
 * on blur or Enter, so half-typed numbers never fight the user.
 * ↑ ↓ step · Shift = ×10 · PageUp/PageDown ×10 · Home/End jump to min/max · hold a stepper to repeat.
 */
export interface NumberInputProps {
  value: number;
  onValueChange: (v: number) => void;
  min?: number;
  max?: number;
  step?: number;
  /** Decimal places (defaults to the step's precision) */
  precision?: number;
  /** Unit shown after the number, e.g. "tokens" or "%" */
  suffix?: string;
  size?: "sm" | "md" | "lg";
  disabled?: boolean;
  id?: string;
  className?: string;
  "aria-label"?: string;
  "aria-describedby"?: string;
  "aria-invalid"?: boolean;
}

const sizes = { sm: "h-8", md: "h-9", lg: "h-10" };

export function NumberInput({ value, onValueChange, min = -Infinity, max = Infinity, step = 1, precision, suffix, size = "md", disabled, id, className, ...aria }: NumberInputProps) {
  const places = precision ?? (String(step).split(".")[1]?.length ?? 0);
  const fmt = (v: number) => v.toFixed(places);
  const [draft, setDraft] = React.useState(fmt(value));
  const [editing, setEditing] = React.useState(false);
  const clamp = (v: number) => Math.min(max, Math.max(min, Number(v.toFixed(places))));
  const set = (v: number) => { const c = clamp(v); onValueChange(c); setDraft(fmt(c)); };
  const latest = React.useRef(value);
  latest.current = value;

  React.useEffect(() => { if (!editing) setDraft(fmt(value)); }, [value, editing]); // eslint-disable-line react-hooks/exhaustive-deps

  const commit = () => {
    setEditing(false);
    const n = parseFloat(draft.replace(/[^\d.\-]/g, ""));
    if (isNaN(n)) setDraft(fmt(value)); else set(n);
  };

  // Press-and-hold repeat
  const timer = React.useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const hold = (dir: 1 | -1) => {
    set(latest.current + dir * step);
    const rep = (delay: number) => { timer.current = setTimeout(() => { set(latest.current + dir * step); rep(Math.max(40, delay * 0.8)); }, delay); };
    rep(400);
  };
  const release = () => clearTimeout(timer.current);
  React.useEffect(() => release, []);

  const parsed = parseFloat(draft);
  const outOfRange = editing && !isNaN(parsed) && (parsed < min || parsed > max);
  const btn = "grid aspect-square h-full shrink-0 place-items-center text-fg-muted transition-colors hover:bg-surface-2 hover:text-fg disabled:pointer-events-none disabled:opacity-40 [&_svg]:size-3.5";

  return (
    <div className={cn("inline-flex w-full max-w-[11rem] items-stretch overflow-hidden rounded-md border bg-bg shadow-xs transition-[border-color,box-shadow] focus-within:border-border-strong focus-within:ring-4 focus-within:ring-fg/5",
      outOfRange ? "border-danger/50" : "border-border", sizes[size], disabled && "opacity-50", className)}>
      <button type="button" tabIndex={-1} aria-label="Decrease" disabled={disabled || value <= min} onPointerDown={() => hold(-1)} onPointerUp={release} onPointerLeave={release} className={cn(btn, "border-r border-border")}><Minus /></button>
      <div className="flex min-w-0 flex-1 items-center justify-center gap-1 px-2">
        <input
          id={id}
          type="text"
          inputMode="decimal"
          role="spinbutton"
          aria-valuenow={value}
          aria-valuemin={isFinite(min) ? min : undefined}
          aria-valuemax={isFinite(max) ? max : undefined}
          {...aria}
          aria-invalid={outOfRange || aria["aria-invalid"] || undefined}
          disabled={disabled}
          value={draft}
          onFocus={(e) => { setEditing(true); e.currentTarget.select(); }}
          onChange={(e) => setDraft(e.target.value)}
          onBlur={commit}
          onKeyDown={(e) => {
            const big = step * 10;
            const k: Record<string, () => void> = {
              ArrowUp: () => set(value + (e.shiftKey ? big : step)), ArrowDown: () => set(value - (e.shiftKey ? big : step)),
              PageUp: () => set(value + big), PageDown: () => set(value - big),
              Home: () => isFinite(min) && set(min), End: () => isFinite(max) && set(max),
              Enter: () => commit(),
            };
            if (k[e.key]) { e.preventDefault(); k[e.key](); if (e.key !== "Enter") setEditing(false); }
          }}
          style={{ width: `${Math.max(2, draft.length + 0.5)}ch` }}
          className="min-w-0 bg-transparent text-center text-sm tabular-nums text-fg focus:outline-none"
        />
        {suffix && <span className="shrink-0 text-sm text-fg-subtle">{suffix}</span>}
      </div>
      <button type="button" tabIndex={-1} aria-label="Increase" disabled={disabled || value >= max} onPointerDown={() => hold(1)} onPointerUp={release} onPointerLeave={release} className={cn(btn, "border-l border-border")}><Plus /></button>
    </div>
  );
}

components/ui/pagination.tsx.source:
"use client";

import * as React from "react";
import { ChevronLeft, ChevronRight } from "lucide-react";
import { cn } from "../../lib/cn";

/**
 * Pagination
 * Page numbers with ellipses: 1 … 4 5 6 … 20. Always shows first, last, current and `siblings` around it.
 * Use for tables and history lists; prefer "Load more" / infinite scroll for feeds.
 */
export function pageRange(page: number, total: number, siblings = 1): (number | "…")[] {
  const size = siblings * 2 + 5;
  if (total <= size) return Array.from({ length: total }, (_, i) => i + 1);
  const l = Math.max(page - siblings, 2), r = Math.min(page + siblings, total - 1);
  const out: (number | "…")[] = [1];
  if (l > 2) out.push("…");
  for (let i = l; i <= r; i++) out.push(i);
  if (r < total - 1) out.push("…");
  out.push(total);
  return out;
}

export interface PaginationProps {
  page: number;
  total: number;
  onPageChange: (page: number) => void;
  siblings?: number;
  /** "numbers" shows pages, "simple" shows "Page 2 of 10" */
  variant?: "numbers" | "simple";
  className?: string;
}

export function Pagination({ page, total, onPageChange, siblings = 1, variant = "numbers", className }: PaginationProps) {
  const btn = "inline-flex h-8 min-w-8 items-center justify-center gap-1 rounded-sm px-2 text-sm font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-fg/20 disabled:pointer-events-none disabled:opacity-40";
  return (
    <nav aria-label="Pagination" className={cn("flex items-center gap-1", className)}>
      <button type="button" className={cn(btn, "pr-3 text-fg-muted hover:bg-surface-2 hover:text-fg")} disabled={page <= 1} onClick={() => onPageChange(page - 1)} aria-label="Previous page">
        <ChevronLeft className="size-4" /><span className="hidden sm:inline">Previous</span>
      </button>
      {variant === "simple" ? (
        <span className="px-2 text-sm tabular-nums text-fg-muted">Page {page} of {total}</span>
      ) : (
        pageRange(page, total, siblings).map((p, i) =>
          p === "…" ? <span key={`e${i}`} className="grid h-8 min-w-8 place-items-center text-sm text-fg-subtle" aria-hidden>…</span> : (
            <button key={p} type="button" aria-current={p === page ? "page" : undefined} aria-label={`Page ${p}`} onClick={() => onPageChange(p)}
              className={cn(btn, "tabular-nums", p === page ? "border border-border bg-bg text-fg shadow-xs" : "text-fg-muted hover:bg-surface-2 hover:text-fg")}>
              {p}
            </button>
          )
        )
      )}
      <button type="button" className={cn(btn, "pl-3 text-fg-muted hover:bg-surface-2 hover:text-fg")} disabled={page >= total} onClick={() => onPageChange(page + 1)} aria-label="Next page">
        <span className="hidden sm:inline">Next</span><ChevronRight className="size-4" />
      </button>
    </nav>
  );
}

components/ui/popover.tsx.source:
"use client";

import * as React from "react";
import { cn } from "../../lib/cn";
import { useFloating, useOutside, Portal, floatingPanel, type Side, type Align } from "../../lib/floating";

/**
 * Popover
 * Rich, interactive floating content anchored to a trigger (filters, settings, share panels).
 * Portalled so it's never clipped, flips when there's no room, closes on outside click / Esc,
 * and returns focus to the trigger.
 */
export interface PopoverProps {
  trigger: React.ReactElement;
  children: React.ReactNode | ((close: () => void) => React.ReactNode);
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  side?: Side;
  align?: Align;
  className?: string;
  /** Accessible name for the dialog */
  label?: string;
}

export function Popover({ trigger, children, open, defaultOpen, onOpenChange, side = "bottom", align = "start", className, label }: PopoverProps) {
  const [inner, setInner] = React.useState(!!defaultOpen);
  const isOpen = open ?? inner;
  const set = React.useCallback((v: boolean) => { setInner(v); onOpenChange?.(v); }, [onOpenChange]);
  const close = React.useCallback(() => { set(false); (fl.anchor.current as HTMLElement | null)?.focus?.(); }, [set]); // eslint-disable-line
  const fl = useFloating({ open: isOpen, side, align });
  const id = React.useId();
  useOutside(isOpen, () => set(false), [fl.anchor, fl.floating]);

  const t = React.cloneElement(trigger, {
    ref: (el: HTMLElement) => { fl.anchor.current = el; },
    onClick: (e: React.MouseEvent) => { (trigger.props as any).onClick?.(e); set(!isOpen); },
    "aria-expanded": isOpen,
    "aria-haspopup": "dialog",
    "aria-controls": isOpen ? id : undefined,
  } as any);

  return (
    <>
      {t}
      {isOpen && (
        <Portal>
          <div
            id={id}
            ref={(el) => { fl.floating.current = el; }}
            role="dialog"
            aria-label={label}
            style={{ ...fl.style, animation: "pl-pop .14s var(--ease-out)" }}
            className={cn(floatingPanel, "w-72 p-4", className)}
            onKeyDown={(e) => { if (e.key === "Escape") close(); }}
          >
            {typeof children === "function" ? children(close) : children}
          </div>
        </Portal>
      )}
    </>
  );
}

components/ui/progress.tsx.source:
import * as React from "react";
import { cn } from "../../lib/cn";

/**
 * Progress
 * Determinate bar or ring for known progress (uploads, indexing, onboarding steps).
 * Omit `value` for an indeterminate bar. Label + value are announced to screen readers.
 */
export interface ProgressProps {
  value?: number;
  max?: number;
  label?: string;
  showValue?: boolean;
  size?: "sm" | "md";
  tone?: "default" | "success" | "warning" | "danger";
  className?: string;
}

const toneCls = { default: "bg-accent", success: "bg-success", warning: "bg-warning", danger: "bg-danger" };

export function Progress({ value, max = 100, label, showValue, size = "md", tone = "default", className }: ProgressProps) {
  const pct = value == null ? null : Math.min(100, (value / max) * 100);
  return (
    <div className={cn("w-full", className)}>
      {(label || showValue) && (
        <div className="mb-2 flex justify-between text-sm">
          {label && <span className="font-medium text-fg">{label}</span>}
          {showValue && pct != null && <span className="tabular-nums text-fg-muted">{Math.round(pct)}%</span>}
        </div>
      )}
      <div role="progressbar" aria-label={label} aria-valuemin={0} aria-valuemax={max} aria-valuenow={value} className={cn("relative overflow-hidden rounded-full bg-surface-2", size === "sm" ? "h-1" : "h-2")}>
        {pct == null ? (
          <div className={cn("absolute inset-y-0 w-1/3 rounded-full", toneCls[tone])} style={{ animation: "pl-indeterminate 1.4s ease-in-out infinite" }} />
        ) : (
          <div className={cn("h-full rounded-full transition-[width] duration-500 ease-out", toneCls[tone])} style={{ width: `${pct}%` }} />
        )}
      </div>
    </div>
  );
}

export function ProgressRing({ value, max = 100, size = 40, stroke = 4, label, showValue = true, className }: { value: number; max?: number; size?: number; stroke?: number; label?: string; showValue?: boolean; className?: string }) {
  const r = (size - stroke) / 2, c = 2 * Math.PI * r, pct = Math.min(100, (value / max) * 100);
  return (
    <span role="progressbar" aria-label={label} aria-valuenow={value} aria-valuemin={0} aria-valuemax={max} className={cn("relative inline-grid place-items-center", className)} style={{ width: size, height: size }}>
      <svg width={size} height={size} className="-rotate-90" aria-hidden>
        <circle cx={size / 2} cy={size / 2} r={r} fill="none" strokeWidth={stroke} className="stroke-surface-2" />
        <circle cx={size / 2} cy={size / 2} r={r} fill="none" strokeWidth={stroke} strokeLinecap="round" className="stroke-accent transition-[stroke-dashoffset] duration-500" strokeDasharray={c} strokeDashoffset={c * (1 - pct / 100)} />
      </svg>
      {showValue && <span className="absolute text-2xs font-medium tabular-nums text-fg">{Math.round(pct)}%</span>}
    </span>
  );
}

components/ui/radio-group.tsx.source:
"use client";

import * as React from "react";
import { cn } from "../../lib/cn";

/**
 * RadioGroup
 * One choice from a short list. Native radios for free keyboard support (arrow keys move selection).
 * `variant="card"` renders bordered cards — good for plan or model pickers.
 */
export interface RadioOption { value: string; label: React.ReactNode; description?: React.ReactNode; disabled?: boolean }

export interface RadioGroupProps {
  options: RadioOption[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  name?: string;
  variant?: "default" | "card";
  orientation?: "vertical" | "horizontal";
  label?: string;
  className?: string;
}

export function RadioGroup({ options, value, defaultValue, onValueChange, name, variant = "default", orientation = "vertical", label, className }: RadioGroupProps) {
  const auto = React.useId();
  const [inner, setInner] = React.useState(defaultValue);
  const current = value ?? inner;
  const n = name ?? auto;
  return (
    <div role="radiogroup" aria-label={label} className={cn("flex gap-3", orientation === "vertical" ? "flex-col" : "flex-wrap", className)}>
      {options.map((o) => {
        const checked = current === o.value;
        return (
          <label
            key={o.value}
            className={cn(
              "group flex cursor-pointer items-start gap-3",
              variant === "card" && "rounded-lg border p-4 transition-colors has-[:focus-visible]:ring-2 has-[:focus-visible]:ring-fg/20",
              variant === "card" && (checked ? "border-fg bg-surface" : "border-border hover:border-border-strong"),
              o.disabled && "cursor-not-allowed opacity-50"
            )}
          >
            <input
              type="radio"
              name={n}
              value={o.value}
              checked={checked}
              disabled={o.disabled}
              onChange={() => { setInner(o.value); onValueChange?.(o.value); }}
              className="peer sr-only"
            />
            <span className={cn("mt-0.5 grid size-4 shrink-0 place-items-center rounded-full border shadow-xs transition-colors peer-focus-visible:ring-2 peer-focus-visible:ring-fg/20 peer-focus-visible:ring-offset-2 peer-focus-visible:ring-offset-bg", checked ? "border-accent bg-accent" : "border-border-strong bg-bg")}>
              <span className={cn("size-1.5 rounded-full bg-accent-fg transition-transform", checked ? "scale-100" : "scale-0")} />
            </span>
            <span className="space-y-0.5">
              <span className="block text-sm font-medium text-fg">{o.label}</span>
              {o.description && <span className="block text-xs text-fg-muted">{o.description}</span>}
            </span>
          </label>
        );
      })}
    </div>
  );
}

components/ui/resizable.tsx.source:
"use client";

import * as React from "react";
import { cn } from "../../lib/cn";

/**
 * ResizablePanels
 * Two or more panels with draggable handles between them — chat beside a canvas,
 * a file tree beside a preview. Sizes are percentages; min sizes are respected.
 * Handles are keyboard accessible (arrow keys ±5%, Home/End to min/max) and
 * double-click resets to the default layout.
 */
export interface ResizablePanelsProps {
  children: React.ReactNode[];
  direction?: "horizontal" | "vertical";
  /** Percent sizes, must add up to 100. Defaults to equal. */
  defaultSizes?: number[];
  /** Percent minimums per panel (default 15) */
  minSizes?: number[];
  onResize?: (sizes: number[]) => void;
  /** Accessible names for the panels, used by the handles */
  labels?: string[];
  className?: string;
}

export function ResizablePanels({ children, direction = "horizontal", defaultSizes, minSizes, onResize, labels, className }: ResizablePanelsProps) {
  const n = children.length;
  const initial = defaultSizes ?? Array(n).fill(100 / n);
  const [sizes, setSizes] = React.useState<number[]>(initial);
  const root = React.useRef<HTMLDivElement>(null);
  const [drag, setDrag] = React.useState<number | null>(null);
  const horizontal = direction === "horizontal";
  const minOf = (i: number) => minSizes?.[i] ?? 15;

  const update = (next: number[]) => { setSizes(next); onResize?.(next); };

  /** Move the boundary after panel i by delta percent, clamped to both mins */
  const shift = (i: number, delta: number, base = sizes) => {
    const pair = base[i] + base[i + 1];
    const a = Math.min(Math.max(base[i] + delta, minOf(i)), pair - minOf(i + 1));
    const next = [...base]; next[i] = a; next[i + 1] = pair - a;
    update(next);
  };

  const onPointerDown = (i: number) => (e: React.PointerEvent) => {
    e.preventDefault();
    (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);
    const rect = root.current!.getBoundingClientRect();
    const total = horizontal ? rect.width : rect.height;
    const start = horizontal ? e.clientX : e.clientY;
    const base = sizes;
    setDrag(i);
    const move = (ev: PointerEvent) => shift(i, (((horizontal ? ev.clientX : ev.clientY) - start) / total) * 100, base);
    const up = () => { setDrag(null); window.removeEventListener("pointermove", move); window.removeEventListener("pointerup", up); };
    window.addEventListener("pointermove", move);
    window.addEventListener("pointerup", up);
  };

  return (
    <div ref={root} className={cn("flex h-full w-full overflow-hidden", horizontal ? "flex-row" : "flex-col", drag !== null && (horizontal ? "cursor-col-resize select-none" : "cursor-row-resize select-none"), className)}>
      {children.map((child, i) => (
        <React.Fragment key={i}>
          <div className="min-h-0 min-w-0 overflow-auto" style={{ flexBasis: `${sizes[i]}%`, flexGrow: 0, flexShrink: 0 }}>{child}</div>
          {i < n - 1 && (
            <div
              role="separator"
              tabIndex={0}
              aria-orientation={horizontal ? "vertical" : "horizontal"}
              aria-valuenow={Math.round(sizes[i])}
              aria-valuemin={minOf(i)}
              aria-valuemax={Math.round(sizes[i] + sizes[i + 1] - minOf(i + 1))}
              aria-label={labels ? `Resize ${labels[i]}` : "Resize panels"}
              onPointerDown={onPointerDown(i)}
              onDoubleClick={() => update(initial)}
              onKeyDown={(e) => {
                const back = horizontal ? "ArrowLeft" : "ArrowUp", fwd = horizontal ? "ArrowRight" : "ArrowDown";
                if (e.key === back) { e.preventDefault(); shift(i, e.shiftKey ? -10 : -5); }
                else if (e.key === fwd) { e.preventDefault(); shift(i, e.shiftKey ? 10 : 5); }
                else if (e.key === "Home") { e.preventDefault(); shift(i, -100); }
                else if (e.key === "End") { e.preventDefault(); shift(i, 100); }
                else if (e.key === "Enter") { e.preventDefault(); update(initial); }
              }}
              className={cn("group relative z-10 flex shrink-0 touch-none items-center justify-center bg-border outline-none transition-colors hover:bg-fg/30 focus-visible:bg-fg/50",
                horizontal ? "w-px cursor-col-resize" : "h-px cursor-row-resize", drag === i && "bg-fg/50")}
            >
              {/* Larger invisible hit area */}
              <span aria-hidden className={cn("absolute", horizontal ? "inset-y-0 -left-1.5 -right-1.5" : "inset-x-0 -top-1.5 -bottom-1.5")} />
              <span aria-hidden className={cn("relative shrink-0 rounded-full border border-border bg-bg shadow-xs", horizontal ? "h-6 w-2.5" : "h-2.5 w-6")}>
                <span className={cn("absolute inset-0 m-auto rounded-full bg-fg-subtle", horizontal ? "h-3 w-px" : "h-px w-3")} />
              </span>
            </div>
          )}
        </React.Fragment>
      ))}
    </div>
  );
}

components/ui/scroll-area.tsx.source:
"use client";

import * as React from "react";
import { cn } from "../../lib/cn";

/**
 * ScrollArea
 * Scroll container with thin themed scrollbars and edge fades that appear only when there's
 * more content in that direction — a quiet hint that the list continues.
 */
export function ScrollArea({ className, children, maxHeight, orientation = "vertical", fade = true, ...p }: React.HTMLAttributes<HTMLDivElement> & { maxHeight?: number | string; orientation?: "vertical" | "horizontal"; fade?: boolean }) {
  const ref = React.useRef<HTMLDivElement>(null);
  const [edges, setEdges] = React.useState({ start: false, end: false });
  const update = React.useCallback(() => {
    const el = ref.current; if (!el) return;
    const v = orientation === "vertical";
    const pos = v ? el.scrollTop : el.scrollLeft, size = v ? el.scrollHeight - el.clientHeight : el.scrollWidth - el.clientWidth;
    setEdges({ start: pos > 2, end: pos < size - 2 });
  }, [orientation]);
  React.useEffect(() => { update(); const ro = new ResizeObserver(update); if (ref.current) ro.observe(ref.current); return () => ro.disconnect(); }, [update]);
  const v = orientation === "vertical";
  const mask = fade ? `linear-gradient(${v ? "to bottom" : "to right"}, ${edges.start ? "transparent" : "#000"} 0, #000 24px, #000 calc(100% - 24px), ${edges.end ? "transparent" : "#000"} 100%)` : undefined;
  return (
    <div
      ref={ref}
      onScroll={update}
      tabIndex={0}
      className={cn(
        "relative focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-fg/20",
        v ? "overflow-y-auto overflow-x-hidden" : "overflow-x-auto overflow-y-hidden",
        "[scrollbar-color:rgb(var(--border-strong))_transparent] [scrollbar-width:thin] [&::-webkit-scrollbar]:size-2 [&::-webkit-scrollbar-thumb]:rounded-full [&::-webkit-scrollbar-thumb]:bg-border-strong",
        className
      )}
      style={{ maxHeight, WebkitMaskImage: mask, maskImage: mask }}
      {...p}
    >
      {children}
    </div>
  );
}

components/ui/select.tsx.source:
"use client";

import * as React from "react";
import { Check, ChevronsUpDown } from "lucide-react";
import { cn } from "../../lib/cn";
import { useFloating, useOutside, Portal, floatingPanel } from "../../lib/floating";

/**
 * Select
 * Pick one option from a list of up to ~15. For longer lists or free text, use Combobox.
 * Options can have descriptions, icons and groups. Keyboard: ↑ ↓ Home End, type-ahead, Enter, Esc.
 */
export interface SelectOption { value: string; label: string; description?: string; icon?: React.ReactNode; group?: string; disabled?: boolean }

export interface SelectProps {
  options: SelectOption[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  placeholder?: string;
  disabled?: boolean;
  size?: "sm" | "md";
  id?: string;
  "aria-label"?: string;
  "aria-invalid"?: boolean;
  className?: string;
}

export function Select({ options, value, defaultValue, onValueChange, placeholder = "Select…", disabled, size = "md", id, className, ...aria }: SelectProps) {
  const [inner, setInner] = React.useState(defaultValue);
  const current = value ?? inner;
  const [open, setOpen] = React.useState(false);
  const [active, setActive] = React.useState(0);
  const fl = useFloating({ open, side: "bottom", align: "start", offset: 4, matchWidth: true });
  const listId = React.useId();
  const buf = React.useRef({ s: "", t: 0 });
  useOutside(open, () => setOpen(false), [fl.anchor, fl.floating]);
  const sel = options.find((o) => o.value === current);
  const enabled = options.map((o, i) => (o.disabled ? -1 : i)).filter((i) => i >= 0);

  const openList = () => { setActive(Math.max(0, options.findIndex((o) => o.value === current))); setOpen(true); };
  const pick = (i: number) => { const o = options[i]; if (!o || o.disabled) return; setInner(o.value); onValueChange?.(o.value); setOpen(false); (fl.anchor.current as HTMLElement)?.focus(); };
  const move = (d: number) => { const p = enabled.indexOf(active); setActive(enabled[Math.max(0, Math.min(enabled.length - 1, p + d))]); };
  React.useEffect(() => { if (open) document.getElementById(`${listId}-${active}`)?.scrollIntoView({ block: "nearest" }); }, [active, open, listId]);

  let lastGroup: string | undefined;
  return (
    <>
      <button
        id={id}
        ref={(el) => { fl.anchor.current = el; }}
        type="button"
        role="combobox"
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-controls={listId}
        aria-activedescendant={open ? `${listId}-${active}` : undefined}
        disabled={disabled}
        onClick={() => (open ? setOpen(false) : openList())}
        onKeyDown={(e) => {
          if (!open && ["ArrowDown", "ArrowUp", "Enter", " "].includes(e.key)) { e.preventDefault(); openList(); return; }
          if (!open) return;
          if (e.key === "ArrowDown") { e.preventDefault(); move(1); }
          else if (e.key === "ArrowUp") { e.preventDefault(); move(-1); }
          else if (e.key === "Home") { e.preventDefault(); setActive(enabled[0]); }
          else if (e.key === "End") { e.preventDefault(); setActive(enabled[enabled.length - 1]); }
          else if (e.key === "Enter" || e.key === " ") { e.preventDefault(); pick(active); }
          else if (e.key === "Tab") setOpen(false);
          else if (e.key.length === 1) {
            const now = Date.now();
            buf.current = { s: (now - buf.current.t < 500 ? buf.current.s : "") + e.key.toLowerCase(), t: now };
            const hit = enabled.find((i) => options[i].label.toLowerCase().startsWith(buf.current.s));
            if (hit != null) setActive(hit);
          }
        }}
        className={cn(
          "flex w-full min-w-0 items-center gap-2 rounded-md border border-border bg-bg px-3 text-left text-base shadow-xs transition-[border-color,box-shadow] focus-visible:border-border-strong focus-visible:outline-none focus-visible:ring-4 focus-visible:ring-fg/5 disabled:cursor-not-allowed disabled:opacity-50 aria-[invalid=true]:border-danger/60 [&_svg]:size-4 [&_svg]:shrink-0",
          size === "sm" ? "h-8 text-sm" : "h-9",
          className
        )}
        {...aria}
      >
        {sel?.icon && <span className="text-fg-muted">{sel.icon}</span>}
        <span className={cn("flex-1 truncate", !sel && "text-fg-subtle")}>{sel?.label ?? placeholder}</span>
        <ChevronsUpDown className="text-fg-subtle" />
      </button>
      {open && (
        <Portal>
          <ul
            id={listId}
            role="listbox"
            ref={(el) => { fl.floating.current = el; }}
            style={{ ...fl.style, animation: "pl-pop .12s var(--ease-out)" }}
            className={cn(floatingPanel, "max-h-72 overflow-y-auto p-1")}
          >
            {options.map((o, i) => {
              const header = o.group && o.group !== lastGroup;
              lastGroup = o.group;
              return (
                <React.Fragment key={o.value}>
                  {header && <li role="presentation" className="px-2 pb-1 pt-2 text-xs font-medium text-fg-subtle">{o.group}</li>}
                  <li
                    id={`${listId}-${i}`}
                    role="option"
                    aria-selected={o.value === current}
                    aria-disabled={o.disabled || undefined}
                    onMouseEnter={() => !o.disabled && setActive(i)}
                    onMouseDown={(e) => e.preventDefault()}
                    onClick={() => pick(i)}
                    className={cn("flex cursor-default items-center gap-2 rounded-sm px-2 py-1.5 text-sm [&_svg]:size-4", i === active && "bg-surface-2", o.disabled && "opacity-40")}
                  >
                    {o.icon && <span className="text-fg-muted">{o.icon}</span>}
                    <span className="min-w-0 flex-1">
                      <span className="block truncate text-fg">{o.label}</span>
                      {o.description && <span className="block truncate text-xs text-fg-subtle">{o.description}</span>}
                    </span>
                    {o.value === current && <Check className="text-fg" />}
                  </li>
                </React.Fragment>
              );
            })}
          </ul>
        </Portal>
      )}
    </>
  );
}

components/ui/separator.tsx.source:
import * as React from "react";
import { cn } from "../../lib/cn";

/**
 * Separator
 * Hairline divider. Pass `label` for "or" dividers in forms. Decorative by default.
 */
export function Separator({ className, vertical, label, decorative = true }: { className?: string; vertical?: boolean; label?: React.ReactNode; decorative?: boolean }) {
  const a11y = decorative ? { role: "none" as const } : { role: "separator" as const, "aria-orientation": vertical ? ("vertical" as const) : ("horizontal" as const) };
  if (label && !vertical)
    return (
      <div {...a11y} className={cn("flex items-center gap-3 text-xs text-fg-subtle", className)}>
        <span className="h-px flex-1 bg-border" />{label}<span className="h-px flex-1 bg-border" />
      </div>
    );
  return <div {...a11y} className={cn("shrink-0 bg-border", vertical ? "h-full w-px self-stretch" : "h-px w-full", className)} />;
}

components/ui/sheet.tsx.source:
"use client";

import * as React from "react";
import { createPortal } from "react-dom";
import { X } from "lucide-react";
import { cn } from "../../lib/cn";

/**
 * Sheet
 * A panel that slides in from an edge — settings, filters, artifact panels, mobile navigation.
 * `side="bottom"` becomes a drawer with a grab handle on phones.
 * Focus is trapped while open and returned to the trigger on close.
 */
export interface SheetProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  side?: "right" | "left" | "bottom";
  title?: React.ReactNode;
  description?: React.ReactNode;
  footer?: React.ReactNode;
  children?: React.ReactNode;
  /** Hide the built-in close button (when the content has its own) */
  showClose?: boolean;
  className?: string;
}

export function Sheet({ open, onOpenChange, side = "right", title, description, footer, children, showClose = true, className }: SheetProps) {
  const ref = React.useRef<HTMLDivElement>(null);
  const change = React.useRef(onOpenChange);
  change.current = onOpenChange;
  const [render, setRender] = React.useState(open);
  const [shown, setShown] = React.useState(false);
  React.useEffect(() => {
    if (open) { setRender(true); requestAnimationFrame(() => requestAnimationFrame(() => setShown(true))); }
    else { setShown(false); const t = setTimeout(() => setRender(false), 220); return () => clearTimeout(t); }
  }, [open]);
  React.useEffect(() => {
    if (!open) return;
    const prev = document.activeElement as HTMLElement | null;
    const t = setTimeout(() => ref.current?.querySelector<HTMLElement>("input, textarea, select, button:not([data-close])")?.focus() ?? ref.current?.focus(), 30);
    const key = (e: KeyboardEvent) => {
      if (e.key === "Escape") change.current(false);
      if (e.key === "Tab" && ref.current) {
        const f = Array.from(ref.current.querySelectorAll<HTMLElement>("button, [href], input, textarea, select, [tabindex]:not([tabindex='-1'])"));
        if (!f.length) return;
        if (e.shiftKey && document.activeElement === f[0]) { e.preventDefault(); f[f.length - 1].focus(); }
        else if (!e.shiftKey && document.activeElement === f[f.length - 1]) { e.preventDefault(); f[0].focus(); }
      }
    };
    document.addEventListener("keydown", key);
    const o = document.body.style.overflow; document.body.style.overflow = "hidden";
    return () => { clearTimeout(t); document.removeEventListener("keydown", key); document.body.style.overflow = o; prev?.focus?.(); };
  }, [open]);

  if (!render) return null;
  const pos = {
    right: cn("inset-y-0 right-0 h-full w-full max-w-md border-l", shown ? "translate-x-0" : "translate-x-full"),
    left: cn("inset-y-0 left-0 h-full w-full max-w-md border-r", shown ? "translate-x-0" : "-translate-x-full"),
    bottom: cn("inset-x-0 bottom-0 max-h-[85vh] w-full rounded-t-xl border-t", shown ? "translate-y-0" : "translate-y-full"),
  }[side];

  return createPortal(
    <div className="fixed inset-0 z-[100]">
      <div className={cn("absolute inset-0 bg-black/40 transition-opacity duration-200", shown ? "opacity-100" : "opacity-0")} onClick={() => onOpenChange(false)} aria-hidden />
      <div ref={ref} role="dialog" aria-modal="true" tabIndex={-1} className={cn("absolute flex flex-col border-border bg-bg shadow-lg outline-none transition-transform duration-200 ease-out", pos, className)}>
        {side === "bottom" && <div className="mx-auto mt-3 h-1 w-10 shrink-0 rounded-full bg-border-strong" aria-hidden />}
        {(title || description) && (
          <div className="shrink-0 space-y-1 p-6 pb-4 pr-14">
            {title && <h2 className="text-xl font-semibold text-fg">{title}</h2>}
            {description && <p className="text-base text-fg-muted">{description}</p>}
          </div>
        )}
        {showClose && <button type="button" data-close onClick={() => onOpenChange(false)} aria-label="Close" className="absolute right-4 top-4 grid size-8 place-items-center rounded-sm text-fg-subtle hover:bg-surface-2 hover:text-fg"><X className="size-4" /></button>}
        <div className="min-h-0 flex-1 overflow-y-auto px-6 pb-6">{children}</div>
        {footer && <div className="flex shrink-0 justify-end gap-2 border-t border-border bg-surface px-6 py-4">{footer}</div>}
      </div>
    </div>,
    document.body
  );
}

