}
export function TCaption({ className, ...p }: React.HTMLAttributes<HTMLTableCaptionElement>) {
  return <caption className={cn("py-3 text-xs text-fg-subtle", className)} {...p} />;
}

components/ui/tabs.tsx.source:
"use client";

import * as React from "react";
import { cn } from "../../lib/cn";

/**
 * Tabs
 * Switch between views of the same thing. Three styles: underline (page sections),
 * segmented (compact toggles like Preview / Code) and pills.
 * Arrow keys move between tabs (automatic activation), Home/End jump to ends.
 */
export interface TabItem { value: string; label: React.ReactNode; icon?: React.ReactNode; badge?: React.ReactNode; disabled?: boolean; content?: React.ReactNode }

export interface TabsProps {
  items: TabItem[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (v: string) => void;
  variant?: "underline" | "segmented" | "pills";
  size?: "sm" | "md";
  fullWidth?: boolean;
  className?: string;
  /** Rendered at the right end of the tab list */
  actions?: React.ReactNode;
}

export function Tabs({ items, value, defaultValue, onValueChange, variant = "underline", size = "md", fullWidth, className, actions }: TabsProps) {
  const [inner, setInner] = React.useState(defaultValue ?? items[0]?.value);
  const cur = value ?? inner;
  const id = React.useId();
  const refs = React.useRef<(HTMLButtonElement | null)[]>([]);
  const enabled = items.map((t, i) => (t.disabled ? -1 : i)).filter((i) => i >= 0);
  const select = (i: number) => { const t = items[i]; setInner(t.value); onValueChange?.(t.value); refs.current[i]?.focus(); };
  const active = items.find((t) => t.value === cur);

  const list = {
    underline: "gap-6 border-b border-border",
    segmented: "gap-0.5 rounded-md bg-surface-2 p-0.5",
    pills: "gap-1",
  }[variant];
  const tab = (on: boolean) => ({
    underline: cn("-mb-px border-b-2 px-0.5", size === "sm" ? "h-9" : "h-10", on ? "border-fg text-fg" : "border-transparent text-fg-muted hover:text-fg"),
    segmented: cn("rounded-sm px-3", size === "sm" ? "h-7" : "h-8", on ? "bg-bg text-fg shadow-xs" : "text-fg-muted hover:text-fg"),
    pills: cn("rounded-full px-3", size === "sm" ? "h-7" : "h-8", on ? "bg-fg text-bg" : "text-fg-muted hover:bg-surface-2 hover:text-fg"),
  }[variant]);

  return (
    <div className={className}>
      <div className={cn("flex items-center", variant === "underline" && "border-b border-border")}>
        <div
          role="tablist"
          className={cn("flex min-w-0 items-center overflow-x-auto [scrollbar-width:none]", list, variant === "underline" && "border-b-0", fullWidth && "w-full [&>*]:flex-1")}
          onKeyDown={(e) => {
            const i = items.findIndex((t) => t.value === cur);
            const p = enabled.indexOf(i);
            if (e.key === "ArrowRight") { e.preventDefault(); select(enabled[(p + 1) % enabled.length]); }
            if (e.key === "ArrowLeft") { e.preventDefault(); select(enabled[(p - 1 + enabled.length) % enabled.length]); }
            if (e.key === "Home") { e.preventDefault(); select(enabled[0]); }
            if (e.key === "End") { e.preventDefault(); select(enabled[enabled.length - 1]); }
          }}
        >
          {items.map((t, i) => {
            const on = t.value === cur;
            return (
              <button
                key={t.value}
                ref={(el) => { refs.current[i] = el; }}
                id={`${id}-t-${t.value}`}
                role="tab"
                type="button"
                aria-selected={on}
                aria-controls={t.content !== undefined ? `${id}-p-${t.value}` : undefined}
                tabIndex={on ? 0 : -1}
                disabled={t.disabled}
                onClick={() => select(i)}
                className={cn("inline-flex shrink-0 items-center justify-center gap-2 whitespace-nowrap font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-fg/20 disabled:opacity-40 [&_svg]:size-4", size === "sm" ? "text-sm" : "text-sm", tab(on))}
              >
                {t.icon}{t.label}{t.badge}
              </button>
            );
          })}
        </div>
        {actions && <div className="ml-auto flex items-center gap-1 pl-4">{actions}</div>}
      </div>
      {active?.content !== undefined && (
        <div key={active.value} id={`${id}-p-${active.value}`} role="tabpanel" aria-labelledby={`${id}-t-${active.value}`} tabIndex={0} className="pt-4 focus-visible:outline-none" style={{ animation: "pl-in .15s ease-out" }}>
          {active.content}
        </div>
      )}
    </div>
  );
}

components/ui/tags-input.tsx.source:
"use client";

import * as React from "react";
import { X } from "lucide-react";
import { cn } from "../../lib/cn";

/**
 * TagsInput
 * Type and press Enter or comma to add a tag. Paste a list and it splits on commas and new lines.
 * Backspace on an empty field selects the last tag, a second Backspace removes it.
 * Duplicates are ignored, `validate` can reject a value with a message, and `max` caps the count.
 */
export interface TagsInputProps {
  value: string[];
  onValueChange: (tags: string[]) => void;
  placeholder?: string;
  max?: number;
  /** Return an error message to reject a tag */
  validate?: (tag: string) => string | undefined;
  /** Keys that commit the current text (default Enter and ",") */
  separators?: string[];
  disabled?: boolean;
  id?: string;
  className?: string;
  "aria-label"?: string;
  "aria-describedby"?: string;
  "aria-invalid"?: boolean;
}

export function TagsInput({ value, onValueChange, placeholder = "Add…", max, validate, separators = ["Enter", ","], disabled, id, className, ...aria }: TagsInputProps) {
  const [text, setText] = React.useState("");
  const [error, setError] = React.useState<string>();
  const [armed, setArmed] = React.useState(false);
  const input = React.useRef<HTMLInputElement>(null);
  const full = max != null && value.length >= max;

  const add = (raw: string[]) => {
    const next = [...value];
    let err: string | undefined;
    for (const r of raw) {
      const t = r.trim();
      if (!t || next.includes(t)) continue;
      if (max != null && next.length >= max) { err = `Up to ${max} allowed`; break; }
      const e = validate?.(t);
      if (e) { err = e; continue; }
      next.push(t);
    }
    if (next.length !== value.length) onValueChange(next);
    setError(err);
    return !err;
  };

  const remove = (i: number) => { onValueChange(value.filter((_, j) => j !== i)); input.current?.focus(); };

  return (
    <div className={cn("w-full", className)}>
      <div
        onClick={() => input.current?.focus()}
        className={cn("flex min-h-9 w-full cursor-text flex-wrap items-center gap-1.5 rounded-md border bg-bg px-1.5 py-1 text-sm shadow-xs transition-[border-color,box-shadow] focus-within:border-border-strong focus-within:ring-4 focus-within:ring-fg/5",
          error ? "border-danger/50" : "border-border", disabled && "pointer-events-none opacity-50")}
      >
        {value.map((t, i) => (
          <span key={t} className={cn("inline-flex h-6 max-w-full items-center gap-1 rounded-sm bg-surface-2 pl-2 pr-0.5 text-sm text-fg transition-shadow", armed && i === value.length - 1 && "ring-2 ring-fg/30")}>
            <span className="truncate">{t}</span>
            <button type="button" tabIndex={-1} onClick={(e) => { e.stopPropagation(); remove(i); }} aria-label={`Remove ${t}`} className="grid size-5 place-items-center rounded-xs text-fg-subtle hover:bg-border hover:text-fg"><X className="size-3" /></button>
          </span>
        ))}
        <input
          ref={input}
          id={id}
          value={text}
          disabled={disabled || full}
          placeholder={full ? `Limit of ${max} reached` : value.length ? "" : placeholder}
          {...aria}
          aria-invalid={!!error || aria["aria-invalid"] || undefined}
          aria-describedby={[error ? `${id ?? "tags"}-err` : "", aria["aria-describedby"] ?? ""].filter(Boolean).join(" ") || undefined}
          onChange={(e) => { setText(e.target.value); setArmed(false); if (error) setError(undefined); }}
          onBlur={() => { if (text.trim() && add([text])) setText(""); setArmed(false); }}
          onPaste={(e) => {
            const s = e.clipboardData.getData("text");
            if (/[,\n\t]/.test(s)) { e.preventDefault(); add(s.split(/[,\n\t]/)); }
          }}
          onKeyDown={(e) => {
            if (separators.includes(e.key) && !e.nativeEvent.isComposing) {
              if (text.trim()) { e.preventDefault(); if (add([text])) setText(""); }
              else if (e.key !== "Enter") e.preventDefault();
            } else if (e.key === "Backspace" && !text && value.length) {
              e.preventDefault();
              if (armed) { remove(value.length - 1); setArmed(false); } else setArmed(true);
            } else if (e.key === "Escape") setArmed(false);
          }}
          className="h-6 min-w-[6rem] flex-1 bg-transparent px-1 text-sm text-fg placeholder:text-fg-subtle focus:outline-none disabled:cursor-not-allowed"
        />
      </div>
      <div className="mt-1.5 flex justify-between gap-3 text-xs">
        <p id={`${id ?? "tags"}-err`} className="text-danger" aria-live="polite">{error}</p>
        {max != null && <p className={cn("shrink-0 tabular-nums", full ? "text-fg-muted" : "text-fg-subtle")}>{value.length}/{max}</p>}
      </div>
    </div>
  );
}

components/ui/textarea.tsx.source:
"use client";

import * as React from "react";
import { cn } from "../../lib/cn";
import { inputBase } from "./input";

/**
 * Textarea
 * Multi-line input. `autoResize` grows with content up to `maxRows`. `showCount` with maxLength shows a counter.
 */
export interface TextareaProps extends React.TextareaHTMLAttributes<HTMLTextAreaElement> {
  autoResize?: boolean;
  maxRows?: number;
  showCount?: boolean;
}

export const Textarea = React.forwardRef<HTMLTextAreaElement, TextareaProps>(({ className, autoResize, maxRows = 12, showCount, maxLength, onChange, value, defaultValue, rows = 3, ...p }, ref) => {
  const inner = React.useRef<HTMLTextAreaElement>(null);
  React.useImperativeHandle(ref, () => inner.current!);
  const [count, setCount] = React.useState(String(value ?? defaultValue ?? "").length);
  const resize = () => {
    const el = inner.current;
    if (!el || !autoResize) return;
    el.style.height = "auto";
    el.style.height = Math.min(el.scrollHeight, maxRows * 20 + 18) + "px";
  };
  React.useLayoutEffect(resize, [value, autoResize, maxRows]);
  return (
    <div className="relative w-full">
      <textarea
        ref={inner}
        rows={rows}
        value={value}
        defaultValue={defaultValue}
        maxLength={maxLength}
        onChange={(e) => { setCount(e.target.value.length); resize(); onChange?.(e); }}
        className={cn(inputBase, "block min-h-16 resize-y py-2", autoResize && "resize-none", showCount && "pb-6", className)}
        {...p}
      />
      {showCount && maxLength && (
        <span className={cn("pointer-events-none absolute bottom-2 right-3 text-xs tabular-nums", count >= maxLength ? "text-danger" : "text-fg-subtle")}>{count}/{maxLength}</span>
      )}
    </div>
  );
});
Textarea.displayName = "Textarea";

components/ui/toggle.tsx.source:
"use client";

import * as React from "react";
import { cn } from "../../lib/cn";

/**
 * Toggle & ToggleGroup
 * Pressed/unpressed buttons for formatting, view modes and filters.
 * ToggleGroup type="single" behaves like a segmented control; "multiple" like a set of switches.
 */
export interface ToggleProps extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "onChange"> {
  pressed?: boolean;
  defaultPressed?: boolean;
  onPressedChange?: (pressed: boolean) => void;
  size?: "sm" | "md";
  variant?: "ghost" | "outline";
}

const toggleCls = (on: boolean, size: "sm" | "md", variant: "ghost" | "outline") =>
  cn(
    "inline-flex shrink-0 items-center justify-center gap-1.5 rounded-sm font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-fg/20 disabled:pointer-events-none disabled:opacity-40 [&_svg]:size-4",
    size === "sm" ? "h-8 min-w-8 px-2 text-sm" : "h-9 min-w-9 px-2.5 text-base",
    variant === "outline" && "border border-border shadow-xs",
    on ? "bg-surface-2 text-fg" : "text-fg-muted hover:bg-surface-2/60 hover:text-fg"
  );

export function Toggle({ pressed, defaultPressed, onPressedChange, size = "md", variant = "ghost", className, ...p }: ToggleProps) {
  const [inner, setInner] = React.useState(!!defaultPressed);
  const on = pressed ?? inner;
  return <button type="button" aria-pressed={on} onClick={() => { setInner(!on); onPressedChange?.(!on); }} className={cn(toggleCls(on, size, variant), className)} {...p} />;
}

export interface ToggleGroupItem { value: string; label: React.ReactNode; "aria-label"?: string; disabled?: boolean }

export function ToggleGroup({ type = "single", items, value, defaultValue, onValueChange, size = "md", variant = "outline", className }: {
  type?: "single" | "multiple";
  items: ToggleGroupItem[];
  value?: string | string[];
  defaultValue?: string | string[];
  onValueChange?: (v: any) => void;
  size?: "sm" | "md";
  variant?: "ghost" | "outline" | "segmented";
  className?: string;
}) {
  const [inner, setInner] = React.useState<string | string[]>(defaultValue ?? (type === "single" ? "" : []));
  const cur = value ?? inner;
  const isOn = (v: string) => (Array.isArray(cur) ? cur.includes(v) : cur === v);
  const set = (v: string) => {
    const next = type === "single" ? v : Array.isArray(cur) && cur.includes(v) ? cur.filter((x) => x !== v) : [...(cur as string[]), v];
    setInner(next); onValueChange?.(next);
  };
  const refs = React.useRef<(HTMLButtonElement | null)[]>([]);
  const seg = variant === "segmented";
  return (
    <div
      role={type === "single" ? "radiogroup" : "group"}
      className={cn("inline-flex items-center", seg ? "gap-0.5 rounded-md bg-surface-2 p-0.5" : variant === "outline" ? "rounded-md border border-border p-0.5 shadow-xs" : "gap-1", className)}
      onKeyDown={(e) => {
        const i = refs.current.findIndex((r) => r === document.activeElement);
        if (i < 0) return;
        if (e.key === "ArrowRight") { e.preventDefault(); refs.current[(i + 1) % items.length]?.focus(); }
        if (e.key === "ArrowLeft") { e.preventDefault(); refs.current[(i - 1 + items.length) % items.length]?.focus(); }
      }}
    >
      {items.map((it, i) => {
        const on = isOn(it.value);
        return (
          <button
            key={it.value}
            ref={(el) => { refs.current[i] = el; }}
            type="button"
            role={type === "single" ? "radio" : undefined}
            aria-checked={type === "single" ? on : undefined}
            aria-pressed={type === "multiple" ? on : undefined}
            aria-label={it["aria-label"]}
            disabled={it.disabled}
            onClick={() => set(it.value)}
            className={cn(toggleCls(on, size, "ghost"), seg && on && "bg-bg text-fg shadow-xs", seg && !on && "hover:bg-transparent")}
          >
            {it.label}
          </button>
        );
      })}
    </div>
  );
}

components/ui/tooltip.tsx.source:
import * as React from "react";
import { cn } from "../../lib/cn";

/**
 * Tooltip
 * Short label for icon buttons and truncated text. Shows on hover and keyboard focus.
 * Keep it to a few words; never put interactive content in a tooltip (use HoverCard).
 */
export interface TooltipProps {
  label: React.ReactNode;
  side?: "top" | "bottom";
  align?: "center" | "start" | "end";
  children: React.ReactNode;
  className?: string;
}

export function Tooltip({ label, side = "top", align = "center", children, className }: TooltipProps) {
  return (
    <span className={cn("group/tt relative inline-flex", className)}>
      {children}
      <span
        role="tooltip"
        className={cn(
          "pointer-events-none absolute z-50 hidden whitespace-nowrap rounded-sm bg-fg px-2 py-1 text-xs font-medium text-bg shadow-sm group-hover/tt:block group-focus-within/tt:block",
          side === "top" ? "bottom-full mb-2" : "top-full mt-2",
          align === "center" ? "left-1/2 -translate-x-1/2" : align === "start" ? "left-0" : "right-0"
        )}
        style={{ animation: "pl-in .12s ease-out" }}
      >
        {label}
      </span>
    </span>
  );
}

